  insert into amusq.subjects (name, color, icon, descr, topics, exam_date, published, free, ord)
insert into amusq.questions
  (subject_id, ord, q, options, answer, expl_ar, expl_en, translation, mnemonic, topic, derived, opts_built, important)
values
  ((select id from s), 1, 'Which clinical feature is most characteristic of ketamine toxicity?', '["Severe diarrhea","Dissociation","Bradycardia","Miosis"]'::jsonb, 1, 'الكيتامين مخدّر انفصالي يعمل بحصر مستقبلات NMDA، فيفصل الإدراك عن الإحساس ويظهر المريض شاخصًا غائبًا عن محيطه. الإسهال الشديد ليس من صورته إطلاقًا، وبطء القلب خاطئ لأن الكيتامين يرفع النبض والضغط بتنشيطه الودّي، وتضيّق الحدقة علامة الأفيونات لا الكيتامين الذي يوسّع الحدقة. المعلومة المفتاحية: الانفصال + توسّع الحدقة + تسرّع القلب = كيتامين.', 'Ketamine is a dissociative anaesthetic that blocks NMDA receptors, so perception is separated from sensation and the patient appears awake but detached from the environment. Severe diarrhea is not part of its profile at all; bradycardia is wrong because ketamine''s sympathomimetic effect raises heart rate and blood pressure; miosis points to opioids, whereas ketamine causes pupil dilation. Key point: dissociation plus mydriasis plus tachycardia equals ketamine.', 'أي علامة سريرية هي الأكثر تميّزًا لتسمّم الكيتامين؟', '{}'::jsonb, 'المهلوسات والمواد النفسية', false, false, false),
  ((select id from s), 2, 'Herbal remedies are primarily derived from:', '["Synthetic chemicals","Plants","Animal products","Minerals"]'::jsonb, 1, 'العلاجات العشبية بتعريفها مستحضرات مصدرها الأجزاء النباتية من أوراق وجذور وبذور وأزهار. المواد الكيميائية المُصنّعة هي مصدر الأدوية الدوائية لا العشبية، والمنتجات الحيوانية والمعادن قد تدخل في مستحضرات تقليدية أخرى لكنها ليست تعريف العلاج العشبي. المعلومة المفتاحية: عشبي = نباتي المصدر.', 'Herbal remedies are by definition preparations derived from plants — leaves, roots, seeds, bark and flowers — and their active compounds are plant secondary metabolites. Synthetic chemicals are the source of manufactured pharmaceuticals rather than herbal products; animal products and minerals appear in other traditional preparations but neither defines a herbal remedy. Key point: herbal means plant-derived.', 'تُستخلص العلاجات العشبية بالدرجة الأولى من:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 3, 'Which statement about herbal remedies is TRUE?', '["All herbal remedies are completely safe.","Herbal remedies cannot interact with prescription drugs.","Herbal remedies may cause toxicity and drug interactions.","Herbal remedies never cause poisoning."]'::jsonb, 2, 'الأعشاب تحوي مركّبات فعّالة دوائيًا حقيقية، لذلك تسبّب سُمّية مباشرة وتتداخل مع الأدوية الموصوفة كما في الجنكو مع الوارفارين ونبتة سانت جون مع مضادات الاكتئاب. عبارة أن جميعها آمنة تمامًا وعبارة أنها لا تسبّب التسمّم أبدًا كلتاهما خاطئتان لأن القفازيّة والدفلى قاتلتان، وعبارة عدم إمكان التداخل خاطئة لأن التداخلات موثّقة وخطيرة. المعلومة المفتاحية: الطبيعي لا يعني الآمن.', 'Herbal remedies may cause toxicity and drug interactions because they contain genuinely pharmacologically active compounds, as seen with ginkgo plus warfarin and St. John''s Wort plus antidepressants. The claim that all herbal remedies are completely safe and the claim that they never cause poisoning are both false, since foxglove and oleander can kill; the claim that they cannot interact with prescription drugs is false because such interactions are well documented and dangerous. Key point: natural does not mean safe.', 'أي عبارة عن العلاجات العشبية صحيحة؟', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 4, 'Which herbal remedy contains cardiac glycosides?', '["Kava","Foxglove (Digitalis)","Ginkgo biloba","Yohimbe"]'::jsonb, 1, 'القفازيّة هي المصدر النباتي الأصلي للديجيتاليس، وتحتوي غليكوزيدات قلبية تثبّط مضخة الصوديوم والبوتاسيوم فتسبّب بطء قلب واضطرابات نظم. الكافا مثبّطة للجهاز العصبي المركزي وسامّة للكبد لا للقلب بهذه الآلية، والجنكو بيلوبا يزيد خطر النزف، واليوهمبي منبّه ودّي يرفع الضغط. المعلومة المفتاحية: القفازيّة والدفلى فقط هما نبتتا الغليكوزيدات القلبية.', 'Foxglove, the plant source of digitalis, contains cardiac glycosides that inhibit the sodium-potassium pump and produce bradycardia, AV block and dysrhythmias. Kava is a central nervous system depressant with chronic liver toxicity rather than a cardiac glycoside plant; Ginkgo biloba inhibits platelet aggregation and raises bleeding risk; Yohimbe is a sympathetic stimulant that raises blood pressure. Key point: foxglove and oleander are the two classic cardiac glycoside plants.', 'أي علاج عشبي يحتوي على غليكوزيدات قلبية؟', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 5, 'Oleander poisoning most closely resembles toxicity from:', '["Acetaminophen","Digoxin","Aspirin","Morphine"]'::jsonb, 1, 'الدفلى تحتوي غليكوزيدات قلبية مماثلة في آليتها للديجوكسين، فتعطي الصورة نفسها: غثيان وقيء، واضطرابات بصرية، وبطء قلب مع حصار أذيني بطيني وفرط بوتاسيوم. الأسيتامينوفين تسمّمه كبدي متأخّر، والأسبرين يعطي حماضًا وطنينًا وفرط تهوية، والمورفين يعطي تثبيطًا تنفسيًا وتضيّق حدقة. المعلومة المفتاحية: دفلى = ديجوكسين نباتي.', 'Oleander contains cardiac glycosides with the same mechanism as digoxin, so it produces an identical picture of nausea and vomiting, visual disturbance, bradycardia with AV block and hyperkalemia. Acetaminophen toxicity is delayed hepatic injury; aspirin produces metabolic acidosis, tinnitus and hyperventilation; morphine produces respiratory depression with pinpoint pupils. Key point: oleander is digoxin in plant form.', 'يشبه تسمّم الدفلى إلى حدّ بعيد التسمّم بـ:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 6, 'Aconite poisoning is most likely to cause:', '["Hyperglycemia","Ventricular arrhythmias","Miosis","Hypothermia"]'::jsonb, 1, 'الأقونيطن يفتح قنوات الصوديوم في غشاء الخلية القلبية ويُبقيها مفتوحة، فيسبّب لاإستقرارًا كهربائيًا واضطرابات نظم بطينية قد تكون مميتة. ارتفاع سكر الدم ليس من صورته وهو أقرب لحاصرات الكالسيوم، وتضيّق الحدقة علامة أفيونية أو فسفورية عضوية، وانخفاض الحرارة ليس السمة المميّزة له. المعلومة المفتاحية: أقونيطن = خلل قنوات صوديوم = نظم بطيني خطير.', 'Aconite opens cardiac sodium channels and holds them open, producing electrical instability and ventricular arrhythmias that may be fatal. Hyperglycemia is not part of its picture and points instead to calcium channel blockers; miosis suggests opioids or organophosphates; hypothermia is not its characteristic feature. Key point: aconite is a sodium channel opener that causes dangerous ventricular rhythms.', 'التسمّم بالأقونيطن يسبّب على الأرجح:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 7, 'Which herb contains ephedrine-like compounds?', '["Ephedra (Ma Huang)","Kava","Ginkgo biloba","Aloe vera"]'::jsonb, 0, 'الإفيدرا المعروفة باسم ما هوانغ هي المصدر النباتي للإفيدرين والسودوإفيدرين، وهي منبّهات ودّية تُستعمل في مكمّلات إنقاص الوزن والطاقة. الكافا مثبّطة مركزية لا منبّهة، والجنكو بيلوبا يؤثّر على تكدّس الصفيحات والنزف، والصبّار مليّن هضمي وموضعي بلا فعل ودّي. المعلومة المفتاحية: ما هوانغ = الإفيدرين النباتي.', 'Ephedra, also known as Ma Huang, is the plant source of ephedrine and pseudoephedrine, sympathomimetic compounds used in weight-loss and energy supplements. Kava is a central depressant rather than a stimulant; Ginkgo biloba affects platelet aggregation and bleeding; Aloe vera acts as a gastrointestinal and topical agent with no sympathomimetic effect. Key point: Ma Huang is herbal ephedrine.', 'أي عشبة تحتوي على مركّبات شبيهة بالإفيدرين؟', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 8, 'Ephedra toxicity commonly presents with:', '["Bradycardia","Tachycardia and hypertension","Respiratory depression only","Hypothermia"]'::jsonb, 1, 'الإفيدرا منبّه ودّي مباشر وغير مباشر، فتعطي صورة الاندفاع الأدريناليني: تسرّع قلب وارتفاع ضغط وقلق ورعاش وأحيانًا اختلاج أو حادث دماغي. بطء القلب معاكس تمامًا لآليتها، والتثبيط التنفّسي صورة المثبّطات كالأفيونات لا المنبّهات، وانخفاض الحرارة خاطئ لأن المنبّهات ترفع الحرارة. المعلومة المفتاحية: إفيدرا = منبّه ودّي يرفع النبض والضغط.', 'Ephedra is a direct and indirect sympathomimetic, so it presents with tachycardia and hypertension along with anxiety, tremor and sometimes seizures or stroke. Bradycardia is the opposite of its mechanism; respiratory depression only is the picture of depressants such as opioids, not of stimulants; hypothermia is wrong because stimulants raise body temperature. Key point: ephedra is a sympathomimetic that drives up both pulse and blood pressure.', 'تظهر سُمّية الإفيدرا عادةً بـ:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 9, 'Kava toxicity primarily affects the:', '["Respiratory system","Central nervous system","Endocrine system","Hematologic system"]'::jsonb, 1, 'الكافا تُستعمل كمهدّئ ومزيل للقلق، وتأثيرها الحاد الأساسي تثبيط الجهاز العصبي المركزي مع نعاس وترنّح واضطراب توازن. الجهاز التنفّسي لا يتأثّر إلا ثانويًا في التثبيط الشديد وليس هو الهدف الأول، وجهاز الغدد الصمّاء غير معنيّ، والجهاز الدموي هو هدف الجنكو لا الكافا. المعلومة المفتاحية: كافا = تثبيط مركزي حادًّا، وكبد مزمنًا.', 'Kava is used as a sedative and anxiolytic, and its main acute effect is depression of the central nervous system with drowsiness, ataxia and impaired balance. The respiratory system is affected only secondarily in profound depression and is not the primary target; the endocrine system is not involved; the hematologic system is the target of ginkgo rather than kava. Key point: kava depresses the CNS acutely and injures the liver chronically.', 'تؤثّر سُمّية الكافا بالدرجة الأولى على:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 10, 'Long-term use of kava has been associated with:', '["Kidney stones","Hepatotoxicity","Diabetes","Heart failure"]'::jsonb, 1, 'الاستعمال المزمن للكافا وثّقت معه حالات تأذٍّ كبدي شديد وصل بعضها إلى القصور الكبدي الصاعق، ولهذا سُحبت من أسواق عدة دول. حصيات الكلية والداء السكري وقصور القلب ليست من اختلاطاتها المعروفة، وقصور القلب تحديدًا يرتبط بأدوية أخرى لا بالكافا. المعلومة المفتاحية: كافا مزمنة = كبد.', 'Long-term kava use has been associated with hepatotoxicity, including documented cases of severe hepatic injury and fulminant liver failure, which led to its withdrawal in several countries. Kidney stones and diabetes are not recognised complications of kava, and heart failure relates to other drug groups rather than to kava. Key point: chronic kava means liver injury.', 'ارتبط الاستعمال طويل الأمد للكافا بـ:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 11, 'Ginkgo biloba increases the risk of:', '["Bradycardia","Bleeding","Hypoglycemia","Hyperkalemia"]'::jsonb, 1, 'الجنكو بيلوبا يثبّط عامل تنشيط الصفيحات ويقلّل تكدّسها، فيطيل زمن النزف ويزيد خطر النزف العفوي خصوصًا مع مضادات التخثّر والصفيحات. بطء القلب ليس من فعله، ونقص سكر الدم يرتبط بحاصرات بيتا والأنسولين، وفرط البوتاسيوم يرتبط بمثبّطات الإنزيم المحوّل للأنجيوتنسين. المعلومة المفتاحية: جنكو = نزف.', 'Ginkgo biloba inhibits platelet-activating factor and reduces platelet aggregation, prolonging bleeding time and increasing the risk of bleeding, especially alongside anticoagulants and antiplatelet drugs. Bradycardia is not an effect of ginkgo; hypoglycemia is linked to beta-blockers and insulin; hyperkalemia is linked to ACE inhibitors. Key point: ginkgo equals bleeding.', 'يزيد الجنكو بيلوبا من خطر:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 12, 'St. John''s Wort may cause serotonin syndrome when combined with:', '["Penicillin","Selective serotonin reuptake inhibitors (SSRIs)","Acetaminophen","Insulin"]'::jsonb, 1, 'نبتة سانت جون ترفع الفعالية السيروتونينية المركزية، فيؤدي جمعها مع مثبّطات استرداد السيروتونين الانتقائية إلى فرط سيروتوني يتظاهر بهياج ورمع عضلي وفرط منعكسات وارتفاع حرارة. البنسلين صادّ حيوي بلا فعل سيروتوني، والأسيتامينوفين مسكّن خافض حرارة ولا يرفع السيروتونين، والأنسولين يخفض السكر ولا علاقة له بالمتلازمة. المعلومة المفتاحية: سانت جون + SSRI = متلازمة السيروتونين.', 'St. John''s Wort increases central serotonergic activity, so combining it with selective serotonin reuptake inhibitors (SSRIs) can produce serotonin syndrome with agitation, myoclonus, hyperreflexia and hyperthermia. Penicillin is an antibiotic with no serotonergic action; acetaminophen is an analgesic and antipyretic that does not raise serotonin; insulin lowers blood glucose and has no role in this syndrome. Key point: St. John''s Wort plus an SSRI equals serotonin syndrome.', 'قد تسبّب نبتة سانت جون متلازمة السيروتونين عند الجمع بينها وبين:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 13, 'Yohimbe toxicity is associated with:', '["Hypertension and seizures","Bradycardia","Respiratory depression","Hypothermia"]'::jsonb, 0, 'اليوهمبي حاصر لمستقبلات ألفا ٢ قبل المشبكية، فيزيد إطلاق النورأدرينالين ويسبّب ارتفاع ضغط وتسرّع قلب وقلقًا شديدًا قد يصل إلى الاختلاج. بطء القلب معاكس لفعله المنبّه، والتثبيط التنفّسي صورة المثبّطات لا المنبّهات، وانخفاض الحرارة خاطئ لأن المنبّهات تميل لرفع الحرارة. المعلومة المفتاحية: يوهمبي = منبّه ودّي يرفع الضغط ويُختلج.', 'Yohimbe blocks presynaptic alpha-2 receptors, increasing noradrenaline release and producing hypertension and seizures along with tachycardia and severe anxiety. Bradycardia is the opposite of its stimulant action; respiratory depression is the picture of depressants rather than stimulants; hypothermia is wrong because stimulants tend to raise body temperature. Key point: yohimbe is a sympathomimetic that raises blood pressure and can provoke seizures.', 'ترتبط سُمّية اليوهمبي بـ:', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 14, 'Which cardiovascular drug class most commonly causes severe bradycardia in overdose?', '["ACE inhibitors","Beta-blockers","Nitrates","Diuretics"]'::jsonb, 1, 'حاصرات بيتا تحصر التنبيه الودّي على العقدة الجيبية والأذينية البطينية، فتبطئ النبض وتضعف التقلّص، وبطء القلب هو العلامة الأبرز في جرعتها الزائدة. مثبّطات الإنزيم المحوّل تعطي هبوط ضغط وفرط بوتاسيوم أكثر من البطء، والنترات تسبّب هبوط ضغط مع تسرّع انعكاسي، والمدرّات تسبّب جفافًا واضطراب شوارد لا بطءًا شديدًا. المعلومة المفتاحية: بطء قلب شديد بجرعة زائدة = فكّر أولًا بحاصرات بيتا.', 'Beta-blockers block sympathetic stimulation of the sinus and AV nodes, slowing the rate and weakening contractility, so severe bradycardia is the leading feature in overdose. ACE inhibitors cause hypotension and hyperkalemia more than bradycardia; nitrates cause hypotension with reflex tachycardia; diuretics cause dehydration and electrolyte disturbance rather than profound bradycardia. Key point: severe bradycardia in overdose should make you think of beta-blockers first.', 'أي صنف من أدوية القلب والأوعية هو الأكثر تسبّبًا ببطء القلب الشديد في الجرعة الزائدة؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 15, 'Which beta-blocker is most commonly associated with seizures in overdose?', '["Atenolol","Bisoprolol","Propranolol","Metoprolol"]'::jsonb, 2, 'البروبرانولول شديد الذوبان في الدهون فيعبر الحاجز الدموي الدماغي بغزارة، كما يملك فعلًا مثبّتًا للغشاء يشبه حاصرات الصوديوم، فيسبّب اختلاجات واتساع QRS. الأتينولول محبّ للماء ويعبر الدماغ بصعوبة، والبيسوبرولول والميتوبرولول انتقائيان لبيتا ١ وأقل نفوذًا مركزيًا بكثير. المعلومة المفتاحية: بروبرانولول = دهني + مثبّت غشاء = اختلاج واتساع QRS.', 'Propranolol is highly lipid soluble so it crosses the blood-brain barrier readily, and it also has a membrane-stabilising sodium-channel-blocking action, producing seizures and QRS widening. Atenolol is water soluble and penetrates the brain poorly; bisoprolol and metoprolol are beta-1 selective agents with far less central penetration. Key point: propranolol is lipophilic and membrane-stabilising, so it causes seizures and a wide QRS.', 'أي حاصر بيتا هو الأكثر ارتباطًا بالاختلاجات في الجرعة الزائدة؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 16, 'Calcium channel blocker toxicity primarily causes:', '["Hypertension","Bradycardia and hypotension","Tachycardia and hypertension","Hyperthermia"]'::jsonb, 1, 'حصر قنوات الكالسيوم يقلّل دخول الكالسيوم إلى العضلة القلبية والعقد الناقلة والعضلات الملساء الوعائية، فينتج بطء قلب وضعف تقلّص وتوسّع وعائي أي هبوط ضغط. ارتفاع الضغط وتسرّع القلب مع ارتفاع الضغط كلاهما صورة منبّهات ودّية معاكسة تمامًا، وفرط الحرارة ليس من صورة هذه المجموعة. المعلومة المفتاحية: حاصرات كالسيوم = بطء + هبوط ضغط + ارتفاع سكر.', 'Calcium channel blocker toxicity causes bradycardia and hypotension because reduced calcium entry depresses the myocardium and conducting nodes while relaxing vascular smooth muscle. Hypertension alone and tachycardia and hypertension both describe a sympathomimetic picture that is the exact opposite of this mechanism; hyperthermia is not part of this drug group''s presentation. Key point: calcium channel blockers give bradycardia, hypotension and a high blood glucose.', 'تسبّب سُمّية حاصرات قنوات الكالسيوم بالدرجة الأولى:', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 17, 'Digoxin toxicity results from inhibition of:', '["Beta receptors","Sodium channels","Na⁺/K⁺-ATPase pump","Calcium channels"]'::jsonb, 2, 'الديجوكسين يثبّط مضخة الصوديوم والبوتاسيوم ATPase فيتراكم الصوديوم داخل الخلية ويرتفع الكالسيوم داخلها، مما يزيد قوة التقلّص ويسبّب في التسمّم فرط بوتاسيوم واضطرابات نظم. حصر مستقبلات بيتا آلية حاصرات بيتا، وحصر قنوات الصوديوم آلية مضادات الاكتئاب ثلاثية الحلقات والأقونيطن، وحصر قنوات الكالسيوم آلية الفيراباميل والديلتيازيم. المعلومة المفتاحية: ديجوكسين = مثبّط مضخة الصوديوم البوتاسيوم.', 'Digoxin toxicity results from inhibition of the Na⁺/K⁺-ATPase pump, so intracellular sodium accumulates, intracellular calcium rises, contractility increases, and in overdose hyperkalemia and dysrhythmias appear. Blocking beta receptors is the mechanism of beta-blockers; blocking sodium channels is the mechanism of tricyclic antidepressants and aconite; blocking calcium channels is the mechanism of verapamil and diltiazem. Key point: digoxin is a sodium-potassium pump inhibitor.', 'تنتج سُمّية الديجوكسين عن تثبيط:', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 18, 'Which cardiovascular drug overdose commonly causes hyperglycemia?', '["Digoxin","Calcium channel blockers","Beta-blockers","ACE inhibitors"]'::jsonb, 1, 'قنوات الكالسيوم ضرورية لإفراز الأنسولين من خلايا بيتا في البنكرياس، وحصرها يقلّل الأنسولين فيرتفع سكر الدم، ودرجة الارتفاع تعكس شدّة التسمّم. حاصرات بيتا تفعل العكس تمامًا فتسبّب نقص سكر، والديجوكسين ومثبّطات الإنزيم المحوّل لا تُحدثان اضطرابًا سكريًا مميّزًا. المعلومة المفتاحية: ارتفاع السكر مع بطء قلب وهبوط ضغط = حاصرات كالسيوم.', 'Calcium channel blockers commonly cause hyperglycemia because calcium entry is required for insulin release from pancreatic beta cells, so blocking it reduces insulin and raises glucose in proportion to the severity of poisoning. Beta-blockers do the opposite and cause hypoglycemia; digoxin and ACE inhibitors produce no characteristic glucose disturbance. Key point: high glucose with bradycardia and hypotension means calcium channel blocker poisoning.', 'أي جرعة زائدة من أدوية القلب والأوعية تسبّب عادةً ارتفاع سكر الدم؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 19, 'Which cardiovascular drug overdose commonly causes hypoglycemia?', '["Beta-blockers","Digoxin","Nitrates","ACE inhibitors"]'::jsonb, 0, 'حاصرات بيتا تمنع تحلّل الغليكوجين واستحداث السكر المعتمدين على التنبيه الودّي، فتسبّب نقص سكر الدم وتحجب في الوقت نفسه أعراضه التحذيرية كالرجفان والخفقان. الديجوكسين لا يضطرب معه السكر بشكل مميّز، والنترات تسبّب هبوط ضغط وصداعًا، ومثبّطات الإنزيم المحوّل تسبّب فرط بوتاسيوم لا نقص سكر. المعلومة المفتاحية: بيتا تُنقص السكر، والكالسيوم يرفعه.', 'Beta-blockers commonly cause hypoglycemia because they block the sympathetically driven glycogenolysis and gluconeogenesis that defend blood glucose, and they simultaneously mask warning symptoms such as tremor and palpitations. Digoxin produces no characteristic glucose change; nitrates cause hypotension and headache; ACE inhibitors cause hyperkalemia rather than low glucose. Key point: beta-blockers lower glucose while calcium channel blockers raise it.', 'أي جرعة زائدة من أدوية القلب والأوعية تسبّب عادةً نقص سكر الدم؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 20, 'Which medication is used therapeutically to treat heart failure and atrial fibrillation?', '["Nitroglycerin","Digoxin","Verapamil","Lisinopril"]'::jsonb, 1, 'الديجوكسين يجمع بين فعل مقوٍّ للتقلّص يفيد في قصور القلب وفعل مبطّئ للنقل الأذيني البطيني يضبط سرعة البطين في الرجفان الأذيني. النتروغليسرين موسّع وعائي للذبحة الصدرية، والفيراباميل يضبط سرعة الرجفان لكنه غير مستطبّ في قصور القلب لكونه مثبّطًا للتقلّص، والليزينوبريل يفيد في قصور القلب لكنه لا يعالج الرجفان الأذيني. المعلومة المفتاحية: الديجوكسين وحده يغطّي الحالتين معًا.', 'Digoxin combines a positive inotropic effect that helps heart failure with slowing of AV conduction that controls the ventricular rate in atrial fibrillation, so it treats both conditions. Nitroglycerin is a vasodilator for angina; verapamil controls rate in atrial fibrillation but is not indicated in heart failure because it depresses contractility; lisinopril helps heart failure but does not treat atrial fibrillation. Key point: digoxin is the one agent that covers both heart failure and atrial fibrillation.', 'أي دواء يُستعمل علاجيًا لمعالجة قصور القلب والرجفان الأذيني؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 21, 'ACE inhibitor overdose usually produces:', '["Severe ventricular arrhythmias","Hypotension and hyperkalemia","Bradycardia with seizures","Hyperthermia"]'::jsonb, 1, 'تثبيط الإنزيم المحوّل يخفض الأنجيوتنسين ٢ فيتوسّع الوعاء ويهبط الضغط، ويقلّل الألدوستيرون فيُحتبس البوتاسيوم ويرتفع في الدم. اضطرابات النظم البطينية الشديدة صورة الديجوكسين والأقونيطن، وبطء القلب مع الاختلاجات يوحي بالبروبرانولول، وفرط الحرارة ليس من صورة هذه المجموعة. المعلومة المفتاحية: ACE = ضغط نازل وبوتاسيوم صاعد.', 'ACE inhibitor overdose usually produces hypotension and hyperkalemia, since less angiotensin II means vasodilation and falling pressure while less aldosterone means potassium retention. Severe ventricular arrhythmias suggest digoxin or aconite; bradycardia with seizures suggests propranolol; hyperthermia is not part of this drug group''s picture. Key point: ACE inhibitors drop the pressure and raise the potassium.', 'تُحدث الجرعة الزائدة من مثبّطات الإنزيم المحوّل للأنجيوتنسين عادةً:', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 22, 'Nitrate overdose most commonly causes:', '["Severe hypertension","Hypotension and headache","Bradycardia and hypoglycemia","Hyperglycemia"]'::jsonb, 1, 'النترات تُطلق أكسيد النتريك فتوسّع الأوردة والشرايين، فينقص العود الوريدي ويهبط الضغط، ويسبّب توسّع أوعية الدماغ صداعًا نابضًا هو أشيع شكوى. ارتفاع الضغط الشديد معاكس تمامًا لآليتها، وبطء القلب مع نقص السكر صورة حاصرات بيتا، وارتفاع السكر صورة حاصرات الكالسيوم. المعلومة المفتاحية: نترات = توسّع وعائي = ضغط نازل وصداع.', 'Nitrates release nitric oxide and dilate both veins and arteries, so venous return and blood pressure fall, and cerebral vasodilation produces a throbbing headache — hence hypotension and headache. Severe hypertension is the exact opposite of the mechanism; bradycardia and hypoglycemia describe beta-blocker toxicity; hyperglycemia describes calcium channel blocker toxicity. Key point: nitrates equal vasodilation, falling pressure and headache.', 'تسبّب الجرعة الزائدة من النترات في الغالب:', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 23, 'Which is the most common cardiovascular finding in beta-blocker toxicity?', '["Hypertension","Tachycardia","Bradycardia","Bounding pulse"]'::jsonb, 2, 'حصر مستقبلات بيتا ١ في العقدة الجيبية يبطئ معدّل النظم، فبطء القلب هو الموجودة الأشيع والأبكر في هذه السُمّية ويرافقه هبوط ضغط. ارتفاع الضغط وتسرّع القلب معاكسان لآلية الدواء ويشيران لمنبّه ودّي، والنبض القافز يعكس نتاجًا قلبيًا مرتفعًا وهو عكس ما يحدث هنا. المعلومة المفتاحية: حاصرات بيتا = بطء قلب أولًا.', 'Blockade of beta-1 receptors at the sinus node slows the rate, so bradycardia is the earliest and most common cardiovascular finding in beta-blocker toxicity and is accompanied by hypotension. Hypertension and tachycardia are both opposite to the drug''s mechanism and suggest a sympathomimetic; a bounding pulse reflects a high cardiac output, which is the reverse of what happens here. Key point: in beta-blocker toxicity, bradycardia comes first.', 'ما هي أشيع موجودة قلبية وعائية في سُمّية حاصرات بيتا؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 24, 'A patient with digoxin toxicity is likely to complain of:', '["Double vision only","Yellow-green vision","Complete blindness","Hearing loss"]'::jsonb, 1, 'الديجوكسين يؤثّر على مضخة الصوديوم والبوتاسيوم في مخاريط الشبكية فيسبّب اضطراب رؤية الألوان مع هالات صفراء خضراء، وهي علامة كلاسيكية شديدة النوعية. ازدواج الرؤية وحده ليس السمة المميّزة، والعمى الكامل لا يحدث في هذه السُمّية، وفقدان السمع يرتبط بالسالسيلات والأمينوغليكوزيدات لا بالديجوكسين. المعلومة المفتاحية: أصفر وأخضر = ديجوكسين.', 'Digoxin affects the sodium-potassium pump in the retinal cones, disturbing colour vision and producing yellow-green vision with haloes, a classic and highly specific sign. Double vision only is not the characteristic feature; complete blindness does not occur in this toxicity; hearing loss belongs to salicylates and aminoglycosides rather than digoxin. Key point: yellow and green vision is the signature of digoxin.', 'من المرجّح أن يشكو المريض المصاب بسُمّية الديجوكسين من:', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 25, 'Which electrolyte abnormality is commonly associated with ACE inhibitor toxicity?', '["Hypokalemia","Hyperkalemia","Hypernatremia","Hypocalcemia"]'::jsonb, 1, 'تثبيط الإنزيم المحوّل ينقص الألدوستيرون، والألدوستيرون هو الذي يطرح البوتاسيوم في الكلية، فيؤدي نقصه إلى احتباس البوتاسيوم وفرطه في الدم مع خطر اضطرابات نظم. نقص البوتاسيوم عكس ذلك ويرتبط بالمدرّات، وفرط الصوديوم ونقص الكالسيوم ليسا من الصورة المميّزة لهذه الأدوية. المعلومة المفتاحية: ACE يوقف الألدوستيرون فيرتفع البوتاسيوم.', 'ACE inhibitor toxicity is commonly associated with hyperkalemia, because inhibiting the converting enzyme lowers aldosterone, and aldosterone is what drives renal potassium excretion, so potassium is retained and dysrhythmia risk rises. Hypokalemia is the opposite and is linked to diuretics; hypernatremia and hypocalcemia are not characteristic of these drugs. Key point: ACE inhibitors switch off aldosterone, so potassium climbs.', 'أي اضطراب في الشوارد يرتبط عادةً بسُمّية مثبّطات الإنزيم المحوّل للأنجيوتنسين؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 26, 'Which finding best distinguishes PCP intoxication from LSD intoxication?', '["Visual hallucinations","Horizontal nystagmus and violent behavior","Tachycardia","Mydriasis"]'::jsonb, 1, 'الـ PCP يجمع بين الرأرأة الأفقية والعمودية والسلوك العدواني العنيف مع تسكين ألمي شديد، وهذه التوليفة لا تظهر مع الـ LSD. الهلوسات البصرية سمة الـ LSD نفسها فلا تصلح للتفريق، والتسرّع القلبي وتوسّع الحدقة موجودان في الاثنين معًا لأنهما فعل ودّي مشترك. المعلومة المفتاحية: رأرأة + عنف = PCP.', 'PCP intoxication combines horizontal nystagmus and violent behavior with profound analgesia, and that combination does not occur with LSD. Visual hallucinations are typical of LSD itself so they cannot separate the two; tachycardia and mydriasis are present in both because each has a shared sympathomimetic effect. Key point: nystagmus plus violence equals PCP.', 'أي موجودة تميّز على نحو أفضل تسمّم الـ PCP عن تسمّم الـ LSD؟', '{}'::jsonb, 'المهلوسات والمواد النفسية', false, false, false),
  ((select id from s), 27, 'Why should blood glucose be checked in any patient with altered mental status?', '["To diagnose diabetes.","To exclude hypoglycemia as a reversible cause of altered consciousness.","Because all hallucinogens cause hypoglycemia.","To determine kidney function."]'::jsonb, 1, 'نقص سكر الدم يقلّد أي صورة عصبية تقريبًا من الهياج إلى السبات والاختلاج، وهو قابل للعكس خلال دقائق بالسكر، لذلك فحصه إلزامي في كل اضطراب وعي. تشخيص الداء السكري ليس هدفًا إسعافيًا آنيًا، وليست كل المهلوسات تسبّب نقص سكر، وفحص السكر لا يقيس وظيفة الكلية. المعلومة المفتاحية: كل وعي مضطرب يُفحص سكره فورًا.', 'Blood glucose is checked to exclude hypoglycemia as a reversible cause of altered consciousness, because low glucose mimics almost any neurological picture from agitation to coma and seizure yet reverses within minutes with sugar. Diagnosing diabetes is not an immediate prehospital goal; not all hallucinogens cause hypoglycemia; and a glucose reading says nothing about kidney function. Key point: every patient with altered mental status gets an immediate glucose check.', 'لماذا يجب فحص سكر الدم عند أي مريض باضطراب في الحالة العقلية؟', '{}'::jsonb, 'المبادئ العامة للتعامل مع التسمم', false, false, false),
  ((select id from s), 28, 'Which statement about prognosis is TRUE?', '["Most patients recover with supportive care.","Hallucinogen toxicity is always fatal.","Every patient requires intubation.","There is a specific antidote for all hallucinogens."]'::jsonb, 0, 'أغلب حالات تسمّم المهلوسات تنتهي بالشفاء بالرعاية الداعمة وحدها: بيئة هادئة، سوائل، بنزوديازيبينات عند الهياج، ومراقبة. القول بأنها مميتة دائمًا مبالغة غير صحيحة، والتنبيب يُحفظ للحالات التي تفقد حماية الطريق الهوائي فقط، ولا يوجد ترياق نوعي للمهلوسات أصلًا. المعلومة المفتاحية: الرعاية الداعمة هي العلاج، والإنذار جيد غالبًا.', 'Most patients recover with supportive care, since the great majority of hallucinogen intoxications resolve with a calm environment, fluids, benzodiazepines for agitation and observation. Saying hallucinogen toxicity is always fatal is a gross overstatement; intubation is reserved for patients who lose airway protection rather than required for everyone; and there is no specific antidote for hallucinogens at all. Key point: supportive care is the treatment and the prognosis is usually good.', 'أي عبارة عن الإنذار صحيحة؟', '{}'::jsonb, 'المبادئ العامة للتعامل مع التسمم', false, false, false),
  ((select id from s), 29, 'Which of the following is the best summary of prehospital management?', '["Give activated charcoal to every patient.","Focus on scene safety, ABCs, benzodiazepines for agitation or seizures, active cooling when indicated, ECG monitoring, and rapid transport.","Administer antibiotics immediately.","Use physical restraints as the primary treatment."]'::jsonb, 1, 'التدبير قبل المستشفوي يقوم على تسلسل ثابت: أمن المسرح أولًا لأن المريض قد يكون عنيفًا، ثم ABC، ثم البنزوديازيبينات للهياج والاختلاج، والتبريد عند فرط الحرارة، ومراقبة ECG لاكتشاف السُمّية القلبية، والنقل السريع. الفحم المنشّط له استطبابات وموانع محدّدة ولا يُعطى للجميع، والصادّات الحيوية لا دور لها في التسمّم، والقيود الجسدية إجراء مساعد مؤقت لا علاج أساسي وقد تزيد انحلال الربيدات. المعلومة المفتاحية: أمان ثم ABC ثم بنزوديازيبين وتبريد ومراقبة ونقل.', 'Prehospital management follows a fixed sequence: scene safety first because the patient may be violent, then ABCs, benzodiazepines for agitation or seizures, active cooling when indicated, ECG monitoring to detect cardiotoxicity, and rapid transport. Activated charcoal has defined indications and contraindications so it is not given to every patient; antibiotics have no role in poisoning; and physical restraints are a temporary adjunct rather than a primary treatment and may worsen rhabdomyolysis. Key point: safety, then ABCs, then benzodiazepines, cooling, monitoring and transport.', 'أي مما يلي هو أفضل تلخيص للتدبير قبل المستشفوي؟', '{}'::jsonb, 'المبادئ العامة للتعامل مع التسمم', false, false, false),
  ((select id from s), 30, 'A 68-year-old man develops nausea, vomiting, visual disturbances, bradycardia, and AV block after drinking homemade herbal tea made from foxglove. Which poisoning is most likely?', '["Kava","Foxglove (Digitalis)","Ephedra","Yohimbe"]'::jsonb, 1, 'الصورة كاملة نموذجية للغليكوزيدات القلبية: غثيان وقيء، اضطراب بصري، بطء قلب، وحصار أذيني بطيني، والقصة نفسها تذكر شاي القفازيّة. الكافا تعطي تثبيطًا مركزيًا وسُمّية كبدية لا حصارًا قلبيًا، والإفيدرا واليوهمبي منبّهان يرفعان النبض والضغط وهو عكس ما ورد. المعلومة المفتاحية: بطء قلب + حصار + اضطراب بصري بعد شاي عشبي = قفازيّة.', 'The full picture of nausea, vomiting, visual disturbance, bradycardia and AV block is classic cardiac glycoside poisoning, and the history itself describes tea brewed from foxglove (digitalis). Kava produces central depression and liver toxicity rather than heart block; ephedra and yohimbe are stimulants that raise pulse and pressure, the opposite of what is described. Key point: bradycardia with heart block and visual disturbance after herbal tea equals foxglove.', 'رجل عمره ٦٨ عامًا أصيب بغثيان وقيء واضطرابات بصرية وبطء قلب وحصار أذيني بطيني بعد شرب شاي عشبي منزلي مصنوع من القفازيّة. ما التسمّم الأرجح؟', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 31, 'A young athlete develops severe hypertension, tachycardia, anxiety, and tremors after taking an herbal weight-loss supplement. Which herb is the most likely cause?', '["Ginkgo biloba","Kava","Ephedra","Foxglove"]'::jsonb, 2, 'الإفيدرا هي العشبة الكلاسيكية في مكمّلات إنقاص الوزن والطاقة، وفعلها الودّي يفسّر ارتفاع الضغط والتسرّع والقلق والرعاش عند رياضي شاب. الجنكو بيلوبا يسبّب نزفًا لا اندفاعًا ودّيًا، والكافا مثبّطة تُنعس لا تُهيّج، والقفازيّة تسبّب بطء قلب لا تسرّعه. المعلومة المفتاحية: مكمّل تنحيف + صورة ودّية = إفيدرا.', 'Ephedra is the classic herb in weight-loss and energy supplements, and its sympathomimetic action explains severe hypertension, tachycardia, anxiety and tremor in a young athlete. Ginkgo biloba causes bleeding rather than a sympathomimetic surge; kava is a depressant that sedates rather than stimulates; foxglove causes bradycardia rather than tachycardia. Key point: a slimming supplement plus a sympathomimetic picture equals ephedra.', 'رياضي شاب أصيب بارتفاع ضغط شديد وتسرّع قلب وقلق ورعاش بعد تناوله مكمّلًا عشبيًا لإنقاص الوزن. ما العشبة الأرجح كسبب؟', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 32, 'A patient taking warfarin develops spontaneous bleeding after starting an herbal supplement for memory. Which herb is the most likely cause?', '["Ginkgo biloba","Kava","St. John''s Wort","Yohimbe"]'::jsonb, 0, 'الجنكو بيلوبا هو المكمّل الأشهر لتحسين الذاكرة والدوران الدماغي، ويثبّط تكدّس الصفيحات فيتضافر مع الوارفارين ويسبّب نزفًا عفويًا. الكافا مثبّطة مركزية وسامّة للكبد، ونبتة سانت جون تُنقص فعالية الوارفارين بتحريضها الإنزيمات فتقلّل النزف لا تزيده، واليوهمبي منبّه ودّي بلا تأثير نزفي. المعلومة المفتاحية: ذاكرة + وارفارين + نزف = جنكو.', 'Ginkgo biloba is the best-known supplement taken for memory and cerebral circulation, and it inhibits platelet aggregation, so it compounds the effect of warfarin and causes spontaneous bleeding. Kava is a central depressant and hepatotoxin; St. John''s Wort induces hepatic enzymes and actually reduces warfarin effect rather than increasing bleeding; yohimbe is a sympathomimetic with no bleeding effect. Key point: memory supplement plus warfarin plus bleeding equals ginkgo.', 'مريض يتناول الوارفارين أصيب بنزف عفوي بعد بدئه مكمّلًا عشبيًا للذاكرة. ما العشبة الأرجح كسبب؟', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 33, 'Which statement about herbal remedies is TRUE?', '["Natural products cannot cause poisoning.","Herbal remedies should not be considered during patient assessment.","Herbal remedies may cause severe toxicity and important drug interactions.","There is a specific antidote for every herbal poisoning."]'::jsonb, 2, 'الأعشاب تحوي مركّبات فعّالة قد تكون قاتلة كالقفازيّة والدفلى، وتتداخل مع الأدوية كالجنكو مع الوارفارين ونبتة سانت جون مع مضادات الاكتئاب. القول بأن الطبيعي لا يسمّم خاطئ تمامًا، وتجاهل الأعشاب في التقييم خطأ جسيم لأن المريض غالبًا لا يذكرها تلقائيًا، ولا يوجد ترياق نوعي إلا لقلّة نادرة كالغليكوزيدات القلبية. المعلومة المفتاحية: اسأل دائمًا عن الأعشاب، فالطبيعي ليس آمنًا.', 'Herbal remedies may cause severe toxicity and important drug interactions, since plants such as foxglove and oleander can be lethal and ginkgo with warfarin or St. John''s Wort with antidepressants are well documented interactions. Saying natural products cannot cause poisoning is plainly false; saying herbal remedies should not be considered during patient assessment is a serious error because patients rarely volunteer them; and there is no specific antidote for every herbal poisoning, only for a rare few such as cardiac glycosides. Key point: always ask about herbal use, because natural is not safe.', 'أي عبارة عن العلاجات العشبية صحيحة؟', '{}'::jsonb, 'الأعشاب والمستحضرات الطبيعية', false, false, false),
  ((select id from s), 34, 'Which antidote specifically binds and neutralizes its target drug?', '["Glucagon","Calcium chloride","Digoxin immune Fab","Methylene blue"]'::jsonb, 2, 'أجسام الديجوكسين المناعية Fab أضداد ترتبط مباشرة بجزيء الديجوكسين في الدم وتُخرجه من الفعالية ثم يُطرح كلويًا، فهي ترياق رابط حقيقي. الغلوكاغون يتجاوز الحصار عبر مسار مستقلّ بلا ارتباط بحاصر بيتا، وكلوريد الكالسيوم يعوّض الكالسيوم فيتغلّب على الحصار وظيفيًا لا برابطة، وأزرق الميثيلين يُرجع الميتهيموغلوبين كيميائيًا دون أن يرتبط بدواء. المعلومة المفتاحية: الترياق الرابط الوحيد هنا هو Fab للديجوكسين.', 'Digoxin immune Fab consists of antibody fragments that bind the digoxin molecule directly in the blood, inactivate it and allow renal excretion, making it a true binding antidote. Glucagon bypasses beta blockade through an independent pathway without binding the drug; calcium chloride overcomes calcium channel blockade functionally by supplying substrate rather than by binding; methylene blue chemically reduces methemoglobin without binding any drug. Key point: the only true binding antidote here is digoxin immune Fab.', 'أي ترياق يرتبط نوعيًا بالدواء الهدف ويعادله؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 35, 'Which cardiovascular drug overdose is most likely to cause yellow-green visual disturbances?', '["Digoxin","Atenolol","Nitroglycerin","Enalapril"]'::jsonb, 0, 'الديجوكسين يثبّط مضخة الصوديوم والبوتاسيوم في مخاريط الشبكية فيسبّب خلل رؤية الألوان والهالات الصفراء الخضراء، وهي علامة كلاسيكية للتسمّم. الأتينولول حاصر بيتا يعطي بطء قلب وهبوط ضغط بلا أعراض بصرية لونية، والنتروغليسرين يعطي صداعًا وهبوط ضغط، والإنالابريل يعطي هبوط ضغط وفرط بوتاسيوم. المعلومة المفتاحية: الرؤية الصفراء الخضراء توقيع الديجوكسين.', 'Digoxin overdose is the one most likely to cause yellow-green visual disturbances, because inhibition of the sodium-potassium pump in the retinal cones disrupts colour vision and produces haloes. Atenolol is a beta-blocker giving bradycardia and hypotension without colour vision change; nitroglycerin gives headache and hypotension; enalapril gives hypotension and hyperkalemia. Key point: yellow-green vision is the signature of digoxin toxicity.', 'أي جرعة زائدة من أدوية القلب والأوعية هي الأرجح أن تسبّب اضطرابات بصرية صفراء خضراء؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 36, 'Which statement is TRUE regarding cardiovascular drug toxicity?', '["All ACE inhibitor overdoses require an antidote.","ECG monitoring is essential because life-threatening arrhythmias may develop.","Activated charcoal is indicated for every patient regardless of presentation.","Bradycardia is never caused by calcium channel blocker overdose."]'::jsonb, 1, 'أدوية القلب تؤثّر مباشرة على النقل الكهربائي، وقد تتطوّر اضطرابات نظم مميتة فجأة، لذا فمراقبة تخطيط القلب المستمرة ركن أساسي في التدبير. القول بأن كل جرعات مثبّطات الإنزيم المحوّل تحتاج ترياقًا خاطئ لأن تدبيرها داعم أصلًا ولا ترياق نوعي لها، وإعطاء الفحم للجميع خاطئ لأن له موانع كاضطراب الوعي وفقد حماية الطريق الهوائي، والقول بأن حاصرات الكالسيوم لا تسبّب بطء القلب خاطئ تمامًا فهو من أبرز علاماتها. المعلومة المفتاحية: ECG مستمر في كل تسمّم قلبي وعائي.', 'ECG monitoring is essential because life-threatening arrhythmias may develop, as cardiovascular drugs act directly on cardiac conduction and lethal rhythms can appear suddenly. Saying all ACE inhibitor overdoses require an antidote is false because management is supportive and no specific antidote exists; saying activated charcoal is indicated for every patient ignores contraindications such as altered consciousness and an unprotected airway; and saying bradycardia is never caused by calcium channel blocker overdose is plainly wrong since it is one of their leading signs. Key point: continuous ECG monitoring in every cardiovascular poisoning.', 'أي عبارة صحيحة فيما يخصّ سُمّية أدوية القلب والأوعية؟', '{}'::jsonb, 'أدوية القلب والأوعية', false, false, false),
  ((select id from s), 37, 'Hallucinogenic drugs primarily affect:', '["Liver function","Perception, mood, and sensory experiences","Kidney function","Blood clotting"]'::jsonb, 1, 'المهلوسات تعمل أساسًا على مستقبلات السيروتونين ٥HT2A ومسارات أخرى في القشرة الدماغية، فتغيّر الإدراك والمزاج والتجربة الحسّية وتُحدث الهلوسة وتشوّه الزمن. وظيفة الكبد ليست هدفها الأول وتخصّ الأسيتامينوفين والكافا المزمنة، ووظيفة الكلية تخصّ مضادات الالتهاب، وتخثّر الدم يخصّ الجنكو ومضادات التخثّر. المعلومة المفتاحية: المهلوس يغيّر العقل لا العضو.', 'Hallucinogenic drugs primarily affect perception, mood, and sensory experiences, acting mainly at 5HT2A serotonin receptors and other cortical pathways to distort perception and time sense. Liver function is not their primary target and belongs to acetaminophen and chronic kava; kidney function belongs to NSAIDs; blood clotting belongs to ginkgo and anticoagulants. Key point: a hallucinogen alters the mind rather than an organ.', 'تؤثّر الأدوية المهلوسة بالدرجة الأولى على:', '{}'::jsonb, 'المهلوسات والمواد النفسية', false, false, false),
  ((select id from s), 38, 'Which of the following is considered a classic hallucinogen?', '["Ketamine","LSD","Morphine","Cocaine"]'::jsonb, 1, 'الـ LSD هو النموذج الكلاسيكي للمهلوسات السيروتونينية، ويعمل على مستقبلات ٥HT2A محدثًا هلوسات بصرية وتشوّهًا للزمن مع بقاء الاستبصار جزئيًا. الكيتامين يُصنّف مخدّرًا انفصاليًا لا مهلوسًا كلاسيكيًا، والمورفين أفيون مثبّط، والكوكايين منبّه ودّي وإن سبّب ذهانًا فهو ليس مهلوسًا كلاسيكيًا. المعلومة المفتاحية: الكلاسيكي = LSD وأشباهه السيروتونينية.', 'LSD is the classic serotonergic hallucinogen, acting at 5HT2A receptors to produce visual hallucinations and time distortion with insight often partly preserved. Ketamine is classified as a dissociative anaesthetic rather than a classic hallucinogen; morphine is an opioid depressant; cocaine is a sympathomimetic stimulant that may cause psychosis but is not a classic hallucinogen. Key point: the classic hallucinogens are LSD and its serotonergic relatives.', 'أي مما يلي يُعدّ مهلوسًا كلاسيكيًا؟', '{}'::jsonb, 'المهلوسات والمواد النفسية', false, false, false),
  ((select id from s), 39, 'Which ECG finding suggests significant cardiotoxicity?', '["Short PR interval","Wide QRS complex","Tall P waves","Sinus bradycardia"]'::jsonb, 1, 'اتساع مركّب QRS يدلّ على حصر قنوات الصوديوم وتباطؤ النقل داخل البطين، وهو منذر باضطرابات نظم بطينية مميتة ويستدعي بيكربونات الصوديوم. قِصَر فترة PR موجودة تخصّ متلازمات ما قبل الإثارة لا السُمّية، وموجات P العالية تشير لضخامة أذينية، وبطء القلب الجيبي قد يكون فيزيولوجيًا أو دوائيًا بسيطًا وليس بالخطورة نفسها. المعلومة المفتاحية: QRS عريض = إنذار خطر قلبي.', 'A wide QRS complex indicates sodium channel blockade with slowed intraventricular conduction, warns of lethal ventricular arrhythmias and calls for sodium bicarbonate. A short PR interval belongs to pre-excitation syndromes rather than toxicity; tall P waves suggest atrial enlargement; sinus bradycardia may be physiological or a mild drug effect and does not carry the same danger. Key point: a wide QRS is the cardiac red flag in poisoning.', 'أي موجودة في تخطيط القلب تشير إلى سُمّية قلبية مهمة؟', '{}'::jsonb, 'المبادئ العامة للتعامل مع التسمم', false, false, false),
  ((select id from s), 40, 'Which complication may occur secondary to severe hyperthermia?', '["Rhabdomyolysis","Otitis media","Cholecystitis","Pancreatitis"]'::jsonb, 0, 'فرط الحرارة الشديد مع الهياج والتشنّج العضلي يتلف الخلايا العضلية الهيكلية فتنطلق الميوغلوبين والكرياتين كيناز، وينتج انحلال ربيدات قد يقود إلى قصور كلوي حاد وفرط بوتاسيوم. التهاب الأذن الوسطى خمج طفلي غير مرتبط، والتهاب المرارة سببه انسداد حصوي، والتهاب البنكرياس يرتبط بالكحول والحصيات لا بفرط الحرارة الدوائي. المعلومة المفتاحية: حرارة عالية + هياج = انحلال ربيدات وسوائل مبكّرة.', 'Severe hyperthermia with agitation and muscle rigidity damages skeletal muscle cells, releasing myoglobin and creatine kinase and producing rhabdomyolysis, which can progress to acute kidney injury and hyperkalemia. Otitis media is an unrelated childhood infection; cholecystitis results from gallstone obstruction; pancreatitis relates to alcohol and gallstones rather than to drug-induced hyperthermia. Key point: high temperature plus agitation means rhabdomyolysis and early fluids.', 'أي اختلاط قد يحدث ثانويًا لفرط الحرارة الشديد؟', '{}'::jsonb, 'المبادئ العامة للتعامل مع التسمم', false, false, false),
  ((select id from s), 41, 'A patient taking a large amount of an NSAID develops epigastric pain and hematemesis. The most likely complication is:', '["Upper gastrointestinal bleeding","Acute pancreatitis in every case","Hemolytic anemia","Pneumothorax"]'::jsonb, 0, 'مضادات الالتهاب غير الستيرويدية تثبّط إنزيم COX1 فتقلّل البروستاغلاندينات الحامية للمخاطية المعدية، فيحدث تآكل وقرحة ونزف يتظاهر بألم شرسوفي وقيء دموي. التهاب البنكرياس ليس اختلاطًا معتادًا وكلمة في كل الحالات تجعله خاطئًا حتمًا، وفقر الدم الانحلالي ليس آلية هذه الأدوية، واسترواح الصدر لا صلة له بالمسار الهضمي. المعلومة المفتاحية: NSAID = قرحة ونزف هضمي علوي.', 'NSAIDs inhibit COX-1 and reduce the prostaglandins that protect gastric mucosa, so erosion, ulceration and upper gastrointestinal bleeding follow, presenting as epigastric pain with hematemesis. Acute pancreatitis in every case is not a usual complication and the absolute wording makes it wrong; hemolytic anemia is not the mechanism of these drugs; pneumothorax has no connection to the gastrointestinal tract. Key point: NSAIDs mean ulceration and upper GI bleeding.', 'مريض تناول كمية كبيرة من مضادّ التهاب غير ستيرويدي فأصيب بألم شرسوفي وقيء دموي. الاختلاط الأرجح هو:', '{}'::jsonb, 'المسكنات ومضادات الالتهاب', false, false, false),
  ((select id from s), 42, 'Which NSAID toxicity can be particularly dangerous in patients with asthma who are sensitive to aspirin/NSAIDs?', '["Bronchospasm","Pulmonary edema in every case","Tension pneumothorax","Pleural effusion"]'::jsonb, 0, 'تثبيط COX يحوّل حمض الأراكيدونيك نحو مسار الليبوأوكسيجيناز فتزداد الليكوترينات المقبّضة للقصبات، ما يُحدث تشنّجًا قصبيًا شديدًا عند المرضى الحسّاسين للأسبرين. وذمة الرئة في كل الحالات عبارة مطلقة خاطئة، واسترواح الصدر الضاغط سببه رضّي أو عفوي لا دوائي، وانصباب الجنب ليس من الصورة الحادّة لهذه الأدوية. المعلومة المفتاحية: ثالوث الربو وبوليبات الأنف وحساسية الأسبرين = خطر تشنّج قصبي.', 'COX inhibition shunts arachidonic acid down the lipoxygenase pathway, increasing bronchoconstricting leukotrienes and producing severe bronchospasm in aspirin-sensitive patients. Pulmonary edema in every case is an absolute statement that is false; tension pneumothorax is traumatic or spontaneous rather than drug-induced; pleural effusion is not part of the acute picture of these drugs. Key point: the triad of asthma, nasal polyps and aspirin sensitivity carries a real risk of bronchospasm.', 'أي سُمّية لمضادات الالتهاب غير الستيرويدية قد تكون خطيرة بوجه خاص عند مرضى الربو الحسّاسين للأسبرين أو مضادات الالتهاب؟', '{}'::jsonb, 'المسكنات ومضادات الالتهاب', false, false, false),
  ((select id from s), 43, 'A patient presents after a significant NSAID overdose. Which assessment is most appropriate for the paramedic?', '["Assess airway, breathing, circulation, mental status, and monitor for GI/renal complications","Assume the ingestion is harmless because NSAIDs are OTC","Give naloxone immediately to all patients","Induce vomiting routinely"]'::jsonb, 0, 'التدبير الإسعافي يبدأ دائمًا بتقييم منهجي للطريق الهوائي والتنفّس والدوران والوعي، ثم ترقّب الاختلاطات النوعية لهذه الأدوية وهي النزف الهضمي والتأذّي الكلوي. افتراض عدم الأذى لأن الدواء بلا وصفة خطأ خطير فالجرعات الكبيرة تسبّب حماضًا واختلاجًا وقصورًا كلويًا، والنالوكسون خاص بالأفيونات ولا فائدة له هنا، وإحداث التقيّؤ الروتيني ممارسة مهجورة وخطرة لاحتمال الاستنشاق. المعلومة المفتاحية: ABC أولًا ثم مراقبة الهضم والكلية.', 'The correct approach is to assess airway, breathing, circulation, mental status, and monitor for GI/renal complications, since prehospital care always starts with a systematic primary survey and then anticipates the specific complications of these drugs, namely GI bleeding and renal injury. Assuming the ingestion is harmless because NSAIDs are OTC is dangerous, as large doses cause acidosis, seizures and renal failure; naloxone is specific to opioids and useless here; and inducing vomiting routinely is an abandoned and hazardous practice because of aspiration risk. Key point: ABCs first, then watch the gut and the kidneys.', 'يحضر مريض بعد جرعة زائدة كبيرة من مضادّ التهاب غير ستيرويدي. أي تقييم هو الأنسب للمسعف؟', '{}'::jsonb, 'المسكنات ومضادات الالتهاب', false, false, false),
  ((select id from s), 44, 'In significant salicylate poisoning, serum and urine alkalinization may be achieved using:', '["Sodium bicarbonate","Calcium chloride","Naloxone","Dextrose only"]'::jsonb, 0, 'بيكربونات الصوديوم ترفع درجة الحموضة في المصل والبول فتُبقي السالسيلات بشكلها المتشرّد الذي لا يعبر إلى الدماغ ولا يُعاد امتصاصه في النبيبات، فيزداد طرحه البولي. كلوريد الكالسيوم ترياق حاصرات الكالسيوم لا علاقة له بالقلونة، والنالوكسون خاص بالأفيونات، والدكستروز يصحّح نقص السكر ولا يغيّر درجة الحموضة. المعلومة المفتاحية: بيكربونات = قلونة تسحب السالسيلات من الدماغ إلى البول.', 'Sodium bicarbonate raises serum and urine pH, keeping salicylate in its ionised form so it cannot cross into the brain or be reabsorbed in the renal tubules, which increases urinary elimination. Calcium chloride is the antidote for calcium channel blockers and has nothing to do with alkalinization; naloxone is specific to opioids; dextrose only corrects hypoglycemia and does not change pH. Key point: bicarbonate alkalinizes and pulls salicylate out of the brain and into the urine.', 'في التسمّم المهمّ بالسالسيلات، يمكن تحقيق قلونة المصل والبول باستخدام:', '{}'::jsonb, 'المسكنات ومضادات الالتهاب', false, false, false),
  ((select id from s), 45, 'Which intervention may be considered in severe, life-threatening salicylate poisoning when indicated?', '["Hemodialysis","Immediate insulin infusion in all patients","Naloxone infusion","Chest tube insertion"]'::jsonb, 0, 'السالسيلات جزيء صغير ضعيف الارتباط بالبروتين وقليل حجم التوزّع، لذا يُنزع بفعالية بالغسيل الكلوي الذي يُستطبّ عند الاضطراب العصبي أو الحماض المعنّد أو الوذمة الرئوية أو المستويات العالية جدًا. تسريب الأنسولين للجميع غير مستطبّ وهو أقرب لبروتوكول حاصرات الكالسيوم، والنالوكسون خاص بالأفيونات، والأنبوب الصدري إجراء لاسترواح الصدر لا لتسمّم استقلابي. المعلومة المفتاحية: السالسيلات الشديدة = غسيل كلوي.', 'Hemodialysis may be considered in severe, life-threatening salicylate poisoning because salicylate is a small molecule with low protein binding and a small volume of distribution, and dialysis is indicated for neurological impairment, refractory acidosis, pulmonary edema or very high levels. Immediate insulin infusion in all patients is not indicated and belongs more to calcium channel blocker protocols; naloxone infusion is specific to opioids; chest tube insertion treats pneumothorax rather than a metabolic poisoning. Key point: severe salicylate poisoning means hemodialysis.', 'أي إجراء قد يُؤخذ بالحسبان في التسمّم الشديد المهدّد للحياة بالسالسيلات عند الاستطباب؟', '{}'::jsonb, 'المسكنات ومضادات الالتهاب', false, false, false);
  insert into amusq.subjects (name, color, icon, descr, topics, exam_date, published, free, ord)
insert into amusq.questions
  (subject_id, ord, q, options, answer, expl_ar, expl_en, translation, mnemonic, topic, derived, opts_built, important)
values
  ((select id from s), 1, 'What is the definition of Asthma?', '["Chronic inflammatory disorder with reversible airflow obstruction","Irreversible alveolar destruction","Bacterial infection of the lower airway","Viral infection of the subglottic airway"]'::jsonb, 0, 'الربو بتعريفه اضطراب التهابي مزمن في المجاري الهوائية يرافقه انسداد قابل للعكس تلقائيًا أو بالعلاج، وهذه العكوسية هي جوهر تمييزه. التدمير غير العكوس للأسناخ يصف النفاخ لا الربو، والعدوى البكتيرية في المجرى السفلي تصف ذات الرئة، والعدوى الفيروسية تحت المزمار تصف الخانوق. المعلومة المفتاحية: كلمة عكوس هي مفتاح تعريف الربو وتفرقه عن الانسداد الرئوي المزمن.', 'Asthma is by definition a chronic inflammatory disorder of the airways in which bronchospasm, mucosal oedema and mucus plugging narrow the lumen, and the obstruction is reversible either spontaneously or with treatment. Irreversible alveolar destruction describes emphysema rather than asthma; a bacterial infection of the lower airway describes pneumonia; and a viral infection of the subglottic airway describes croup. Key point: the word reversible is the heart of the asthma definition and is what separates it from COPD.', 'ما تعريف الربو؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 2, 'Which of the following best describes the late phase response in asthma?', '["Occurs within minutes","Responds well to Albuterol","Characterized by severe mucosal edema and mucus plugging","Driven solely by histamine release"]'::jsonb, 2, 'الاستجابة المتأخرة تظهر بعد ساعات من التعرض وتتميز بوذمة شديدة في الغشاء المخاطي وسدادات مخاطية تسد المجرى. حدوثها خلال دقائق يصف الاستجابة المبكرة لا المتأخرة، واستجابتها الجيدة للألبوتيرول غير صحيحة لأن الموسّع لا يزيل الوذمة ولا المخاط، وكونها مدفوعة بالهيستامين وحده يصف كذلك الطور المبكر. المعلومة المفتاحية: المبكر تشنج عضلي سريع، والمتأخر التهاب ووذمة ومخاط.', 'The late phase response appears hours after exposure and is dominated by severe mucosal edema and mucus plugging, which is why it does not clear quickly. Saying it occurs within minutes describes the early phase instead; claiming it responds well to Albuterol is wrong because a bronchodilator relaxes smooth muscle but cannot remove wall oedema or mucus plugs; and being driven solely by histamine release again describes the immediate early reaction. Key point: early phase equals rapid smooth muscle spasm, late phase equals inflammation, oedema and mucus.', 'أي مما يلي يصف الاستجابة المتأخرة في الربو على أفضل نحو؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 3, 'Which medication is generally required for the late phase response in asthma?', '["Albuterol","Corticosteroids","Epinephrine","Ipratropium"]'::jsonb, 1, 'الاستجابة المتأخرة التهابية بطبيعتها، ولذلك تحتاج ستيرويدات قشرية تكبح الالتهاب وتقلل الوذمة وإنتاج المخاط. الألبوتيرول موسّع قصبي يعالج التشنج العضلي في الطور المبكر فقط، والإبينفرين محاكٍ ودّي للحالات الشديدة الحادة لا للسيطرة على الالتهاب المتأخر، والإبراتروبيوم مضاد كوليني يقلل الإفراز ولا يوقف الشلال الالتهابي. المعلومة المفتاحية: التهاب متأخر يعني ستيرويدًا قشريًا.', 'The late phase is inflammatory in nature, so corticosteroids are required to suppress the inflammatory cascade, reduce mucosal oedema and cut mucus production. Albuterol is a bronchodilator that relieves the early bronchospasm only, Epinephrine is a sympathomimetic reserved for severe acute distress rather than control of delayed inflammation, and Ipratropium is an anticholinergic that dries secretions without stopping the inflammatory process. Key point: delayed inflammation means corticosteroids.', 'أي دواء يُطلب عادةً لعلاج الاستجابة المتأخرة في الربو؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 4, 'What makes up the "Asthma Triad"?', '["Bronchospasm, Airway Edema, Mucus Plugging","Vasodilation, Airway Edema, Mucus Plugging","Bronchospasm, Alveolar Collapse, Wheezing","Airway Edema, Mucus Plugging, Infection"]'::jsonb, 0, 'ثالوث الربو هو تشنج العضلات الملساء القصبية، ووذمة جدار المجرى، والسدادات المخاطية، وهي ثلاثة آليات متزامنة تضيق اللمعة. التوسع الوعائي ليس أحد أضلاع الثالوث، وانخماص الأسناخ والأزيز نتيجتان وعرَض لا آليتان أساسيتان، والعدوى محرّض محتمل للنوبة لا مكوّن من مكونات الثالوث. المعلومة المفتاحية: ثلاثة أسباب للضيق: عضلة تنقبض، وجدار ينتفخ، ومخاط يسد.', 'The asthma triad is bronchospasm of airway smooth muscle, airway edema of the mucosal wall, and mucus plugging, three simultaneous mechanisms that narrow the lumen. Vasodilation is not one of the three legs of the triad, alveolar collapse and wheezing are downstream consequences and a physical sign rather than primary mechanisms, and infection is a possible trigger of an attack rather than a component of the triad. Key point: three things narrow the tube, muscle that squeezes, a wall that swells, and mucus that blocks.', 'مم يتألف ثالوث الربو؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 5, 'What happens to EtCO2 during the early stage of a mild asthma attack?', '["It drops due to hyperventilation","It rises above normal","It remains completely unchanged","It drops due to hypoventilation"]'::jsonb, 0, 'في بداية النوبة الخفيفة يفرط المريض في التهوية استجابةً للضيق فيطرح كمية أكبر من ثاني أكسيد الكربون وتنخفض القراءة. ارتفاع القيمة فوق الطبيعي يحدث لاحقًا مع التعب التنفسي ونذير التوقف، وبقاؤها دون تغيير لا يعكس التغير الفسيولوجي الحاصل، والانخفاض بسبب نقص التهوية تناقض لأن نقص التهوية يرفع القيمة لا يخفضها. المعلومة المفتاحية: انخفاض مبكر بفرط التهوية، وارتفاع لاحق ينذر بالفشل.', 'Early in a mild attack the patient hyperventilates in response to the sensation of breathlessness, blows off more carbon dioxide, and so the EtCO2 reading drops. A rise above normal happens later with respiratory fatigue and is an ominous pre-arrest sign, remaining completely unchanged does not reflect the physiological shift taking place, and a drop due to hypoventilation is self-contradictory because hypoventilation retains CO2 and raises the number. Key point: EtCO2 falls early from hyperventilation and climbing later warns of impending failure.', 'ماذا يحدث لقيمة ثاني أكسيد الكربون في نهاية الزفير خلال المرحلة المبكرة من نوبة ربو خفيفة؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 6, 'What is the mechanism of action for Albuterol?', '["Anticholinergic","Corticosteroid","Sympathomimetic Beta-2 agonist","Calcium channel blocker"]'::jsonb, 2, 'الألبوتيرول محاكٍ ودّي انتقائي لمستقبلات بيتا-2 في العضلات الملساء القصبية فيرخيها ويوسّع المجرى الهوائي سريعًا. المضاد الكوليني يصف الإبراتروبيوم، والستيرويد القشري يصف الميثيل بريدنيزولون، وحاصر قنوات الكالسيوم يصف كبريتات المغنيسيوم في سياق الربو. المعلومة المفتاحية: بيتا-2 يعني توسيعًا قصبيًا سريعًا وهو الخط الأول.', 'Albuterol is a selective sympathomimetic Beta-2 agonist that stimulates receptors on bronchial smooth muscle, relaxing it and dilating the airway within minutes. Anticholinergic describes Ipratropium, corticosteroid describes Methylprednisolone, and calcium channel blocker describes the way Magnesium Sulfate acts in the asthma setting. Key point: Beta-2 stimulation equals rapid bronchodilation and is the first-line action in asthma.', 'ما آلية عمل الألبوتيرول؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 7, 'What is the standard paramedic dose for Ipratropium via nebulizer?', '["2.5 mg","1.25 mg","0.5 mg","125 mg"]'::jsonb, 2, 'الجرعة المعيارية للإبراتروبيوم رذاذيًا هي نصف ملليغرام، وتُعطى غالبًا ممزوجة مع الألبوتيرول. أما 2.5 ملغ فهي جرعة الألبوتيرول للبالغين، و1.25 ملغ جرعة ألبوتيرول مخفضة تُستعمل عند الأطفال الصغار، و125 ملغ جرعة ضخمة خطرة لا وجود لها في هذا السياق. المعلومة المفتاحية: ألبوتيرول 2.5 ملغ وإبراتروبيوم 0.5 ملغ في الرذاذة نفسها.', 'The standard nebulized paramedic dose of Ipratropium is 0.5 mg, usually mixed into the same nebulizer as Albuterol. The 2.5 mg figure is the adult Albuterol dose, 1.25 mg is a reduced Albuterol dose used in small children, and 125 mg is an enormous and dangerous quantity that does not exist in this context. Key point: Albuterol 2.5 mg plus Ipratropium 0.5 mg in the same nebulizer.', 'ما الجرعة المعيارية للإبراتروبيوم بالبخاخ الرذاذي لدى المسعف؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 8, 'How does Magnesium Sulfate assist in refractory asthma?', '["It is a beta-2 agonist","It dries up mucus","It is a calcium channel blocker that causes profound smooth muscle relaxation","It is an anti-inflammatory"]'::jsonb, 2, 'المغنيسيوم يعمل كحاصر فيزيولوجي لقنوات الكالسيوم فيمنع دخول الكالسيوم إلى الخلية العضلية الملساء ويحدث ارتخاءً عميقًا للقصبات المتشنجة العنيدة. ليس منبّهًا لبيتا-2 فهذا وصف الألبوتيرول، ولا يجفف المخاط فهذا دور الإبراتروبيوم، وليس مضادًا للالتهاب فهذا دور الستيرويدات القشرية. المعلومة المفتاحية: المغنيسيوم سلاح إنقاذ في الربو المعنّد عبر منع الكالسيوم.', 'Magnesium acts as a physiological calcium channel blocker, preventing calcium entry into bronchial smooth muscle cells and producing profound smooth muscle relaxation in airways that no longer respond to standard bronchodilators. It is not a beta-2 agonist, which describes Albuterol, it does not dry up mucus, which is the role of Ipratropium, and it is not an anti-inflammatory, which is the role of corticosteroids. Key point: Magnesium Sulfate is a rescue agent in refractory asthma acting by blocking calcium.', 'كيف تساعد كبريتات المغنيسيوم في الربو المعنّد؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 9, 'What is the standard dose of Epinephrine 1:1000 for severe asthma distress?', '["1 - 2 mg IV","0.3 - 0.5 mg IM","2.5 mg nebulized","0.1 mg IV"]'::jsonb, 1, 'في الضائقة الشديدة يُعطى الإبينفرين 1:1000 بجرعة 0.3 إلى 0.5 ملغ في العضل، وهو المسار الآمن والفعال خارج المستشفى. جرعة 1 إلى 2 ملغ وريديًا مفرطة وخطرة قلبيًا، و2.5 ملغ رذاذيًا هي جرعة الألبوتيرول لا الإبينفرين بهذا التركيز، و0.1 ملغ وريديًا تركيز 1:10000 يُحجز لحالات محددة تحت مراقبة دقيقة. المعلومة المفتاحية: 1:1000 يعني عضليًا بجرعة ثلاثة إلى خمسة أعشار الملليغرام.', 'In severe asthma distress Epinephrine 1:1000 is given as 0.3 - 0.5 mg IM, which is the safe and effective prehospital route when nebulized drug can no longer reach obstructed airways. A dose of 1 - 2 mg IV is grossly excessive and cardiotoxic, 2.5 mg nebulized is the Albuterol dose and not this concentration of Epinephrine, and 0.1 mg IV corresponds to the 1:10000 concentration reserved for specific monitored situations. Key point: 1:1000 means the intramuscular route at 0.3 to 0.5 mg.', 'ما الجرعة المعيارية للإبينفرين بتركيز 1:1000 في ضائقة الربو الشديدة؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 10, 'Why is intubating an asthmatic patient considered dangerous?', '["It reverses the effects of bronchodilators","It cures the underlying inflammation","Positive pressure ventilation exacerbates air trapping and tension pneumothorax risk","It decreases intrathoracic pressure"]'::jsonb, 2, 'المشكلة في الربو زفيرية، فالهواء يدخل ولا يخرج، والتهوية بالضغط الإيجابي تكدّس هواءً إضافيًا وترفع الضغط الزفيري الذاتي حتى يحدث استرواح صدر ضاغط وهبوط في العود الوريدي. القول إن التنبيب يعكس أثر الموسعات غير صحيح، وهو لا يشفي الالتهاب الكامن إطلاقًا، وهو يرفع الضغط داخل الصدر لا يخفضه. المعلومة المفتاحية: عند تنبيب الربو أطل زمن الزفير وقلل التواتر لتفادي احتباس الهواء.', 'Asthma is an expiratory problem in which air enters but cannot leave, so positive pressure ventilation stacks further breaths, exacerbates air trapping, raises auto-PEEP and can produce tension pneumothorax with loss of venous return. Intubation does not reverse the effects of bronchodilators, it certainly does not cure the underlying inflammation, and it raises rather than decreases intrathoracic pressure. Key point: if an asthmatic must be intubated, lengthen expiratory time and slow the rate to avoid breath stacking.', 'لماذا يُعد تنبيب مريض الربو إجراءً خطرًا؟', '{}'::jsonb, 'الربو', false, false, false),
  ((select id from s), 11, 'What are the two primary disease processes encompassed by COPD?', '["Asthma and Pneumonia","Emphysema and Chronic Bronchitis","Bronchiolitis and Emphysema","Chronic Bronchitis and Asthma"]'::jsonb, 1, 'الانسداد الرئوي المزمن مظلة تضم النفاخ والتهاب القصبات المزمن، وهما اضطرابان انسداديان غير عكوسين في جوهرهما. الربو انسداد عكوس ولا يُصنّف ضمن هذه المظلة، وذات الرئة عدوى حادة، والتهاب القصيبات مرض فيروسي عند الرضّع. المعلومة المفتاحية: مظلة الانسداد الرئوي المزمن قائمة على وجهين: النفاخ والتهاب القصبات المزمن.', 'COPD is an umbrella term covering emphysema and chronic bronchitis, two obstructive processes that are essentially irreversible. Asthma and pneumonia do not belong under this umbrella because asthma is reversible obstruction and pneumonia is an acute infection, bronchiolitis and emphysema pairs an infant viral illness with an adult disease, and chronic bronchitis and asthma again wrongly includes the reversible disorder. Key point: the COPD umbrella has two faces, emphysema and chronic bronchitis.', 'ما العمليتان المرضيتان الرئيسيتان اللتان يشملهما الانسداد الرئوي المزمن؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 12, 'What physical trait is classically associated with emphysema due to hyperinflation?', '["JVD","Barrel chest","Peripheral edema","Ascites"]'::jsonb, 1, 'احتباس الهواء المزمن في النفاخ يزيد القطر الأمامي الخلفي للصدر فينشأ ما يُعرف بالصدر البرميلي. انتفاخ الأوردة الوداجية والوذمة المحيطية والاستسقاء علامات فشل قلب أيمن أو قلب رئوي وترتبط أكثر بالتهاب القصبات المزمن المتقدم لا بفرط النفخ ذاته. المعلومة المفتاحية: الصدر البرميلي بصمة فرط النفخ في النفاخ.', 'Chronic air trapping in emphysema hyperinflates the thorax and increases its anteroposterior diameter, producing the classic barrel chest. JVD, peripheral edema and ascites are signs of right heart failure or cor pulmonale and belong more to advanced chronic bronchitis than to hyperinflation itself. Key point: barrel chest is the physical fingerprint of hyperinflation in emphysema.', 'ما السمة الجسدية المرتبطة تقليديًا بالنفاخ بسبب فرط النفخ الرئوي؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 13, 'Patients with emphysema frequently use which breathing technique to create auto-PEEP?', '["Sniffing position","Tripod positioning","Pursed-lip breathing","Panting"]'::jsonb, 2, 'زمّ الشفتين أثناء الزفير يرفع الضغط داخل المجاري الهوائية فيمنع انهيار القصيبات الصغيرة ويحسّن إفراغ الهواء المحتبس. وضعية الاستنشاق وضعية لفتح مجرى الهواء عند التنبيب، والوضعية ثلاثية القوائم تحسّن ميكانيكا العضلات المساعدة لكنها لا تولّد ضغطًا زفيريًا، واللهاث تنفس سطحي سريع يزيد الفراغ الميت. المعلومة المفتاحية: الشفاه المزمومة دعامة هوائية طبيعية تشبه عمل جهاز الضغط الإيجابي.', 'Pursed-lip breathing raises pressure inside the airways during exhalation, which splints the small bronchioles open, prevents their collapse and improves emptying of trapped air, creating auto-PEEP. The sniffing position is an airway alignment position for intubation, tripod positioning improves accessory muscle mechanics but generates no expiratory back pressure, and panting is rapid shallow breathing that only increases dead space ventilation. Key point: pursed lips act as a natural airway splint that mimics CPAP.', 'أي أسلوب تنفس يستخدمه مرضى النفاخ كثيرًا لتوليد ضغط زفيري نهائي ذاتي؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 14, 'What is the primary cause of hypoxia in Chronic Bronchitis?', '["Alveolar destruction","Loss of lung elasticity","Mucous blockade preventing gas from reaching intact alveoli","Air trapping"]'::jsonb, 2, 'في التهاب القصبات المزمن تكون الأسناخ سليمة نسبيًا لكن المخاط الغزير يسدّ الطريق أمام الغاز فيمنع التبادل ويحدث نقص الأكسجة. تدمير الأسناخ وفقدان المرونة واحتباس الهواء ثلاثتها من ملامح النفاخ لا من التهاب القصبات المزمن. المعلومة المفتاحية: مشكلة التهاب القصبات مخاط يسد، ومشكلة النفاخ سطح تبادل ضائع.', 'In chronic bronchitis the alveoli are relatively intact but excessive mucus forms a mucous blockade preventing gas from reaching those alveoli, so hypoxia results from obstruction rather than from lost surface area. Alveolar destruction, loss of lung elasticity and air trapping are all hallmarks of emphysema, not of chronic bronchitis. Key point: chronic bronchitis is a mucus blockade problem while emphysema is a lost gas exchange surface problem.', 'ما السبب الأساسي لنقص الأكسجة في التهاب القصبات المزمن؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 15, 'Which COPD phenotype is commonly referred to as the "Pink Puffer"?', '["Chronic Bronchitis","Emphysema","Asthma","Bronchiolitis"]'::jsonb, 1, 'مريض النفاخ يحافظ على أكسجته بزيادة جهد التنفس والتنفس بشفاه مزمومة فيبدو وردي اللون نحيلًا لاهثًا، ومن هنا وصف النافخ الوردي. التهاب القصبات المزمن يقابله وصف المنتفخ الأزرق، والربو ليس نمطًا من أنماط الانسداد الرئوي المزمن، والتهاب القصيبات مرض رضّع فيروسي. المعلومة المفتاحية: الوردي ينفخ بشفتيه ويحتفظ بأكسجته على حساب جهد كبير.', 'The emphysema patient maintains oxygenation by greatly increasing work of breathing and using pursed-lip breathing, so he appears thin, pink and puffing, which is the origin of the pink puffer label. Chronic bronchitis corresponds to the blue bloater description, asthma is not a COPD phenotype at all, and bronchiolitis is a viral infant illness. Key point: the pink puffer keeps his saturation up at the cost of enormous respiratory effort.', 'أي نمط ظاهري من الانسداد الرئوي المزمن يُشار إليه شائعًا بالنافخ الوردي؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 16, 'Which COPD phenotype is classically associated with the "Blue Bloater" appearance?', '["Emphysema","Chronic Bronchitis","Pneumonia","Croup"]'::jsonb, 1, 'مريض التهاب القصبات المزمن يعاني نقص أكسجة مزمنًا فيبدو مزرقًّا، ومع القلب الرئوي يحتبس السوائل فيبدو منتفخًا، ومن هنا وصف المنتفخ الأزرق. النفاخ يقابله النافخ الوردي، وذات الرئة عدوى حادة، والخانوق التهاب فيروسي في مجرى الطفل العلوي. المعلومة المفتاحية: الأزرق ينتفخ بساقيه بسبب فشل القلب الأيمن.', 'The chronic bronchitis patient is chronically hypoxic and therefore cyanotic, and once cor pulmonale develops he retains fluid and appears bloated, which produces the blue bloater picture. Emphysema corresponds to the pink puffer, pneumonia is an acute infection rather than a chronic phenotype, and croup is a viral upper airway illness of children. Key point: the blue bloater is blue from chronic hypoxia and bloated from right heart failure.', 'أي نمط ظاهري من الانسداد الرئوي المزمن يرتبط تقليديًا بمظهر المنتفخ الأزرق؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 17, 'What causes the right ventricle to fail in Cor Pulmonale?', '["Myocardial ischemia","Hypovolemia","Increased pulmonary vascular resistance from chronic hypoxia","Systemic vasodilation"]'::jsonb, 2, 'نقص الأكسجة المزمن يسبب تضيقًا وعائيًا رئويًا مستمرًا يرفع المقاومة أمام البطين الأيمن حتى يتضخم ثم يفشل، وهذا هو القلب الرئوي. نقص تروية عضلة القلب يصف الاحتشاء وليس الآلية هنا، ونقص حجم الدم يقلل الحمل القبلي ولا يسبب فشلًا أيمن مزمنًا، وتوسع الأوعية الجهازي يخفض المقاومة ولا يحمّل البطين الأيمن. المعلومة المفتاحية: نقص أكسجة مزمن يرفع مقاومة الرئة فيفشل البطين الأيمن.', 'Chronic hypoxia causes sustained hypoxic pulmonary vasoconstriction, and this increased pulmonary vascular resistance loads the right ventricle until it hypertrophies and finally fails, which is cor pulmonale. Myocardial ischemia describes infarction and is not the mechanism here, hypovolemia reduces preload rather than causing chronic right heart failure, and systemic vasodilation lowers resistance and does not burden the right ventricle. Key point: chronic hypoxia raises pulmonary resistance and the right ventricle fails behind it.', 'ما الذي يسبب فشل البطين الأيمن في القلب الرئوي؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 18, 'Which of the following is a classic sign of Cor Pulmonale?', '["Flat neck veins","Clear lung sounds","Jugular vein distention (JVD) and peripheral edema","Pink skin"]'::jsonb, 2, 'فشل البطين الأيمن يرفع الضغط في الدوران الوريدي الجهازي فتنتفخ الأوردة الوداجية وتظهر وذمة في الأطراف السفلية. الأوردة المسطّحة تدل على نقص حجم لا على احتقان، والأصوات الرئوية النقية لا تميّز الحالة، والبشرة الوردية تناقض الزرقة المتوقعة في هذا النمط. المعلومة المفتاحية: احتقان وريدي ووذمة محيطية هما وجه القلب الرئوي السريري.', 'Right ventricular failure backs pressure up into the systemic venous circulation, producing jugular vein distention (JVD) and peripheral edema in the dependent limbs. Flat neck veins indicate hypovolemia rather than venous congestion, clear lung sounds do not distinguish this condition, and pink skin contradicts the cyanosis expected in this phenotype. Key point: venous congestion with JVD and dependent oedema is the clinical face of cor pulmonale.', 'أي مما يلي علامة كلاسيكية للقلب الرئوي؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 19, 'What is the number one cause of acute COPD exacerbations?', '["Missing a dose of Albuterol","Infections","Cardiac events","Exercise"]'::jsonb, 1, 'العدوى التنفسية سواء كانت جرثومية أو فيروسية هي المحرّض الأول لتفاقم الانسداد الرئوي المزمن لأنها تزيد الإفرازات والالتهاب وتخل بالتوازن الهش أصلًا. إغفال جرعة الألبوتيرول قد يسهم لكنه ليس السبب الأول، والأحداث القلبية تفاقم الحالة لكنها أقل تكرارًا، والجهد البدني قد يكشف الأعراض ولا يشكل السبب الأشيع. المعلومة المفتاحية: أول ما تفكر فيه عند تفاقم الانسداد الرئوي المزمن هو وجود عدوى.', 'Respiratory infections, bacterial or viral, are the single most common trigger of acute COPD exacerbation because they increase secretions and inflammation in lungs whose reserve is already minimal. Missing a dose of Albuterol may contribute but is not the leading cause, cardiac events can worsen the picture but are less frequent triggers, and exercise may unmask symptoms without being the commonest precipitant. Key point: when a COPD patient decompensates, suspect infection first.', 'ما السبب الأول لتفاقم الانسداد الرئوي المزمن الحاد؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 20, 'Why is CPAP highly effective for severe COPD exacerbations?', '["It reverses the underlying bacterial infection","It completely cures emphysema","It splints small airways open, preventing collapse during exhalation","It decreases SpO2"]'::jsonb, 2, 'الضغط الإيجابي المستمر يعمل كدعامة هوائية تمنع انهيار القصيبات الصغيرة في الزفير فيتحسن إفراغ الهواء المحتبس ويقل جهد التنفس. هو لا يعالج العدوى الكامنة وهذا دور الصادات، ولا يشفي النفاخ لأن التدمير السنخي غير عكوس، وهو يرفع إشباع الأكسجين لا يخفضه. المعلومة المفتاحية: الضغط الإيجابي المستمر دعامة تفتح المجاري الصغيرة وتقلد التنفس بشفاه مزمومة.', 'CPAP splints small airways open, preventing collapse during exhalation, which improves emptying of trapped gas, recruits alveoli and dramatically reduces work of breathing. It does not reverse the underlying bacterial infection, which is the job of antibiotics, it cannot cure emphysema because alveolar destruction is irreversible, and it raises rather than decreases SpO2. Key point: CPAP is a pneumatic splint that reproduces the effect of pursed-lip breathing.', 'لماذا يكون جهاز الضغط الإيجابي المستمر شديد الفعالية في التفاقم الشديد للانسداد الرئوي المزمن؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 21, 'Which medication is especially effective in COPD for drying secretions?', '["Epinephrine","Magnesium Sulfate","Ipratropium","Methylprednisolone"]'::jsonb, 2, 'الإبراتروبيوم مضاد كوليني يثبط التأثير المبهمي فيقلل الإفراز المخاطي ويوسّع القصبات، وهذا يجعله مفيدًا بشكل خاص في التهاب القصبات المزمن الغزير الإفرازات. الإبينفرين محاكٍ ودّي لحالات الضائقة الشديدة، وكبريتات المغنيسيوم لارتخاء العضلات الملساء في الربو المعنّد، والميثيل بريدنيزولون ستيرويد يعالج الالتهاب لا الإفراز الحاد. المعلومة المفتاحية: مضاد كوليني يعني مجرى هوائي أوسع وأكثر جفافًا.', 'Ipratropium is an anticholinergic that blocks vagal tone, so it both dilates bronchi and reduces mucus secretion, which makes it especially valuable in the secretion-heavy COPD patient. Epinephrine is a sympathomimetic for severe distress, Magnesium Sulfate relaxes smooth muscle in refractory asthma, and Methylprednisolone treats inflammation over hours rather than drying acute secretions. Key point: anticholinergic means a wider and drier airway.', 'أي دواء فعال بشكل خاص في الانسداد الرئوي المزمن لتجفيف الإفرازات؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, false),
  ((select id from s), 22, 'Pneumonia is characterized by alveoli filling with what substances?', '["Histamine and leukotrienes","Fluid, pus (exudate), and cellular debris","Air and surfactant","Blood only"]'::jsonb, 1, 'في ذات الرئة تمتلئ الأسناخ بالسائل الالتهابي والقيح والفتات الخلوي فينشأ خلل في نسبة التهوية إلى التروية على شكل تحويلة. الهيستامين والليوكوترينات وسائط التهابية في الربو والتأق لا محتوى سنخي، والهواء والمادة الخافضة للتوتر السطحي هما المحتوى الطبيعي للسنخ السليم، والدم وحده يصف النزف الرئوي لا ذات الرئة. المعلومة المفتاحية: سنخ ممتلئ بالنضحة يعني تحويلة ونقص أكسجة.', 'In pneumonia the alveoli fill with fluid, pus (exudate), and cellular debris, which creates a shunt because blood continues to perfuse alveoli that can no longer exchange gas. Histamine and leukotrienes are inflammatory mediators in asthma and anaphylaxis rather than alveolar contents, air and surfactant are the normal contents of a healthy alveolus, and blood only describes pulmonary haemorrhage rather than pneumonia. Key point: alveoli full of exudate means shunt physiology and hypoxia.', 'تتميز ذات الرئة بامتلاء الأسناخ بأي من المواد التالية؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 23, 'Hospital-Acquired Pneumonia (HAP) develops after how many hours of admission?', '["12 hours","24 hours","48+ hours","72 hours"]'::jsonb, 2, 'التعريف المعتمد أن ذات الرئة المكتسبة من المستشفى تظهر بعد ثمان وأربعين ساعة أو أكثر من القبول، لأن ما قبل ذلك يُفترض أنه كان في طور الحضانة قبل الدخول. مدة اثنتي عشرة ساعة وأربع وعشرين ساعة أقصر من أن تسمح بالاستعمار الجرثومي المستشفوي، واثنتان وسبعون ساعة متأخرة عن الحد المتفق عليه. المعلومة المفتاحية: ثمان وأربعون ساعة هي الخط الفاصل بين المجتمع والمستشفى.', 'By accepted definition Hospital-Acquired Pneumonia develops 48+ hours after admission, because anything appearing earlier is assumed to have been incubating before the patient arrived. Twelve hours and 24 hours are too short to allow hospital flora to colonise and cause disease, and 72 hours is later than the agreed cut-off. Key point: 48 hours is the dividing line between community-acquired and hospital-acquired pneumonia.', 'بعد كم ساعة من القبول في المستشفى تُعد ذات الرئة مكتسبة من المستشفى؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 24, 'What causes aspiration pneumonia?', '["Inhaling pollen or dust","A viral upper respiratory infection","Inhaling gastric contents, food, or saliva into the lungs","Thermal injury"]'::jsonb, 2, 'تنشأ ذات الرئة الاستنشاقية حين تدخل محتويات المعدة الحمضية أو الطعام أو اللعاب إلى الشجرة القصبية فتحدث أذية كيميائية ثم عدوى ثانوية. استنشاق اللقاح أو الغبار يثير تفاعلات تحسسية لا هذا النمط، والعدوى الفيروسية العلوية تسبب نزلة أو خانوقًا، والإصابة الحرارية تسبب حرقًا استنشاقيًا مختلف الآلية. المعلومة المفتاحية: كل من ضعفت لديه منعكسات حماية المجرى معرّض للاستنشاق.', 'Aspiration pneumonia is caused by inhaling gastric contents, food, or saliva into the lungs, where acidic material produces a chemical pneumonitis that is then complicated by secondary bacterial infection. Inhaling pollen or dust triggers allergic airway responses instead, a viral upper respiratory infection produces coryza or croup, and thermal injury causes an inhalation burn with an entirely different mechanism. Key point: anyone with impaired airway protective reflexes is at risk of aspiration.', 'ما الذي يسبب ذات الرئة الاستنشاقية؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 25, 'Aspiration pneumonia poses the highest risk in which patient group?', '["Young adult males","Stroke patients and alcoholics","Pregnant women","Asthmatics"]'::jsonb, 1, 'مرضى السكتة الدماغية يعانون عسر بلع وضعف منعكس السعال، والمدمنون على الكحول يعانون تدنيًا في مستوى الوعي، وكلا الحالين يفتح الباب أمام الاستنشاق. الذكور الشباب الأصحاء يحتفظون بمنعكسات سليمة، والحوامل رغم ارتفاع خطر الاستنشاق أثناء التخدير لسن غير الفئة الأعلى خطرًا هنا، ومرضى الربو خطرهم انسدادي لا استنشاقي. المعلومة المفتاحية: ضعف منعكسات المجرى الهوائي هو عامل الخطر الحاسم.', 'Stroke patients and alcoholics carry the highest risk because stroke causes dysphagia and a blunted cough reflex while intoxication depresses level of consciousness, and both allow material to enter the airway unopposed. Young adult males have intact protective reflexes, pregnant women face increased aspiration risk mainly under anaesthesia rather than being the highest-risk prehospital group, and asthmatics face an obstructive rather than an aspiration risk. Key point: loss of airway protective reflexes is the decisive risk factor.', 'في أي فئة من المرضى تشكل ذات الرئة الاستنشاقية أعلى خطر؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 26, 'Which population is highly susceptible to atypical and fungal pneumonias?', '["Immunocompromised patients","Healthy children","Patients with broken bones","Adults ages 20-40"]'::jsonb, 0, 'نقص المناعة سواء بسبب فيروس العوز المناعي أو العلاج الكيميائي أو الأدوية المثبطة يفتح المجال لعوامل ممرضة انتهازية غير نمطية وفطرية لا تصيب أصحاء المناعة عادة. الأطفال الأصحاء يصابون بالأنماط الفيروسية والجرثومية الشائعة، والكسور العظمية لا تغير المناعة وإن ارتبطت بانصمام شحمي، والبالغون بين العشرين والأربعين من أقوى الفئات مناعيًا. المعلومة المفتاحية: العامل الممرض غير المألوف يستدعي السؤال عن حالة المناعة.', 'Immunocompromised patients, whether from HIV, chemotherapy or immunosuppressive drugs, are highly susceptible to atypical and fungal organisms that rarely cause disease in a competent host. Healthy children develop the common viral and typical bacterial pneumonias, patients with broken bones have no altered immunity even though they risk fat embolism, and adults ages 20-40 represent one of the most immunologically robust groups. Key point: an unusual organism should prompt the question of what has weakened the immune system.', 'أي فئة سكانية شديدة القابلية للإصابة بذات الرئة غير النمطية والفطرية؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 27, 'What is a classic sign of lobar pneumonia upon auscultation?', '["Diffuse wheezing","Inspiratory stridor","Localized crackles (rales) in one specific lung field","Completely clear lung sounds"]'::jsonb, 2, 'إصابة فص واحد بالنضحة تعطي خراخر رطبة محصورة في حقل رئوي بعينه، وهذا التوضّع هو ما يميز ذات الرئة الفصية. الأزيز المنتشر علامة تضيّق قصبي منتشر كما في الربو والانسداد الرئوي المزمن، والصرير الشهيقي دليل انسداد في المجرى العلوي، والأصوات النقية تمامًا تنفي وجود ارتشاح سنخي. المعلومة المفتاحية: خراخر موضعية في جهة واحدة تعني عدوى فصية حتى يثبت العكس.', 'Consolidation of a single lobe produces localized crackles (rales) in one specific lung field, and it is this focal distribution that characterises lobar pneumonia. Diffuse wheezing indicates widespread bronchoconstriction as in asthma or COPD, inspiratory stridor points to upper airway obstruction, and completely clear lung sounds would argue against alveolar infiltrate altogether. Key point: unilateral focal crackles mean lobar infection until proven otherwise.', 'ما العلامة الكلاسيكية لذات الرئة الفصية عند الإصغاء؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 28, 'What is the focus of prehospital management for a pneumonia patient exhibiting signs of sepsis and hypotension?', '["Diuretics","Aggressive isotonic IV fluid resuscitation","Nebulized Ipratropium","CPAP"]'::jsonb, 1, 'الإنتان يسبب توسعًا وعائيًا وتسربًا شعريًا ونقص حجم نسبيًا، فالعلاج المحوري قبل المستشفى هو إنعاش قوي بمحلول متساوي التوتر لاستعادة التروية. المدرّات البولية تزيد نقص الحجم وتفاقم الهبوط، والإبراتروبيوم الرذاذي لا يعالج الصدمة الإنتانية، وجهاز الضغط الإيجابي المستمر قد يفيد الأكسجة لكنه يخفض العود الوريدي ويسوء الضغط. المعلومة المفتاحية: هبوط ضغط إنتاني يعني سوائل أولًا لا مدرّات.', 'Sepsis produces vasodilation, capillary leak and a relative hypovolaemia, so the prehospital priority is aggressive isotonic IV fluid resuscitation to restore perfusion pressure. Diuretics would deepen the volume deficit and worsen the hypotension, nebulized Ipratropium does nothing for septic shock, and CPAP may improve oxygenation but reduces venous return and can drop the pressure further in a hypotensive patient. Key point: septic hypotension calls for fluids first, never diuretics.', 'ما محور التدبير قبل المستشفى لمريض ذات رئة تظهر عليه علامات إنتان وهبوط ضغط؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 29, 'Bronchiolitis primarily affects which demographic?', '["Elderly adults","Teenagers","Infants and toddlers (peak age 2-6 months)","School-aged children"]'::jsonb, 2, 'القصيبات عند الرضيع ضيقة أصلًا فأي وذمة أو مخاط فيها يسبب انسدادًا كبيرًا، ولذلك تتركز الإصابة في الرضّع والدارجين وذروتها بين الشهرين والستة أشهر. كبار السن يصابون بذات الرئة والانسداد الرئوي المزمن، والمراهقون وأطفال المدرسة تتسع مجاريهم الهوائية فلا يشكلون الفئة النموذجية. المعلومة المفتاحية: قصيبات ضيقة عند رضيع تعني ضائقة تنفسية سريعة.', 'Bronchiolitis primarily strikes infants and toddlers (peak age 2-6 months) because their bronchioles are already tiny, so a small amount of viral oedema and mucus produces critical narrowing. Elderly adults typically develop pneumonia and COPD exacerbations, and teenagers and school-aged children have airways wide enough that the same inflammation causes far less obstruction. Key point: narrow infant bronchioles turn minor swelling into major respiratory distress.', 'أي فئة عمرية يصيبها التهاب القصيبات بشكل أساسي؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 30, 'What is the cause of over 80% of bronchiolitis cases?', '["Streptococcus pneumoniae","Respiratory Syncytial Virus (RSV)","Parainfluenza virus","Haemophilus influenzae type b"]'::jsonb, 1, 'الفيروس المخلوي التنفسي مسؤول عن أكثر من ثمانين بالمئة من حالات التهاب القصيبات وينتشر بشدة في مواسم الشتاء. المكورة الرئوية العقدية سبب شائع لذات الرئة الجرثومية، وفيروس نظير الإنفلونزا هو المسبب الأشيع للخانوق، والمستدمية النزلية من النمط ب ترتبط بالتهاب لسان المزمار. المعلومة المفتاحية: التهاب القصيبات فيروسي والمخلوي التنفسي سيده.', 'Respiratory Syncytial Virus (RSV) accounts for well over 80% of bronchiolitis cases and spreads intensely in winter months. Streptococcus pneumoniae is a leading cause of bacterial pneumonia, Parainfluenza virus is the classic cause of croup, and Haemophilus influenzae type b is associated with epiglottitis. Key point: bronchiolitis is viral and RSV is the dominant agent.', 'ما المسبب لأكثر من ثمانين بالمئة من حالات التهاب القصيبات؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 31, 'Because infants are obligate nose breathers, what can cause severe distress in bronchiolitis?', '["Minor throat irritation","Nasal congestion alone","Ear infections","Mild fever"]'::jsonb, 1, 'الرضيع لا يجيد التنفس الفموي التعويضي، فانسداد المنخرين بالمفرزات وحده كافٍ لإحداث ضائقة تنفسية شديدة، ولهذا الشفط الأنفي إجراء علاجي مهم. تهيج الحلق البسيط والتهابات الأذن لا تعيق تدفق الهواء، والحمى الخفيفة ترفع الاستهلاك الأكسجيني قليلًا دون أن تسد المجرى. المعلومة المفتاحية: شفط الأنف عند الرضيع تدخل بسيط بأثر كبير.', 'Because infants are obligate nose breathers and cannot reliably switch to mouth breathing, nasal congestion alone can obstruct their only airway and cause severe distress, which is why nasal suctioning is a genuinely therapeutic intervention. Minor throat irritation and ear infections do not obstruct airflow, and a mild fever raises oxygen consumption slightly without blocking the airway. Key point: suctioning an infant nose is a simple intervention with a large effect.', 'بما أن الرضّع يتنفسون من الأنف إلزاميًا، فما الذي قد يسبب ضائقة شديدة في التهاب القصيبات؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 32, 'In its early stages, bronchiolitis typically resembles:', '["A severe asthma attack","Anaphylaxis","A common cold","Epiglottitis"]'::jsonb, 2, 'يبدأ التهاب القصيبات بأعراض علوية بسيطة من سيلان أنف وعطاس وسعال وحمى خفيفة فيبدو كنزلة برد، ثم يتدهور خلال أيام إلى ضائقة سفلية. نوبة الربو الشديدة تبدأ بضيق وأزيز حادين، والتأق بدؤه فجائي ومصحوب بشرى ووذمة، والتهاب لسان المزمار عاصف مع حمى عالية وسيلان لعاب. المعلومة المفتاحية: بداية شبيهة بالزكام لا تنفي تدهورًا خطيرًا خلال يومين إلى ثلاثة.', 'Bronchiolitis begins with mild upper respiratory symptoms of rhinorrhoea, sneezing, cough and low-grade fever, so early on it resembles a common cold before deteriorating over two to three days into lower airway distress. A severe asthma attack starts with abrupt wheeze and dyspnoea, anaphylaxis is sudden with urticaria and angioedema, and epiglottitis is fulminant with high fever and drooling. Key point: a cold-like onset does not exclude serious deterioration within a few days.', 'في مراحله المبكرة، يشبه التهاب القصيبات عادةً:', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 33, 'Which of the following is a sign of severe deterioration in bronchiolitis?', '["Mild runny nose","Playfulness","Severe tachypnea, profound retractions, and poor feeding","Low-grade fever"]'::jsonb, 2, 'تسرع النفس الشديد والسحب العميق وضعف الرضاعة ثلاثتها تدل على جهد تنفسي مرهق وقرب استنزاف احتياطي الرضيع. سيلان الأنف الخفيف والحمى المنخفضة أعراض الطور المبكر البسيط، والمرح واللعب علامة اطمئنان تدل على تعويض جيد. المعلومة المفتاحية: رضيع لا يرضع ويسحب بعمق هو رضيع على حافة الفشل التنفسي.', 'Severe tachypnea, profound retractions, and poor feeding together indicate exhausting respiratory effort and an infant close to depleting his reserve, since feeding is abandoned when breathing consumes all available energy. A mild runny nose and a low-grade fever belong to the early mild phase, and playfulness is a reassuring sign of good compensation. Key point: an infant who will not feed and is retracting deeply is on the edge of respiratory failure.', 'أي مما يلي علامة تدهور شديد في التهاب القصيبات؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 34, 'If nebulized Epinephrine is administered for bronchiolitis or croup, what must the paramedic monitor for?', '["Hypoglycemia","A rebound effect as the medication wears off","Sudden hypothermia","Severe bradycardia"]'::jsonb, 1, 'الإبينفرين الرذاذي يقبض الأوعية موضعيًا فيقلل الوذمة مؤقتًا، وعند زوال أثره قد تعود الوذمة والصرير بشدة، فتلزم مراقبة مطوّلة ونقل حتى لو تحسن الطفل. نقص السكر ليس أثرًا متوقعًا للإبينفرين بل هو يرفع السكر، وانخفاض الحرارة المفاجئ لا علاقة له بالدواء، والإبينفرين يسبب تسرع قلب لا بطئًا شديدًا. المعلومة المفتاحية: تحسّن بعد الإبينفرين الرذاذي لا يعني إلغاء النقل.', 'Nebulized Epinephrine works by local vasoconstriction that temporarily shrinks airway oedema, so the paramedic must monitor for a rebound effect as the medication wears off, with return of stridor and distress, which is why prolonged observation and transport are required even after apparent improvement. Hypoglycemia is not expected because Epinephrine raises blood glucose, sudden hypothermia is unrelated to the drug, and Epinephrine causes tachycardia rather than severe bradycardia. Key point: improvement after nebulized Epinephrine never cancels the need for transport.', 'إذا أُعطي الإبينفرين رذاذيًا لالتهاب القصيبات أو الخانوق، فما الذي يجب على المسعف مراقبته؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, false),
  ((select id from s), 35, 'The normal pleural space maintains what type of pressure relative to the atmosphere?', '["Positive pressure","Constant negative pressure","Zero pressure","Alternating pressure"]'::jsonb, 1, 'الحيز الجنبي يحافظ على ضغط سلبي ثابت أقل من الضغط الجوي، وهذا ما يبقي الرئة ملتصقة بجدار الصدر ومنتفخة. الضغط الإيجابي حالة مرضية تحدث في الاسترواح الضاغط، والضغط الصفري يعني تعادلًا يفقد الرئة تمددها، والضغط المتناوب يصف ضغط المجاري الهوائية لا الحيز الجنبي. المعلومة المفتاحية: السلبية الجنبية هي ما يبقي الرئة مفتوحة.', 'The normal pleural space maintains a constant negative pressure below atmospheric, and this is what keeps the visceral and parietal layers apposed so the lung stays expanded with the chest wall. Positive pressure is a pathological state seen in tension pneumothorax, zero pressure means equalisation and loss of lung expansion, and alternating pressure describes airway pressure rather than the pleural space. Key point: pleural negativity is what holds the lung open.', 'أي نوع من الضغط يحافظ عليه الحيز الجنبي الطبيعي نسبةً إلى الضغط الجوي؟', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 36, 'A pneumothorax occurs when:', '["Alveoli fill with fluid","The trachea swells","A breach in the lung or chest wall allows air into the pleural space","A clot blocks the pulmonary artery"]'::jsonb, 2, 'أي خرق في نسيج الرئة أو في جدار الصدر يسمح للهواء بدخول الحيز الجنبي فيضيع الضغط السلبي وتنهار الرئة جزئيًا أو كليًا. امتلاء الأسناخ بالسائل يصف الوذمة الرئوية أو ذات الرئة، وتورم الرغامى يصف انسدادًا في المجرى العلوي، وانسداد الشريان الرئوي بخثرة يصف الانصمام الرئوي. المعلومة المفتاحية: هواء في الحيز الجنبي يعني ضياع السلبية وانهيار الرئة.', 'A pneumothorax occurs when a breach in the lung or chest wall allows air into the pleural space, destroying the negative pressure so the lung collapses partially or completely. Alveoli filling with fluid describes pulmonary edema or pneumonia, a swollen trachea describes upper airway obstruction, and a clot blocking the pulmonary artery describes pulmonary embolism. Key point: air in the pleural space means loss of negative pressure and lung collapse.', 'يحدث استرواح الصدر عندما:', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 37, 'What is a common cause of secondary spontaneous pneumothorax?', '["Gunshot wound","Existing lung disease such as COPD or Asthma","Croup","DVT"]'::jsonb, 1, 'الاسترواح العفوي الثانوي يقع على أرضية مرض رئوي سابق كالانسداد الرئوي المزمن أو الربو حيث تتشكل فقاعات هشة قابلة للتمزق. الجرح الناري يسبب استرواحًا رضحيًا لا عفويًا، والخانوق مرض في المجرى العلوي عند الأطفال، وخثار الأوردة العميقة يقود إلى الانصمام الرئوي لا إلى الاسترواح. المعلومة المفتاحية: كلمة ثانوي تعني وجود مرض رئوي كامن مسبق.', 'Secondary spontaneous pneumothorax occurs on the background of existing lung disease such as COPD or Asthma, where fragile blebs and weakened alveolar walls rupture without any trauma. A gunshot wound produces a traumatic rather than a spontaneous pneumothorax, croup is a paediatric upper airway illness, and DVT leads to pulmonary embolism rather than to pneumothorax. Key point: the word secondary signals underlying pre-existing lung disease.', 'ما السبب الشائع لاسترواح الصدر العفوي الثانوي؟', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 38, 'An open pneumothorax caused by penetrating trauma is also known as:', '["A tension pneumothorax","Cor pulmonale","A sucking chest wound","Hemothorax"]'::jsonb, 2, 'الاسترواح المفتوح يسمح بمرور الهواء من الخارج إلى الحيز الجنبي عبر الجرح فيصدر صوت مص مميز، ومن هنا التسمية بجرح الصدر الماص. الاسترواح الضاغط حالة تالية تتطور عندما يُحبس الهواء بصمام أحادي الاتجاه، والقلب الرئوي فشل بطين أيمن مزمن، وتدمّي الصدر تجمع دم لا هواء في الحيز الجنبي. المعلومة المفتاحية: جرح مفتوح في الصدر يمص الهواء يحتاج تغطية فورية.', 'An open pneumothorax from penetrating trauma lets outside air move through the defect into the pleural space with an audible noise on inspiration, which is why it is called a sucking chest wound. A tension pneumothorax is a later development once a one-way valve traps air under pressure, cor pulmonale is chronic right heart failure, and hemothorax is blood rather than air collecting in the pleural space. Key point: an open chest defect that draws air in needs immediate covering.', 'استرواح الصدر المفتوح الناجم عن رضح نافذ يُعرف أيضًا باسم:', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 39, 'What is the immediate definitive action upon discovering a sucking chest wound?', '["Intubate the patient","Cover the wound with a gloved hand, then apply a vented chest seal","Perform a needle thoracostomy","Administer Albuterol"]'::jsonb, 1, 'الإجراء الفوري هو سدّ الجرح باليد المرتدية للقفاز لإيقاف دخول الهواء، ثم استبدالها بضماد صدري منفّس يسمح بخروج الهواء ويمنع دخوله فيقي من تطور استرواح ضاغط. التنبيب بالضغط الإيجابي قد يعجّل بالاسترواح الضاغط دون معالجة الجرح، وبزل الإبرة يُحجز لحال ظهور الاسترواح الضاغط فعليًا، والألبوتيرول لا دور له في الرضح النافذ. المعلومة المفتاحية: يد أولًا ثم ضماد منفّس، وراقب تطور الاسترواح الضاغط.', 'The immediate definitive action is to cover the wound with a gloved hand, then apply a vented chest seal, because the hand stops air entry instantly and the vented dressing then lets trapped air escape while preventing further entry, guarding against tension. Intubating the patient adds positive pressure and can precipitate tension without addressing the defect, needle thoracostomy is reserved for tension that has actually developed, and Albuterol has no role in penetrating chest trauma. Key point: hand first, then a vented seal, and keep watching for tension.', 'ما الإجراء الحاسم الفوري عند اكتشاف جرح صدر ماص؟', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 40, 'What clinically differentiates a tension pneumothorax from a simple pneumothorax?', '["Presence of wheezing","Hypotension and severe hemodynamic compromise","Pleuritic chest pain","Decreased breath sounds"]'::jsonb, 1, 'الفارق الجوهري هو الأثر الدوراني: الضغط المتصاعد يضغط الأوعية الكبيرة ويقلل العود الوريدي فيهبط الضغط وتظهر صدمة انسدادية. الأزيز ليس من علامات الاسترواح، والألم الجنبي ونقص أصوات التنفس موجودان في الاسترواح البسيط أيضًا فلا يميّزان بينهما. المعلومة المفتاحية: ما يجعل الاسترواح ضاغطًا هو انهيار الدورة الدموية لا مجرد الأعراض التنفسية.', 'What separates the two is the circulatory effect, since rising pleural pressure compresses the great vessels, reduces venous return and produces hypotension and severe hemodynamic compromise, that is obstructive shock. Wheezing is not a feature of pneumothorax at all, and pleuritic chest pain and decreased breath sounds occur in simple pneumothorax as well, so neither can distinguish the two. Key point: tension is defined by circulatory collapse, not by respiratory symptoms alone.', 'ما الذي يميّز سريريًا استرواح الصدر الضاغط عن الاسترواح البسيط؟', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 41, 'Which of the following is a late and often terminal sign of a tension pneumothorax?', '["Tachycardia","Tachypnea","Tracheal deviation","Pleuritic chest pain"]'::jsonb, 2, 'انحراف الرغامى يتطلب ضغطًا هائلًا يزيح المنصف كاملًا، ولذلك يظهر متأخرًا جدًا وغالبًا قبيل توقف القلب. تسرع القلب وتسرع النفس علامتان مبكرتان تعويضيتان، والألم الجنبي عرَض بدئي شائع، فلا يصح انتظار أي منها كدليل تأخر. المعلومة المفتاحية: لا تنتظر انحراف الرغامى لتشخّص وتعالج الاسترواح الضاغط.', 'Tracheal deviation requires enough accumulated pressure to shift the entire mediastinum, so it appears very late and often immediately before cardiac arrest. Tachycardia and tachypnea are early compensatory findings, and pleuritic chest pain is a common initial symptom, so none of these three signals late decompensation. Key point: never wait for tracheal deviation before diagnosing and decompressing a tension pneumothorax.', 'أي مما يلي علامة متأخرة وغالبًا نهائية في استرواح الصدر الضاغط؟', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 42, 'What is a key auscultation finding in a pneumothorax?', '["Bilateral crackles","Inspiratory stridor","Decreased or absent breath sounds on the affected side","Diffuse wheezing"]'::jsonb, 2, 'انهيار الرئة يمنع دخول الهواء إليها فتنقص أصوات التنفس أو تغيب في الجانب المصاب مع بقائها في الجانب السليم. الخراخر الثنائية تشير إلى وذمة رئوية، والصرير الشهيقي يدل على انسداد في المجرى العلوي، والأزيز المنتشر يدل على تضيق قصبي. المعلومة المفتاحية: غياب أحادي الجانب لأصوات التنفس مع ضيق مفاجئ يعني استرواحًا.', 'The collapsed lung admits no air, so the key finding is decreased or absent breath sounds on the affected side while the opposite side remains normal. Bilateral crackles suggest pulmonary edema, inspiratory stridor indicates upper airway obstruction, and diffuse wheezing indicates bronchoconstriction. Key point: unilateral loss of breath sounds with sudden dyspnoea means pneumothorax.', 'ما الموجودة الإصغائية الأساسية في استرواح الصدر؟', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 43, 'What is the absolute prehospital indication for performing a needle thoracostomy?', '["Simple spontaneous pneumothorax with normal blood pressure","Tension pneumothorax accompanied by severe hemodynamic compromise (obstructive shock)","Any penetrating chest wound","Pleuritic chest pain with clear breath sounds"]'::jsonb, 1, 'بزل الإبرة إجراء إنقاذي يُحجز للاسترواح الضاغط حين يقترن باختلال ديناميكي شديد وصدمة انسدادية. الاسترواح البسيط مع ضغط طبيعي يُدبَّر بالأكسجين والمراقبة والنقل، وأي جرح نافذ لا يبرر البزل بلا علامات ضغط، وألم جنبي مع أصوات نقية لا يشير إلى استرواح أصلًا. المعلومة المفتاحية: البزل يتبع الاختلال الدوراني لا مجرد وجود هواء.', 'Needle thoracostomy is a life-saving procedure reserved for tension pneumothorax accompanied by severe hemodynamic compromise (obstructive shock), where the pressure must be released immediately. Simple spontaneous pneumothorax with normal blood pressure is managed with oxygen, monitoring and transport, any penetrating chest wound without tension signs does not justify decompression, and pleuritic chest pain with clear breath sounds does not even suggest pneumothorax. Key point: decompression follows haemodynamic collapse, not the mere presence of pleural air.', 'ما الدلالة المطلقة لإجراء بزل الصدر بالإبرة قبل المستشفى؟', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 44, 'According to ATLS, what is the preferred site for a needle thoracostomy?', '["2nd Intercostal Space, Midclavicular Line","5th Intercostal Space, Anterior Axillary Line","4th Intercostal Space, Midaxillary Line","Subxiphoid"]'::jsonb, 1, 'صار الموضع المفضل حديثًا الفراغ الوربي الخامس على الخط الإبطي الأمامي لأن جدار الصدر هناك أرق فتصل الإبرة إلى الحيز الجنبي بنجاح أكبر. الفراغ الثاني على الخط الترقوي المتوسط موضع تقليدي بديل وكثيرًا ما تفشل الإبرة في اختراقه لسماكة النسج، والفراغ الرابع على الخط الإبطي المتوسط موضع أنبوب الصدر، وأسفل الناتئ الرهابي موضع بزل التامور. المعلومة المفتاحية: الخامس الإبطي الأمامي هو المفضل والثاني الترقوي المتوسط بديل.', 'According to ATLS the preferred site is the 5th Intercostal Space, Anterior Axillary Line, because the chest wall is thinner there and the needle far more reliably reaches the pleural space. The 2nd Intercostal Space, Midclavicular Line is the traditional alternative where thick tissue often causes failure, the 4th Intercostal Space, Midaxillary Line is the chest tube site, and the subxiphoid approach is used for pericardiocentesis. Key point: fifth space anterior axillary is preferred, with second space midclavicular as the alternative.', 'وفقًا لبروتوكول دعم الحياة المتقدم في الرضوح، ما الموضع المفضل لبزل الصدر بالإبرة؟', '{}'::jsonb, 'استرواح الصدر وإصابات الجنبة', false, false, false),
  ((select id from s), 45, 'The narrowest part of the pediatric airway (under 8 years old) is the:', '["Glottic opening (vocal cords)","Epiglottis","Cricoid ring (subglottic area)","Carina"]'::jsonb, 2, 'عند الطفل دون الثامنة تكون الحلقة الحلقية تحت المزمار أضيق نقطة في المجرى، ولهذا تسبب وذمة بسيطة هناك انسدادًا كبيرًا. فتحة المزمار هي الأضيق عند البالغ لا الطفل، ولسان المزمار بنية غضروفية فوق المزمار لا نقطة تضيق ثابتة، والجؤجؤ نقطة تفرع الرغامى بعيدًا عن التضيق. المعلومة المفتاحية: قمع الطفل ضيقه في الأسفل تحت المزمار وقمع البالغ ضيقه عند الحبال.', 'In a child under 8 the narrowest part of the airway is the cricoid ring (subglottic area), which is why even minor swelling there causes disproportionate obstruction. The glottic opening (vocal cords) is the narrowest point in the adult, not the child, the epiglottis is a cartilaginous flap above the glottis rather than a fixed point of narrowing, and the carina is the distal tracheal bifurcation. Key point: the paediatric airway narrows below the cords while the adult airway narrows at them.', 'أضيق جزء في المجرى الهوائي عند الأطفال دون سن الثامنة هو:', '{}'::jsonb, 'المجرى الهوائي عند الأطفال والانسداد', false, false, false),
  ((select id from s), 46, 'Stridor typically indicates:', '["Lower airway bronchospasm","Partial upper airway obstruction","Fluid in the alveoli","A pulmonary embolism"]'::jsonb, 1, 'الصرير صوت خشن عالي النبرة ينتج عن مرور هواء مضطرب في مجرى علوي متضيق جزئيًا، ويسمع غالبًا في الشهيق. التشنج القصبي السفلي يعطي أزيزًا زفيريًا، والسائل في الأسناخ يعطي خراخر، والانصمام الرئوي غالبًا لا يعطي صوتًا رئويًا شاذًا. المعلومة المفتاحية: صرير يعني فوق المزمار وما حوله، وأزيز يعني أسفل الشجرة القصبية.', 'Stridor is a harsh high-pitched sound generated by turbulent flow through a partially narrowed upper airway and is usually heard on inspiration. Lower airway bronchospasm produces expiratory wheeze instead, fluid in the alveoli produces crackles, and a pulmonary embolism usually produces no abnormal breath sound at all. Key point: stridor localises to the upper airway while wheeze localises to the lower bronchial tree.', 'الصرير يدل عادةً على:', '{}'::jsonb, 'المجرى الهوائي عند الأطفال والانسداد', false, false, false),
  ((select id from s), 47, 'The hallmark sign of croup is:', '["Drooling","A harsh, barking \"seal-like\" cough","High fever","Muffled voice"]'::jsonb, 1, 'الوذمة الفيروسية تحت المزمار تعطي سعالًا نباحيًا خشنًا مميزًا يشبه صوت الفقمة وغالبًا يشتد ليلًا. سيلان اللعاب والصوت المكتوم علامتان لالتهاب لسان المزمار حيث يعجز الطفل عن البلع، والحمى المرتفعة أيضًا أقرب إلى الالتهاب الجرثومي منها إلى الخانوق الذي يرافقه ارتفاع حراري خفيف. المعلومة المفتاحية: سعال نباحي يعني خانوقًا حتى يثبت غير ذلك.', 'Viral subglottic oedema in croup produces a harsh, barking seal-like cough that classically worsens at night, and this is the hallmark finding. Drooling and a muffled voice belong to epiglottitis where the child cannot swallow, and high fever also points to the bacterial process rather than to croup, which typically causes only a low-grade temperature. Key point: a barking cough means croup until proven otherwise.', 'العلامة المميزة للخانوق هي:', '{}'::jsonb, 'المجرى الهوائي عند الأطفال والانسداد', false, false, false),
  ((select id from s), 48, 'Epiglottitis is typically caused by:', '["A viral infection (RSV)","A bacterial infection (often Hib)","Allergies","Smoking"]'::jsonb, 1, 'التهاب لسان المزمار عدوى جرثومية عاصفة ترتبط تقليديًا بالمستدمية النزلية من النمط ب، وقد تراجعت كثيرًا بعد انتشار التلقيح. الفيروس المخلوي التنفسي يسبب التهاب القصيبات، والحساسية تسبب وذمة وعائية مختلفة السياق، والتدخين عامل خطر لأمراض مزمنة لا لهذا الالتهاب الحاد. المعلومة المفتاحية: جرثومي وسريع ومهدد للحياة، ولا تُهيّج الطفل بأي فحص فموي.', 'Epiglottitis is a fulminant bacterial infection (often Hib) that has become far less common since routine vaccination but remains immediately life-threatening. A viral infection (RSV) causes bronchiolitis, allergies cause angioedema in a different clinical context, and smoking is a risk factor for chronic disease rather than for this acute supraglottic infection. Key point: bacterial, rapid and life-threatening, and the child must never be agitated with oral examination.', 'التهاب لسان المزمار يسببه عادةً:', '{}'::jsonb, 'المجرى الهوائي عند الأطفال والانسداد', false, false, false),
  ((select id from s), 49, 'Which of the following is NOT one of the classic "4 D''s" of Epiglottitis?', '["Drooling","Dysphagia","Dysphonia","Dry cough"]'::jsonb, 3, 'الدال الأربعة الكلاسيكية هي سيلان اللعاب وعسر البلع وخلل الصوت والضائقة التنفسية، والسعال الجاف ليس منها بل إن غياب السعال النباحي أحد ما يميز هذا الالتهاب عن الخانوق. سيلان اللعاب وعسر البلع وخلل الصوت ثلاثتها من العلامات الأصيلة الناتجة عن تورم لسان المزمار. المعلومة المفتاحية: أربع دالات تصف طفلًا يسيل لعابه ولا يبلع ولا يتكلم بوضوح ويلهث.', 'The classic four D''s are drooling, dysphagia, dysphonia and distress, so dry cough is the one that does not belong, and in fact the absence of a barking cough is one of the features separating epiglottitis from croup. Drooling, dysphagia and dysphonia are all genuine consequences of a swollen epiglottis obstructing swallowing and phonation. Key point: the four D''s describe a child who drools, cannot swallow, cannot speak clearly and is in distress.', 'أي مما يلي ليس من الدال الأربعة الكلاسيكية لالتهاب لسان المزمار؟', '{}'::jsonb, 'المجرى الهوائي عند الأطفال والانسداد', false, false, false),
  ((select id from s), 50, 'What is the primary intervention for a conscious infant under 1 year with a severe FBAO?', '["Heimlich maneuver","Abdominal thrusts","5 back blows followed by 5 chest thrusts","Blind finger sweep"]'::jsonb, 2, 'عند الرضيع الواعي تُنفَّذ دورات من خمس ضربات ظهرية بين لوحي الكتف تليها خمس ضغطات صدرية حتى يخرج الجسم أو يفقد الرضيع وعيه. مناورة هايمليك والضغطات البطنية ممنوعتان دون السنة لخطر أذية الكبد والطحال والأحشاء، والكنس الأعمى بالإصبع قد يدفع الجسم إلى عمق أكبر. المعلومة المفتاحية: دون السنة لا ضغط على البطن، ظهر ثم صدر فقط.', 'For a conscious infant under 1 year with a severe FBAO the technique is cycles of 5 back blows followed by 5 chest thrusts, repeated until the object is expelled or the infant becomes unresponsive. The Heimlich maneuver and abdominal thrusts are contraindicated below one year because of the risk of liver, spleen and visceral injury, and a blind finger sweep may drive the object deeper. Key point: below one year there are no abdominal thrusts, only back blows and chest thrusts.', 'ما التدخل الأساسي لرضيع واعٍ دون عمر السنة مصاب بانسداد شديد في المجرى الهوائي بجسم أجنبي؟', '{}'::jsonb, 'المجرى الهوائي عند الأطفال والانسداد', false, false, false),
  ((select id from s), 51, 'What should a paramedic do if BLS maneuvers fail on an unconscious patient with a severe FBAO?', '["Perform a surgical cricothyrotomy immediately","Use direct laryngoscopy and Magill forceps to remove the object","Administer Albuterol","Administer Epinephrine"]'::jsonb, 1, 'بعد فشل الإسعاف الأساسي ينتقل المسعف إلى الرؤية المباشرة بالمنظار الحنجري وإزالة الجسم بملقط ماجيل، وهو الخطوة المتقدمة المنطقية التالية. بضع الغشاء الحلقي الدرقي الجراحي إجراء الملاذ الأخير ولا يُبدأ به قبل محاولة الإزالة المباشرة، والألبوتيرول لا يفيد في انسداد ميكانيكي، والإبينفرين علاج للتأق لا للجسم الأجنبي. المعلومة المفتاحية: انظر ثم أزل بالملقط قبل التفكير في المجرى الجراحي.', 'When BLS maneuvers fail in an unresponsive patient the next logical advanced step is to use direct laryngoscopy and Magill forceps to remove the object under direct vision. A surgical cricothyrotomy is the last resort and must not precede an attempt at direct removal, Albuterol does nothing for a mechanical obstruction, and Epinephrine treats anaphylaxis rather than a foreign body. Key point: look and remove with forceps before considering a surgical airway.', 'ماذا ينبغي أن يفعل المسعف إذا فشلت مناورات الإسعاف الأساسي لدى مريض فاقد للوعي مصاب بانسداد شديد في المجرى الهوائي بجسم أجنبي؟', '{}'::jsonb, 'المجرى الهوائي عند الأطفال والانسداد', false, false, false),
  ((select id from s), 52, 'Which of the following best describes the underlying mechanism of pulmonary edema?', '["It occurs when the lymphatic drainage system completely ceases to function.","It occurs when the rate of fluid transudation from pulmonary capillaries exceeds the rate of lymphatic drainage.","It occurs when oxygen rapidly diffuses into the blood, displacing fluid.","It occurs when capillary oncotic pressure rapidly increases."]'::jsonb, 1, 'الوذمة الرئوية اختلال في التوازن: يتسرب السائل من الشعيرات بمعدل يفوق قدرة الأوعية اللمفية على سحبه فيتراكم في النسيج الخلالي ثم في الأسناخ. التوقف التام للتصريف اللمفي ليس شرطًا للحدوث فالنظام يعمل لكنه يُغرق، وانتشار الأكسجين لا يزيح السائل، وارتفاع الضغط الجرمي الشعري يسحب السائل إلى داخل الوعاء فيقاوم الوذمة لا يسببها. المعلومة المفتاحية: ارتشاح يفوق التصريف هو جوهر الوذمة.', 'Pulmonary edema is a balance failure that occurs when the rate of fluid transudation from pulmonary capillaries exceeds the rate of lymphatic drainage, so fluid accumulates first in the interstitium and then floods the alveoli. Complete cessation of lymphatic drainage is not required because the system keeps working but is simply overwhelmed, oxygen diffusing into blood does not displace fluid, and rising capillary oncotic pressure actually pulls fluid back into the vessel and opposes oedema. Key point: transudation outpacing drainage is the essence of pulmonary oedema.', 'أي مما يلي يصف الآلية الكامنة للوذمة الرئوية على أفضل نحو؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 53, 'Which of the following is considered a non-cardiogenic cause of pulmonary edema?', '["Left-Sided Congestive Heart Failure (CHF)","Valvular disease","Myocardial Infarction (AMI)","Toxic inhalation (e.g., chlorine gas)"]'::jsonb, 3, 'استنشاق المواد السامة كغاز الكلور يؤذي الغشاء السنخي الشعري مباشرة فيزيد نفوذيته ويسرّب السائل دون أي خلل في مضخة القلب، وهذا هو النمط غير القلبي. قصور القلب الأيسر ومرض الصمامات واحتشاء العضلة ثلاثتها ترفع الضغط في الأذين الأيسر والشعيرات الرئوية فتسبب وذمة قلبية المنشأ. المعلومة المفتاحية: غير قلبي يعني أذية غشاء ونفوذية، وقلبي يعني ضغطًا هيدروستاتيًا مرتفعًا.', 'Toxic inhalation (e.g., chlorine gas) injures the alveolar capillary membrane directly, increasing its permeability so fluid leaks with no pump failure at all, which defines the non-cardiogenic pattern. Left-Sided Congestive Heart Failure (CHF), valvular disease and Myocardial Infarction (AMI) all raise left atrial and pulmonary capillary pressures and therefore cause cardiogenic oedema. Key point: non-cardiogenic means membrane injury and permeability while cardiogenic means raised hydrostatic pressure.', 'أي مما يلي يُعد سببًا غير قلبي للوذمة الرئوية؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 54, 'How does the End-Tidal CO2 (EtCO2) value typically change as a patient with pulmonary edema begins to experience respiratory fatigue?', '["It remains steadily below 35 mmHg.","It stays at a constant baseline.","It drops significantly due to hyperventilation.","It climbs, indicating impending respiratory arrest."]'::jsonb, 3, 'في البداية يفرط المريض في التهوية فتنخفض القراءة، لكن مع إنهاك عضلات التنفس تتراجع التهوية السنخية فيتراكم ثاني أكسيد الكربون وترتفع القيمة منذرة بتوقف تنفسي وشيك. بقاء القيمة دون خمسة وثلاثين أو ثباتها على خط الأساس يصف مرحلة التعويض لا مرحلة التعب، والانخفاض الكبير بفرط التهوية يصف الطور المبكر لا طور الإنهاك. المعلومة المفتاحية: صعود منحنى الكربون الزفيري عند مريض متعب إنذار بالتنبيب.', 'As the patient tires, alveolar ventilation falls, carbon dioxide accumulates, and the EtCO2 climbs, indicating impending respiratory arrest and the need to prepare for ventilatory support. Remaining steadily below 35 mmHg or staying at a constant baseline describes the compensating phase rather than fatigue, and a significant drop due to hyperventilation describes the early presentation before exhaustion sets in. Key point: a rising EtCO2 in a tiring patient is a warning of imminent respiratory arrest.', 'كيف تتغير عادةً قيمة ثاني أكسيد الكربون في نهاية الزفير عندما يبدأ مريض الوذمة الرئوية بالتعب التنفسي؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 55, 'Why is Continuous Positive Airway Pressure (CPAP) considered the gold standard prehospital intervention for pulmonary edema?', '["It acts as a loop diuretic to remove fluid from the body.","It forces fluid out of the alveoli, stents open collapsed alveoli, and increases intrathoracic pressure to decrease preload.","It provides a potent venodilatory effect to pool blood in the periphery.","It reduces afterload by dilating systemic arteries."]'::jsonb, 1, 'الضغط الإيجابي المستمر يعمل بثلاث آليات معًا: يدفع السائل من السنخ إلى النسيج الخلالي، ويبقي الأسناخ المنهارة مفتوحة فيحسن الأكسجة، ويرفع الضغط داخل الصدر فيقلل العود الوريدي والحمل القبلي. هو ليس مدرًّا عرويًا فذاك دور الفوروسيميد، وليس موسعًا وريديًا فذاك دور النتروغليسرين، ولا يوسّع الشرايين الجهازية لتخفيض الحمل البعدي. المعلومة المفتاحية: فائدته ميكانيكية مزدوجة في الرئة والدورة معًا.', 'CPAP works by three mechanisms at once, since it forces fluid out of the alveoli, stents open collapsed alveoli, and increases intrathoracic pressure to decrease preload, improving both oxygenation and cardiac loading. It is not a loop diuretic, which describes Furosemide, it is not a potent venodilator pooling blood peripherally, which describes Nitroglycerin, and it does not reduce afterload by dilating systemic arteries. Key point: the benefit of CPAP is mechanical and acts on the lung and the circulation simultaneously.', 'لماذا يُعد الضغط الإيجابي المستمر في المجرى الهوائي المعيار الذهبي للتدخل قبل المستشفى في الوذمة الرئوية؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 56, 'What is the primary pharmacological action of Nitroglycerin (NTG) when treating cardiogenic pulmonary edema?', '["It promotes the renal excretion of water and sodium.","It acts as a potent venodilator, expanding veins to pool blood in the periphery and reduce the volume returning to the heart.","It acts as a bronchodilator to treat Cardiac Asthma.","It forces fluid out of the interstitial space back into the capillaries."]'::jsonb, 1, 'النتروغليسرين موسّع وريدي بالدرجة الأولى، يجمع الدم في السرير الوريدي المحيطي فيقلل العود الوريدي والحمل القبلي، وبذلك يخف الاحتقان الرئوي سريعًا. تعزيز الإطراح الكلوي وصف للمدرّات، وتوسيع القصبات وصف لموسعات بيتا-2، ودفع السائل من الخلالي إلى الشعيرات ليس آلية دوائية للنترات. المعلومة المفتاحية: النترات تخفض الحمل القبلي أولًا وتوسّع الشرايين عند الجرعات الأعلى.', 'Nitroglycerin acts primarily as a potent venodilator, expanding veins to pool blood in the periphery and reduce the volume returning to the heart, which lowers preload and rapidly relieves pulmonary congestion. Promoting renal excretion of water and sodium describes diuretics, acting as a bronchodilator describes beta-2 agonists, and forcing interstitial fluid back into the capillaries is not a pharmacological action of nitrates. Key point: nitrates drop preload first and dilate arteries only at higher doses.', 'ما التأثير الدوائي الأساسي للنتروغليسرين في علاج الوذمة الرئوية القلبية المنشأ؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 57, 'Where do more than 90% of pulmonary emboli originate?', '["From bone marrow fat after a major fracture.","Deep Vein Thromboses (DVTs) in the lower extremities or pelvis.","From the right atrium due to Atrial Fibrillation.","From air introduced via central lines."]'::jsonb, 1, 'أكثر من تسعين بالمئة من الصمّات الرئوية مصدرها خثرات في الأوردة العميقة للطرفين السفليين أو الحوض تنفصل وتنتقل عبر الدوران الوريدي إلى الشريان الرئوي. الانصمام الشحمي بعد الكسور والانصمام الهوائي عبر الخطوط المركزية أسباب نادرة، وخثرات الأذين الأيمن في الرجفان الأذيني ممكنة لكنها لا تشكل النسبة الغالبة. المعلومة المفتاحية: ابحث عن الساق المتورمة المؤلمة عند كل شك بانصمام رئوي.', 'More than 90% of pulmonary emboli arise from Deep Vein Thromboses (DVTs) in the lower extremities or pelvis, which break loose and travel through the venous circulation and right heart into the pulmonary arteries. Bone marrow fat after a major fracture and air introduced via central lines are genuine but rare causes, and right atrial thrombus from Atrial Fibrillation is possible but accounts for a small minority. Key point: look for a swollen painful leg whenever pulmonary embolism is suspected.', 'من أين ينشأ أكثر من تسعين بالمئة من الصمّات الرئوية؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 58, 'Which of the following best describes the V/Q mismatch created by a pulmonary embolism?', '["It creates \"Dead Space\" where air is present, but no gas exchange occurs because there is no blood flow.","It creates \"Shunting\" where blood flow is normal, but the alveoli are filled with fluid.","It causes both ventilation and perfusion to drop to zero simultaneously.","It causes a hyper-perfusion state that overwhelms alveolar ventilation."]'::jsonb, 0, 'الصمّة تسد الشريان فتصل الأسناخ تهوية كاملة بلا تروية، وهذا هو تعريف الفراغ الميت، ومنه ينشأ انخفاض ثاني أكسيد الكربون الزفيري رغم بقاء الرئتين نقيتين. التحويلة عكس ذلك تمامًا وتصف الوذمة وذات الرئة حيث التروية موجودة والأسناخ ممتلئة، وهبوط الاثنين إلى الصفر معًا لا يحدث هنا، وفرط التروية غير وارد مع انسداد وعائي. المعلومة المفتاحية: فراغ ميت يعني هواءً بلا دم، وتحويلة تعني دمًا بلا هواء.', 'The embolus blocks arterial flow so alveoli are still fully ventilated but no longer perfused, creating dead space where air is present, but no gas exchange occurs because there is no blood flow, and this is why EtCO2 falls while the lungs stay clear. Shunting is the exact opposite and describes oedema or pneumonia where perfusion continues past fluid-filled alveoli, ventilation and perfusion do not both drop to zero here, and a hyper-perfusion state is impossible with vascular occlusion. Key point: dead space means air without blood while shunt means blood without air.', 'أي مما يلي يصف على أفضل نحو خلل نسبة التهوية إلى التروية الذي يحدثه الانصمام الرئوي؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 59, 'Why must paramedics exercise extreme caution when considering CPAP or PEEP for a patient with a suspected pulmonary embolism?', '["It increases intrathoracic pressure, which decreases venous return, worsening obstructive shock.","It causes systemic vasodilation, dropping the blood pressure further.","It pushes the embolus deeper into the pulmonary capillary bed.","It increases left ventricular afterload, causing immediate pulmonary edema."]'::jsonb, 0, 'مريض الانصمام يعاني أصلًا من انسداد أمام البطين الأيمن، ورفع الضغط داخل الصدر يقلل العود الوريدي ويحرم البطين الأيمن المتعثر من حمله القبلي فيتفاقم الانهيار الدوراني. الضغط الإيجابي لا يسبب توسعًا وعائيًا جهازيًا، ولا يدفع الصمّة ميكانيكيًا داخل السرير الشعري، وتأثيره على الحمل البعدي للبطين الأيسر مخفّض لا مرتفع. المعلومة المفتاحية: في الصدمة الانسدادية الضغط الإيجابي سيف ذو حدين فاستخدمه بحذر شديد.', 'The embolism patient already has an obstruction in front of a struggling right ventricle, and positive pressure increases intrathoracic pressure, which decreases venous return, worsening obstructive shock by removing the preload that ventricle depends on. CPAP does not cause systemic vasodilation, it cannot mechanically push the embolus deeper into the pulmonary capillary bed, and its effect on left ventricular afterload is to reduce it rather than to increase it. Key point: in obstructive shock positive pressure is double-edged and must be used with extreme caution.', 'لماذا يجب على المسعفين توخي الحذر الشديد عند التفكير في الضغط الإيجابي المستمر أو الضغط الزفيري النهائي الإيجابي لمريض يُشتبه بانصمام رئوي؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 60, 'What is an appropriate initial prehospital fluid management strategy for a hypotensive patient with a massive pulmonary embolism?', '["Withhold all fluids to prevent right ventricular failure.","Administer a rapid 2-liter fluid bolus to overcome the obstruction.","Administer a careful fluid bolus (e.g., 250-500 mL Normal Saline) to increase right ventricular preload.","Administer Furosemide to decrease hydrostatic pressure."]'::jsonb, 2, 'الجرعة المحسوبة من مئتين وخمسين إلى خمسمئة مليلتر تدعم الحمل القبلي للبطين الأيمن المتعثر دون إغراقه، ثم يُعاد التقييم بعد كل جرعة. منع السوائل كليًا يحرم البطين الأيمن من دعم ضروري، ولتران دفعة واحدة يوسّعان البطين الأيمن ويدفعان الحاجز نحو الأيسر فيفاقمان الانهيار، والفوروسيميد يقلل الحجم ويسوء التروية. المعلومة المفتاحية: رشفة محسوبة من السائل مع إعادة تقييم متكررة لا إغراق ولا حرمان.', 'The correct approach is to administer a careful fluid bolus (e.g., 250-500 mL Normal Saline) to increase right ventricular preload, supporting the failing right ventricle without overdistending it, then reassess after each bolus. Withholding all fluids deprives that ventricle of needed support, a rapid 2-liter bolus overdistends the right ventricle and bows the septum into the left ventricle, worsening collapse, and Furosemide reduces volume and further impairs perfusion. Key point: give a measured sip of fluid with frequent reassessment, neither flooding nor starving the patient.', 'ما الاستراتيجية المناسبة لتدبير السوائل مبدئيًا قبل المستشفى لمريض مصاب بانصمام رئوي ضخم مع هبوط في الضغط؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 61, 'A patient presents with sudden onset dyspnea, clear lungs, and an EtCO2 of 18 mmHg. Which of the following should be highly suspected?', '["Asthma","Cardiogenic Pulmonary Edema","Pulmonary Embolism","Pneumonia"]'::jsonb, 2, 'اجتماع الضيق المفاجئ مع رئتين نقيتين وقيمة منخفضة جدًا لثاني أكسيد الكربون الزفيري هو التوقيع الكلاسيكي للانصمام الرئوي بسبب زيادة الفراغ الميت. الربو يعطي أزيزًا زفيريًا واضحًا، والوذمة القلبية تعطي خراخر رطبة منتشرة، وذات الرئة تعطي خراخر موضعية وحمى وبدءًا تدريجيًا. المعلومة المفتاحية: رئتان نقيتان مع رقم منخفض على مقياس الكربون الزفيري تعني انصمامًا حتى يثبت العكس.', 'Sudden dyspnoea with clear lungs and an EtCO2 of 18 mmHg is the classic signature of pulmonary embolism, because increased dead space dilutes exhaled carbon dioxide while the lung parenchyma itself remains normal. Asthma would produce obvious expiratory wheeze, cardiogenic pulmonary edema would produce diffuse wet crackles, and pneumonia would produce focal crackles with fever and a gradual onset. Key point: clear lungs with a low EtCO2 and sudden dyspnoea mean pulmonary embolism until proven otherwise.', 'يحضر مريض بضيق نفس مفاجئ ورئتين نقيتين وقيمة ثاني أكسيد كربون في نهاية الزفير تبلغ 18 مليمترًا زئبقيًا. أي مما يلي ينبغي الاشتباه به بقوة؟', '{}'::jsonb, 'الوذمة الرئوية والانصمام الرئوي', false, false, false),
  ((select id from s), 62, 'What is Cor Pulmonale?', '["Left-sided heart failure from a myocardial infarction","Right-sided heart failure resulting strictly from pulmonary disease","Pericardial tamponade","Pulmonary edema from hypertension"]'::jsonb, 1, 'القلب الرئوي هو فشل البطين الأيمن الناتج حصرًا عن مرض في الرئة يرفع مقاومة الأوعية الرئوية، فيتضخم البطين الأيمن ثم يعجز. فشل الجانب الأيسر بعد احتشاء عضلة القلب سببه قلبي لا رئوي، والاندحاس التاموري سائل يضغط القلب من خارجه، والوذمة الرئوية من ارتفاع الضغط مشكلة الجانب الأيسر. المعلومة المفتاحية: القلب الرئوي = فشل أيمن سببه الرئة وحدها.', 'Cor pulmonale is right ventricular failure caused strictly by lung disease: chronic hypoxia raises pulmonary vascular resistance, and the right ventricle hypertrophies against that load until it fails. Left-sided failure after a myocardial infarction is cardiac in origin, pericardial tamponade is fluid compressing the heart from the outside, and pulmonary oedema from hypertension is a left-sided problem. Key point: cor pulmonale = right-sided failure whose cause lies in the lungs alone.', 'ما هو القلب الرئوي؟', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, true),
  ((select id from s), 63, 'The concept of "Hypoxic Drive" suggests that chronic COPD patients breathe in response to:', '["High CO2 levels","Low O2 levels","High pH levels","Low CO2 levels"]'::jsonb, 1, 'يفترض هذا المفهوم أن مركز التنفس عند مريض الانسداد المزمن اعتاد ارتفاع ثاني أكسيد الكربون فقلّت حساسيته له، فصار الدافع الباقي للتنفس هو انخفاض الأكسجين. ارتفاع ثاني أكسيد الكربون هو دافع الشخص السليم لا هذا المريض، وارتفاع درجة الحموضة يثبّط التنفس، وانخفاض ثاني أكسيد الكربون يزيل الدافع لا يصنعه. المعلومة المفتاحية: الدافع الناقص الأكسجين = التنفس استجابةً لنقص الأكسجين — ومع ذلك لا يُمنع الأكسجين عن مريض ناقص التأكسج أبدًا.', 'The hypoxic drive theory holds that in chronic COPD the respiratory centre becomes desensitised to a persistently high CO2, leaving a low O2 level as the remaining stimulus to breathe. A high CO2 is the normal person''s main drive rather than this patient''s, a high pH depresses ventilation, and a low CO2 removes drive instead of creating it. Key point: hypoxic drive = breathing triggered by low oxygen — but never withhold oxygen from a hypoxic patient because of it.', 'مفهوم «الدافع الناقص الأكسجين» يشير إلى أن مرضى الانسداد الرئوي المزمن يتنفسون استجابةً لـ:', '{}'::jsonb, 'الانسداد الرئوي المزمن', false, false, true),
  ((select id from s), 64, 'Are bronchodilators routinely indicated for all pneumonia patients?', '["No, they are absolutely contraindicated","Yes, they push fluid out of the alveoli","Only if there is concurrent wheezing/bronchospasm","Yes, they cure the infection"]'::jsonb, 2, 'موسّعات القصبات ترخي العضلة الملساء للمجرى، ومشكلة ذات الرئة سائل وقيح داخل الأسناخ لا تشنّج قصبي، فلا فائدة منها إلا إذا صاحبها أزيز أو تشنّج فتُعطى لهذا السبب وحده. القول إنها مضادّة الاستطباب مطلقًا مبالغة، وهي لا تدفع السائل خارج الأسناخ فهذا عمل الضغط الإيجابي المستمر، ولا تعالج العدوى فهذا عمل المضاد الحيوي. المعلومة المفتاحية: في ذات الرئة يُعطى موسّع القصبات حسب العَرَض — إن وُجد أزيز فقط.', 'Bronchodilators relax airway smooth muscle, but the problem in pneumonia is fluid and pus filling the alveoli rather than bronchospasm, so they help only when wheezing or bronchospasm happens to coexist. Calling them absolutely contraindicated overstates it, they do not push fluid out of the alveoli — that is what CPAP does — and they do not treat the infection, which is the antibiotic''s job. Key point: in pneumonia a bronchodilator is symptom-driven — give it only if there is a wheeze.', 'هل موسّعات القصبات مُستطبّة روتينيًا لكل مرضى ذات الرئة؟', '{}'::jsonb, 'الالتهابات الرئوية والقصيبات', false, false, true);
  insert into amusq.subjects (name, color, icon, descr, topics, exam_date, published, free, ord)
insert into amusq.questions
  (subject_id, ord, q, options, answer, expl_ar, expl_en, translation, mnemonic, topic, derived, opts_built, important)
values
  ((select id from s), 1, 'Situation awareness is best defined as the ability to:', '["Perceive, understand, and predict what is happening","Perform clinical procedures","Memorize treatment protocols","Complete patient documentation"]'::jsonb, 0, 'التعريف المعتمد للوعي الظرفي يجمع ثلاثة مستويات متتابعة هي الإدراك ثم الفهم ثم التوقّع، ولهذا فالخيار الأول هو الوحيد الذي يستوعب التعريف كاملًا. أما تنفيذ الإجراءات السريرية فهو مهارة تقنية يدوية لا ذهنية، وحفظ بروتوكولات العلاج مجرد استرجاع للمعلومة بلا تحليل للموقف، وإكمال التوثيق مهمة إدارية تأتي لاحقًا ولا تصف عملية ذهنية جارية. المعلومة المفتاحية: الوعي الظرفي مهارة ذهنية غير تقنية بثلاثة مستويات، لا مهارة يدوية ولا حفظ.', 'Situation awareness is the ability to perceive the elements of the scene, understand what they mean, and project what will happen next — the three levels described by Endsley. Performing clinical procedures and completing documentation are technical or administrative tasks, not awareness; memorising protocols is recall, which does not adapt to a changing scene. Key point: situation awareness = perceive, understand, predict.', 'يُعرَّف الوعي الظرفي على أفضل وجه بأنه القدرة على:', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 2, 'Which of the following is considered a non-technical skill?', '["Situation awareness","Intravenous cannulation","Endotracheal intubation","CPR"]'::jsonb, 0, 'المهارات غير التقنية هي القدرات المعرفية والاجتماعية التي تدعم الأداء دون أن تكون إجراءً يدويًا، والوعي الظرفي مثالها الأول. أما تركيب القنية الوريدية والتنبيب الرغامي والإنعاش القلبي الرئوي فكلها إجراءات يدوية تُتقن بالتدريب العملي وتُقاس بدقة التنفيذ، فهي مهارات تقنية بامتياز. المعلومة المفتاحية: كل ما يُنفَّذ باليد على المريض مهارة تقنية، وما يجري في الذهن وبين أفراد الفريق مهارة غير تقنية.', 'Situation awareness is a cognitive, non-technical skill: it is the mental work of building and updating a picture of the patient and the scene, and it underpins every decision made. Intravenous cannulation, endotracheal intubation and CPR are all psychomotor procedures performed with the hands and measured by accuracy of execution, so all three are technical skills. Key point: what happens in the head and between team members is non-technical; what happens to the patient through the hands is technical.', 'أي مما يلي يُعدّ مهارة غير تقنية؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 3, 'Which is the FIRST level of situation awareness?', '["Projection","Comprehension","Evaluation","Perception"]'::jsonb, 3, 'المستوى الأول هو الإدراك، أي التقاط المعطيات الخام من البيئة ومن المريض قبل أي تحليل. والفهم هو المستوى الثاني إذ يفسّر ما أُدرك، والتوقّع هو المستوى الثالث إذ يستشرف ما سيحدث، أما التقييم فليس أصلًا أحد المستويات الثلاثة المعتمدة. المعلومة المفتاحية: الترتيب ثابت لا يُعكس، إدراك ثم فهم ثم توقّع، ولا يمكن فهم ما لم يُدرَك.', 'Perception is Level 1 — simply gathering the raw data from the patient, the monitors, the bystanders and the environment before any interpretation. Comprehension is Level 2 because it explains what those data mean, projection is Level 3 because it forecasts what will happen next, and evaluation is not one of the three recognised levels at all. Key point: the order never reverses — perception, then comprehension, then projection.', 'ما هو المستوى الأول من الوعي الظرفي؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 4, 'During Level 1 (Perception), the paramedic should primarily:', '["Predict future events","Collect information from the environment","Choose the treatment plan","Evaluate patient outcomes"]'::jsonb, 1, 'مهمة المستوى الأول هي جمع المعطيات من المشهد والمريض والأجهزة والشهود، فهذه هي المادة الخام لكل ما يليها. أما توقّع الأحداث المستقبلية فهو وظيفة المستوى الثالث، واختيار خطة العلاج قرار يأتي بعد اكتمال المستويات الثلاثة، وتقييم النتائج يحدث في مرحلة لاحقة بعد تنفيذ التدخل. المعلومة المفتاحية: الإدراك جمعٌ للمعلومات لا تفسير لها ولا قرار مبني عليها.', 'Level 1 is perception, whose only job is to collect information from the environment, the patient and the monitoring equipment as raw material for everything that follows. Predicting future events belongs to Level 3 projection, choosing the treatment plan is a decision taken after all three levels are complete, and evaluating patient outcomes happens later, after the intervention has been delivered. Key point: perception gathers data — it does not yet interpret them or act on them.', 'خلال المستوى الأول (الإدراك)، ينبغي على المسعف بشكل أساسي أن:', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 5, 'Understanding the meaning of collected information represents which level of situation awareness?', '["Comprehension","Projection","Perception","Reflection"]'::jsonb, 0, 'نصّ السؤال يصف تفسير المعنى، وهذا بالضبط تعريف المستوى الثاني وهو الفهم. أما التوقّع فيتجاوز المعنى الحالي إلى ما سيحدث لاحقًا، والإدراك يسبق المعنى إذ يقتصر على جمع المعطيات، والتأمل ليس من مستويات الوعي الظرفي أصلًا. المعلومة المفتاحية: كلمة معنى في نص السؤال هي المفتاح الدال على المستوى الثاني، الفهم.', 'Understanding what the collected data actually mean is the definition of Level 2, comprehension — the stage where separate findings are integrated into a clinical picture. Projection goes beyond present meaning to forecast future events, perception precedes meaning because it only captures the raw findings, and reflection is not one of the levels of situation awareness. Key point: the word meaning in the stem is the marker for Level 2, comprehension.', 'فهم معنى المعلومات التي تم جمعها يمثّل أي مستوى من مستويات الوعي الظرفي؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 6, 'Predicting that an asthma patient may develop respiratory arrest is an example of:', '["Perception","Documentation","Communication","Projection"]'::jsonb, 3, 'الحديث هنا عن حدث لم يقع بعد وإنما يُستشرف حدوثه، وهذا هو المستوى الثالث أي التوقّع. أما الإدراك فيقتصر على ملاحظة الأزيز وتسرّع التنفس الآنَين، والتوثيق تسجيل إداري للمعطيات، والتواصل نقل المعلومة للآخرين لا استشراف مآلها. المعلومة المفتاحية: كل عبارة تتحدث عمّا قد يحدث لاحقًا تشير إلى المستوى الثالث، التوقّع.', 'Predicting that an asthma patient may deteriorate into respiratory arrest concerns an event that has not yet happened, which is exactly Level 3, projection. Perception would only be noticing the wheeze and tachypnoea as they are now, documentation is an administrative record of findings, and communication passes information to others rather than forecasting where the patient is heading. Key point: any statement about what may happen next signals Level 3, projection.', 'توقّع أن مريض الربو قد يتعرّض لتوقّف تنفسي هو مثال على:', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 7, 'Situation awareness is most closely related to:', '["Medication administration","Decision making","Physical fitness","Documentation"]'::jsonb, 1, 'الوعي الظرفي هو المدخل الذي يغذّي القرار السريري، فبقدر دقة الصورة الذهنية تكون سلامة القرار، ولذلك الارتباط الأوثق هو بصنع القرار. أما إعطاء الأدوية فمهارة تنفيذية تأتي بعد القرار، واللياقة البدنية لا صلة مفهومية لها بالمعالجة الذهنية للمعلومات، والتوثيق نشاط تسجيلي لاحق. المعلومة المفتاحية: الوعي الظرفي مقدّمة والقرار السريري نتيجة، وفقدان الأول يفسد الثاني حتمًا.', 'Situation awareness feeds directly into decision making: the accuracy of the mental picture determines the quality of the clinical decision that follows. Medication administration is an execution skill that comes after the decision, physical fitness has no conceptual link to processing information, and documentation is a recording activity performed afterwards. Key point: situation awareness is the input and the clinical decision is the output — degrade the first and the second fails.', 'الوعي الظرفي هو الأوثق ارتباطًا بـ:', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 8, 'Which factor commonly reduces situation awareness?', '["Fatigue","Team communication","Adequate rest","Clinical experience"]'::jsonb, 0, 'الإرهاق يستنزف الانتباه والذاكرة العاملة فيضيّق مجال الملاحظة ويبطئ التفسير، وهو من أشهر مسببات تدهور الوعي الظرفي. أما التواصل بين أفراد الفريق فيرفع الوعي المشترك، والراحة الكافية تجدّد القدرة على الانتباه، والخبرة السريرية تسرّع التعرف على الأنماط، فالثلاثة عوامل داعمة لا مُضعفة. المعلومة المفتاحية: الإرهاق والضغط النفسي وضيق الوقت تُضعف الوعي الظرفي، بينما التواصل والراحة والخبرة تعزّزه.', 'Fatigue depletes attention and working memory, narrowing what the paramedic notices and slowing interpretation, so it is one of the commonest causes of degraded situation awareness. Team communication raises shared awareness, adequate rest restores attentional capacity, and clinical experience speeds up pattern recognition, so all three support awareness rather than reduce it. Key point: fatigue, stress and time pressure erode situation awareness; rest, experience and communication protect it.', 'أي عامل يقلّل الوعي الظرفي بشكل شائع؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 9, 'Which of the following is an example of good situation awareness during a road traffic accident?', '["Ignoring traffic hazards","Focusing only on the patient''s injury","Assessing both patient condition and scene safety","Beginning treatment without scene assessment"]'::jsonb, 2, 'الوعي الظرفي الجيد يعني إحاطة بالصورة كاملة، أي المريض والمشهد معًا، فكان الجواب الصحيح تقييم الحالة والسلامة في آن واحد. أما تجاهل مخاطر المرور فتفريط في السلامة، والتركيز على الإصابة وحدها هو تعريف رؤية النفق، وبدء العلاج دون تقييم الموقع يعرّض الفريق والمريض معًا للخطر. المعلومة المفتاحية: الوعي الظرفي الجيد يوسّع دائرة الانتباه ليشمل المريض والبيئة، لا يضيّقها على أحدهما.', 'Good situation awareness means holding the whole picture, so assessing both patient condition and scene safety together is the only answer that keeps the full field of attention open. Ignoring traffic hazards abandons safety, focusing only on the patient''s injury is the definition of tunnel vision, and beginning treatment without scene assessment puts both crew and patient at risk. Key point: good situation awareness widens attention to include patient and environment, it never narrows it to one of them.', 'أي مما يلي مثال على وعي ظرفي جيد أثناء حادث سير؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 10, 'The role of memory in situation awareness is to:', '["Replace patient assessment","Help recognize familiar clinical patterns","Reduce communication","Eliminate decision making"]'::jsonb, 1, 'الذاكرة تخزّن صورًا سريرية سابقة تُقارن بها المعطيات الحالية، فتسرّع التعرف على النمط وتدعم مستوى الفهم. أما القول إنها تحل محل تقييم المريض فخطأ خطير لأن الذاكرة تكمّل التقييم ولا تلغيه، وهي لا تقلّل التواصل ولا تلغي صنع القرار بل تغذّيهما بمرجعية سابقة. المعلومة المفتاحية: الذاكرة أداة مساعِدة للتعرف على الأنماط، ولا تُغني أبدًا عن التقييم الفعلي للمريض.', 'Memory stores previous clinical pictures against which current findings can be matched, so it helps recognise familiar clinical patterns and supports the comprehension level of awareness. Saying it replaces patient assessment is dangerous because stored experience supplements assessment but never substitutes for it, and memory neither reduces communication nor eliminates decision making — it supplies the reference material that informs both. Key point: memory assists pattern recognition; it never removes the need to actually assess the patient.', 'دور الذاكرة في الوعي الظرفي هو:', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 11, 'Which action helps maintain situation awareness?', '["Ignoring team feedback","Continuous reassessment","Focusing on one task only","Avoiding communication"]'::jsonb, 1, 'الوعي الظرفي صورة ذهنية متغيّرة بتغيّر حالة المريض، ولا تبقى محدَّثة إلا بإعادة التقييم المستمرة. أما تجاهل ملاحظات الفريق فيحرم المسعف من معلومات لم يرها بنفسه، والتركيز على مهمة واحدة فقط طريق مباشر إلى رؤية النفق، وتجنّب التواصل يقطع تدفق المعلومات ويهدم الوعي المشترك. المعلومة المفتاحية: إعادة التقييم المستمرة هي المحرّك الذي يبقي الصورة الذهنية مطابقة للواقع.', 'Situation awareness is a picture that decays as the patient changes, so only continuous reassessment keeps it matched to reality. Ignoring team feedback discards information the paramedic did not see personally, focusing on one task only leads straight to tunnel vision, and avoiding communication cuts off the information flow that builds shared awareness. Key point: continuous reassessment is the engine that keeps the mental picture aligned with the real situation.', 'أي إجراء يساعد على الحفاظ على الوعي الظرفي؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 12, 'Which of the following is a sign of reduced situation awareness?', '["Tunnel vision","Effective teamwork","Frequent reassessment","Shared communication"]'::jsonb, 0, 'رؤية النفق تضييق للانتباه على تفصيل واحد مع غياب بقية المشهد، وهي العلامة الأبرز على انخفاض الوعي الظرفي. أما العمل الجماعي الفعّال وإعادة التقييم المتكررة والتواصل المشترك فثلاثتها مؤشرات على وعي ظرفي سليم ومحدَّث لا على تدهوره. المعلومة المفتاحية: رؤية النفق ليست تركيزًا جيدًا بل عرَض إنذاري على ضياع الصورة الكاملة.', 'Tunnel vision — attention narrowed onto one detail while the rest of the scene disappears — is the classic warning sign that situation awareness has been lost. Effective teamwork, frequent reassessment and shared communication are all markers of healthy, updated awareness rather than indicators of its decline. Key point: tunnel vision is not good concentration, it is the red flag of lost situation awareness.', 'أي مما يلي علامة على انخفاض الوعي الظرفي؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 13, 'A paramedic notices heavy bleeding but fails to recognize an obstructed airway because attention is focused only on the bleeding. This is an example of:', '["Pattern recognition","Closed-loop communication","Effective projection","Tunnel vision leading to reduced situation awareness"]'::jsonb, 3, 'انحصار الانتباه في النزيف وحده حتى فات انسداد المجرى الهوائي هو التطبيق الحرفي لرؤية النفق وما تسببه من انخفاض الوعي الظرفي. أما التعرف على النمط فيعني مطابقة صورة سريرية كاملة لا إغفال جزء منها، والتواصل المغلق الحلقة أسلوب لتأكيد الأوامر لا صلة له بالمشهد، والتوقّع الفعّال كان سيقود إلى ملاحظة الخطر لا إلى تفويته. المعلومة المفتاحية: إغفال تهديد حياة بسبب الانشغال بمشكلة أخرى ظاهرة هو التعريف العملي لرؤية النفق.', 'Attention locked onto the heavy bleeding while an obstructed airway goes unnoticed is a textbook example of tunnel vision leading to reduced situation awareness. Pattern recognition means matching a complete clinical picture rather than missing part of it, closed-loop communication is a method for confirming orders and is irrelevant to this scene, and effective projection would have anticipated the airway threat instead of missing it. Key point: missing a life threat because of preoccupation with another visible problem is the working definition of tunnel vision.', 'يلاحظ مسعف نزيفًا غزيرًا لكنه يفشل في التعرف على انسداد في المجرى الهوائي لأن انتباهه منصبّ على النزيف وحده. هذا مثال على:', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 14, 'A paramedic observes smoke coming from a crashed vehicle, realizes it indicates a fire risk, and immediately requests firefighters while moving the patient to a safe area. Which statement best describes this scenario?', '["Only Level 1 (Perception) was used.","Only Level 2 (Comprehension) was used.","Only Level 3 (Projection) was used.","All three levels of situation awareness were applied."]'::jsonb, 3, 'المشهد يجمع المستويات الثلاثة متسلسلة: رؤية الدخان إدراك، وإدراك دلالته على خطر حريق فهم، واستشراف اشتعال المركبة والتحرك الوقائي توقّع. ولذلك فكل خيار يحصر الموقف في مستوى واحد فقط، سواء الإدراك أو الفهم أو التوقّع، يهمل الخطوتين الأخريين الظاهرتين صراحة في النص. المعلومة المفتاحية: حين يتضمن السيناريو ملاحظة ثم تفسيرًا ثم تصرفًا استباقيًا، فالإجابة هي تطبيق المستويات الثلاثة معًا.', 'The scenario runs through all three levels in sequence: seeing the smoke is perception, realising it signals fire risk is comprehension, and anticipating ignition so the patient is moved and fire crews are called is projection. Any answer restricting the scenario to perception alone, comprehension alone or projection alone ignores the other two steps that are explicitly described in the stem. Key point: notice, then interpret, then act pre-emptively means all three levels of situation awareness were applied.', 'يلاحظ مسعف دخانًا يتصاعد من مركبة محطّمة، فيدرك أن ذلك يشير إلى خطر حريق، ويطلب فورًا رجال الإطفاء بينما ينقل المريض إلى منطقة آمنة. أي عبارة تصف هذا الموقف على أفضل وجه؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 15, 'Which of the following BEST describes teamwork in paramedic practice?', '["One healthcare provider making all decisions","Healthcare professionals working independently","Coordinated efforts of healthcare professionals toward a common goal","Assigning all tasks to the team leader"]'::jsonb, 2, 'جوهر العمل الجماعي هو التنسيق بين جهود متعددة تصبّ في هدف واحد مشترك، وهو ما ينص عليه الخيار الثالث. أما انفراد مقدّم واحد بكل القرارات فيلغي معنى الفريق، والعمل بشكل مستقل ينفي التنسيق، وإسناد كل المهام إلى القائد يُثقله ويحرم الفريق من دوره ويعطّل الأداء. المعلومة المفتاحية: الفريق تنسيقٌ وهدفٌ مشترك، لا انفرادٌ بالقرار ولا عملٌ متوازٍ منفصل.', 'Teamwork is the coordinated effort of several professionals directed at one shared goal, which is what makes coordination and a common objective the defining features. One provider making all decisions removes the point of a team, professionals working independently removes the coordination, and assigning all tasks to the team leader overloads the leader and wastes the rest of the team. Key point: a team means coordinated effort toward a common goal, not solo decision-making or parallel independent work.', 'أي مما يلي يصف العمل الجماعي في الممارسة الإسعافية على أفضل وجه؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 16, 'During a cardiac arrest, which team member is primarily responsible for maintaining an overview of the resuscitation and making major decisions', '["Compressor","Team leader","Recorder","Medication provider"]'::jsonb, 1, 'قائد الفريق هو من يحتفظ بالصورة الشاملة ويوزّع الأدوار ويتخذ القرارات الكبرى، ولذلك يُفضَّل ألا ينشغل بمهمة يدوية واحدة. أما القائم بالضغطات فمهمته محصورة في جودة الضغط، والمدوِّن يسجّل التوقيتات والأحداث، ومُعطي الأدوية ينفّذ الأوامر الدوائية، وكلهم أدوار تنفيذية محدودة النطاق. المعلومة المفتاحية: القائد ينسّق ويرى الصورة كاملة، والبقية ينفّذون مهام محدّدة.', 'The team leader holds the overview, assigns roles and makes the major decisions, which is why the leader should stay free of any single hands-on task. The compressor is focused on compression quality, the recorder logs times and events, and the medication provider executes drug orders — all narrow, task-specific roles. Key point: the leader coordinates and keeps the whole picture; everyone else performs a defined task.', 'أثناء توقّف القلب، أي عضو في الفريق مسؤول بشكل أساسي عن الحفاظ على النظرة الشاملة للإنعاش واتخاذ القرارات الكبرى؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 17, 'Which stage of team development is characterized by disagreements, conflicts, and competition among team members?', '["Forming","Storming","Norming","Performing"]'::jsonb, 1, 'اجتماع الخلافات والصراعات والتنافس في وصف واحد يشير حصرًا إلى مرحلة الخلاف، وهي المرحلة الثانية من مراحل تكوين الفريق. أما التشكيل فمرحلة تعارف وتحديد أوّلي للأدوار والأهداف، والتنظيم مرحلة تُبنى فيها الثقة وتُوحَّد التوقعات بعد تجاوز الصراع، والأداء مرحلة نضج يعمل فيها الفريق بسلاسة وتكيّف. المعلومة المفتاحية: التنافس على السلطة والأدوار هو البصمة المميّزة لمرحلة الخلاف دون سواها.', 'Disagreements, conflict and competition for authority appearing together describe the storming stage, the second phase of team development, when members test roles and challenge each other. Forming is the cautious introductory phase of setting roles and goals, norming is where trust is built and expectations align after the conflict is resolved, and performing is the mature phase of smooth, adaptive work. Key point: competition for authority and rejection of assigned roles is the fingerprint of storming.', 'أي مرحلة من مراحل تكوين الفريق تتّسم بالخلافات والصراعات والتنافس بين أعضاء الفريق؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 18, 'A paramedic says, "Heba, please administer the prescribed medication." Heba replies, "I will administer the medication," and later says, "Medication administered." What communication technique is being demonstrated?', '["SBAR","Call-out communication","Closed-loop communication","Passive communication"]'::jsonb, 2, 'الحلقة اكتملت بأركانها الثلاثة: أمر موجّه إلى شخص محدّد بالاسم، وإعادة الأمر من المتلقّي، وتأكيد إتمام التنفيذ، وهذا هو التواصل المغلق الحلقة. أما أسلوب الموقف والخلفية والتقييم والتوصية فأداة تسليم منظّم لا إصدار أمر، والنداء المفتوح إعلان معلومة للجميع بلا مستقبِل محدّد، والتواصل السلبي غياب للمبادرة والتأكيد. المعلومة المفتاحية: الحلقة لا تُغلق إلا بتأكيد التنفيذ العائد إلى مُصدِر الأمر.', 'The loop is complete here in all three parts: an order directed at a named individual, the receiver repeating it back, and a final confirmation that it has been done — that is closed-loop communication. SBAR is a structured handover or referral tool rather than a way of issuing an order, call-out communication broadcasts information to everyone without naming a receiver, and passive communication lacks any initiative or confirmation. Key point: the loop only closes when completion is reported back to the person who gave the order.', 'يقول مسعف: هبة، من فضلك أعطي الدواء الموصوف. فتردّ هبة: سأعطي الدواء، ثم تقول لاحقًا: تم إعطاء الدواء. ما أسلوب التواصل الذي يجري عرضه هنا؟', '{}'::jsonb, 'التواصل والتفويض', false, false, false),
  ((select id from s), 19, 'Which characteristic is most associated with an effective emergency team?', '["Unclear roles","Limited communication","Shared situation awareness","Individual decision-making only"]'::jsonb, 2, 'الفريق الفعّال يمتلك أعضاؤه الصورة الذهنية نفسها عن حالة المريض والمشهد، وهذا هو الوعي الظرفي المشترك. أما الأدوار غير الواضحة فتسبب التكرار والمهام المنسية، والتواصل المحدود يقطع تدفق المعلومات، وصنع القرار الفردي فقط يهدر خبرة بقية الأعضاء ويزيد احتمال الخطأ. المعلومة المفتاحية: الوعي الظرفي المشترك هو ما يحوّل مجموعة أفراد إلى فريق فعّال حقًا.', 'An effective emergency team is one in which every member holds the same mental picture of the patient and the scene, which is shared situation awareness. Unclear roles cause duplicated and forgotten tasks, limited communication blocks the flow of information, and individual decision-making only wastes the experience of the rest of the team and increases error. Key point: shared situation awareness is what turns a group of individuals into a genuinely effective team.', 'أي خاصية ترتبط أكثر بالفريق الطارئ الفعّال؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 20, 'What is the main purpose of clear role assignment during resuscitation?', '["To increase competition between providers","To prevent duplication and missed tasks","To allow the leader to perform every procedure","To reduce communication"]'::jsonb, 1, 'وضوح الأدوار يضمن أن كل مهمة لها صاحب واحد معروف، فلا تُنفَّذ مهمة مرتين ولا تُترك أخرى بلا منفّذ. أما زيادة التنافس فنتيجة سلبية لا هدف، وتنفيذ القائد لكل إجراء بنفسه يناقض التفويض ويُفقده النظرة الشاملة، وتقليل التواصل ضرر لا فائدة إذ يبقى التواصل ضروريًا حتى مع وضوح الأدوار. المعلومة المفتاحية: توزيع الأدوار يمنع ازدواج المهام وإغفالها معًا.', 'Clear role assignment gives every task exactly one owner, so nothing is done twice and nothing is left undone — it prevents duplication and missed tasks. Increasing competition between providers is a harmful side effect rather than a purpose, letting the leader perform every procedure contradicts delegation and destroys the overview, and reducing communication is a loss, since communication remains essential even when roles are clear. Key point: assigning roles prevents both duplicated effort and forgotten tasks.', 'ما الغرض الرئيسي من توزيع الأدوار بوضوح أثناء الإنعاش؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 21, 'Which stage of team development is characterized by disagreement and conflict?', '["Forming","Storming","Norming","Performing"]'::jsonb, 1, 'مرحلة الخلاف هي الثانية في ترتيب المراحل الأربع، وسمتها ظهور الاختلاف والصراع قبل أن يستقر الفريق على معايير عمل موحّدة. ولا يصح التشكيل لأنه مرحلة تعارف وتحديد أهداف بلا صدام بعد، ولا التنظيم لأنه يلي الصراع ويقوم على الثقة والاتفاق، ولا الأداء لأنه ذروة النضج والانسجام. المعلومة المفتاحية: ترتيب المراحل تشكيل ثم خلاف ثم تنظيم ثم أداء، والصراع محطة طبيعية في الطريق لا انحرافًا عنه.', 'Storming is the second of the four developmental stages, where open disagreement and conflict surface before the team settles on agreed ways of working. Forming cannot be right because it is the introductory phase of orientation and goal-setting before any clash occurs, norming follows the conflict and rests on trust and agreement, and performing is the peak of maturity and smooth cooperation. Key point: the sequence is forming, storming, norming, performing — conflict is a normal station on the route, not a derailment.', 'أي مرحلة من مراحل تكوين الفريق تتّسم بالاختلاف والصراع؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 22, 'During the forming stage, team members primarily need to establish:', '["Competition between team members","Roles, responsibilities, leadership, and goals","Long-term personal relationships","Independent decision-making"]'::jsonb, 1, 'مرحلة التشكيل مخصّصة لوضع الأساس التنظيمي: من يقود، ومن يفعل ماذا، وما الهدف المشترك. أما التنافس فسمة مرحلة الخلاف التالية، والعلاقات الشخصية طويلة الأمد ليست هدفًا لفريق طوارئ قد يجتمع لساعة واحدة، وصنع القرار المستقل يناقض فكرة الفريق المنسّق من أساسها. المعلومة المفتاحية: التشكيل مرحلة تأسيس الأدوار والمسؤوليات والقيادة والأهداف.', 'The forming stage is where the organisational foundation is laid: who leads, who does what, and what the shared goal is — roles, responsibilities, leadership and goals. Competition between members belongs to the storming stage that follows, long-term personal relationships are not the objective of an emergency team that may exist for a single hour, and independent decision-making contradicts the whole idea of a coordinated team. Key point: forming establishes roles, responsibilities, leadership and goals.', 'خلال مرحلة التشكيل، يحتاج أعضاء الفريق بشكل أساسي إلى تحديد:', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 23, 'Which behavior best represents the norming stage?', '["Team members compete for authority","Team members avoid communication","The team develops trust and shared expectations","Team members refuse assigned roles"]'::jsonb, 2, 'مرحلة التنظيم تعني استقرار المعايير وبناء الثقة وتوحيد التوقعات بعد تجاوز مرحلة الصراع، وهو ما يصفه الخيار الثالث. أما التنافس على السلطة ورفض الأدوار المسندة فسلوكان يميزان مرحلة الخلاف، وتجنّب التواصل خلل عام لا يصف مرحلة بعينها من مراحل النضج. المعلومة المفتاحية: التنظيم هو مرحلة الثقة والاتفاق على قواعد العمل المشتركة.', 'Norming is the stage where standards settle, trust develops and expectations become shared after the conflict of storming has been worked through. Competing for authority and refusing assigned roles are both storming behaviours, and avoiding communication is a general dysfunction rather than a description of any developmental stage. Key point: norming is the stage of trust and agreed shared expectations.', 'أي سلوك يمثّل مرحلة التنظيم على أفضل وجه؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 24, 'A team that communicates clearly, anticipates problems, and adapts rapidly is most likely in which stage?', '["Forming","Storming","Norming","Performing"]'::jsonb, 3, 'وضوح التواصل واستباق المشكلات وسرعة التكيّف ثلاث علامات على النضج الكامل، وهي بصمة مرحلة الأداء. أما التشكيل فمرحلة تلمّس أوّلي للأدوار، والخلاف مرحلة صراع تعرقل التنسيق، والتنظيم مرحلة استقرار للثقة لكنها لم تبلغ بعد ذروة الكفاءة والتكيّف السريع. المعلومة المفتاحية: الاستباق والتكيّف السريع لا يظهران إلا في مرحلة الأداء، وهي آخر المراحل الأربع.', 'Clear communication, anticipation of problems and rapid adaptation are the three hallmarks of a fully mature team, which is the performing stage. Forming is still tentative role-finding, storming is conflict that obstructs coordination, and norming has established trust but has not yet reached peak efficiency and rapid adaptability. Key point: anticipation and rapid adaptation appear only in performing, the last of the four stages.', 'الفريق الذي يتواصل بوضوح ويستبق المشكلات ويتكيّف بسرعة يكون على الأرجح في أي مرحلة؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 25, 'In an emergency department, which professional may be part of the emergency team?', '["Paramedic","Respiratory therapist","Registered nurse","All of the above"]'::jsonb, 3, 'فريق الطوارئ متعدد التخصصات بطبيعته، فيضم المسعف والمعالج التنفسي والممرض المسجّل وغيرهم، ولذلك فالإجابة الجامعة هي الصحيحة. واختيار أي مهنة منفردة كالمسعف أو المعالج التنفسي أو الممرض يقصر الفريق على تخصص واحد ويناقض مبدأ تكامل الأدوار في الطوارئ. المعلومة المفتاحية: تعدد التخصصات سمة أصيلة في فريق الطوارئ، وكل تخصص يضيف خبرة مختلفة.', 'An emergency team is multidisciplinary by nature, so paramedics, respiratory therapists and registered nurses may all belong to it, making the inclusive answer correct. Choosing any single profession alone restricts the team to one discipline and contradicts the principle that complementary roles are combined in emergency care. Key point: multidisciplinary membership is intrinsic to the emergency team, with each profession contributing different expertise.', 'في قسم الطوارئ، أي من هؤلاء المهنيين قد يكون جزءًا من فريق الطوارئ؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 26, 'After STOP, the team should LOOK by:', '["Reassessing the patient","Leaving the scene","Ignoring vital signs","Waiting for someone else to decide"]'::jsonb, 0, 'خطوة النظر في هذا الأسلوب تعني جمع صورة محدّثة عن المريض، أي إعادة تقييمه بعد التوقّف اللحظي عن الاندفاع. أما مغادرة الموقع فهروب من الموقف لا تقييم له، وتجاهل العلامات الحيوية يفقد أهم مصدر للمعطيات، وانتظار قرار الآخرين تعطيل للمسؤولية وليس نظرًا. المعلومة المفتاحية: التوقّف ثم النظر يعني إعادة تقييم المريض والمشهد قبل استئناف القرار.', 'In the stop-look-think-plan approach, the LOOK step means gathering an updated picture of the patient — in other words reassessing after pausing the momentum of action. Leaving the scene abandons the situation rather than examining it, ignoring vital signs discards the most important data source, and waiting for someone else to decide surrenders responsibility instead of looking. Key point: after stopping, LOOK means reassess the patient and the scene before resuming decisions.', 'بعد التوقّف، ينبغي على الفريق أن ينظر عبر:', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 27, 'Why is ABCDE useful during emergency decision-making?', '["It eliminates the need for clinical judgment","It provides structure during chaotic situations","It guarantees a diagnosis","It prevents reassessment"]'::jsonb, 1, 'قيمة هذا النهج أنه يفرض ترتيبًا ثابتًا للأولويات وسط الفوضى فلا يُنسى تهديد حياة تحت ضغط الموقف. أما إلغاء الحكم السريري فخطأ لأن النهج يدعم الحكم ولا يستبدله، وهو لا يضمن تشخيصًا لأنه أداة أولويات لا أداة تشخيص، ولا يمنع إعادة التقييم بل يقوم عليها ويكرّرها من أوله. المعلومة المفتاحية: قوة نهج ABCDE في التنظيم والترتيب، لا في الاستغناء عن التفكير.', 'The value of ABCDE is that it imposes a fixed priority order amid chaos, so no immediate life threat is forgotten under pressure — it provides structure during chaotic situations. It does not eliminate clinical judgment because it supports rather than replaces thinking, it guarantees no diagnosis because it is a prioritisation tool not a diagnostic one, and far from preventing reassessment it is built on repeating the sequence from the top. Key point: the strength of ABCDE is structure and priority order, not a substitute for thinking.', 'لماذا يُعدّ نهج ABCDE مفيدًا أثناء صنع القرار في الحالات الطارئة؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 28, 'Which problem should generally receive the highest priority?', '["Minor old injury","Patient''s occupation","Life-threatening airway obstruction","Patient''s favorite food"]'::jsonb, 2, 'انسداد المجرى الهوائي تهديد فوري للحياة يقتل خلال دقائق، فهو أول ما يُعالج بلا منازع. أما الإصابة القديمة البسيطة فلا تهدّد الحياة الآن، ومهنة المريض معلومة سياقية لا تدخل في ترتيب الأولويات الحادة، والطعام المفضّل تفصيل لا علاقة له بالحالة الطارئة أصلًا. المعلومة المفتاحية: تهديدات الحياة الفورية تسبق كل شيء آخر، والمجرى الهوائي في مقدمتها.', 'A life-threatening airway obstruction kills within minutes, so it takes absolute priority over everything else in the list. A minor old injury poses no immediate threat to life, the patient''s occupation is contextual background irrelevant to acute prioritisation, and the patient''s favourite food has no bearing on an emergency at all. Key point: immediate life threats come before everything else, and the airway is first among them.', 'أي مشكلة ينبغي أن تحظى عمومًا بالأولوية الأعلى؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 29, 'Critical thinking differs from memorization because critical thinking requires the paramedic to:', '["Follow one intervention automatically","Question assumptions and evaluate alternatives","Ignore patient-specific factors","Avoid clinical judgment"]'::jsonb, 1, 'التفكير النقدي عملية نشطة تُخضع الافتراضات للمساءلة وتوازن بين تفسيرات بديلة قبل الحسم. أما اتّباع تدخل واحد بشكل تلقائي فهو الحفظ والتطبيق الآلي بعينه، وتجاهل العوامل الخاصة بالمريض يلغي فردية الحالة، وتجنّب الحكم السريري نقيض التفكير النقدي تمامًا. المعلومة المفتاحية: التفكير النقدي يسأل لماذا وما البديل، والحفظ يكتفي بما هي الخطوة التالية.', 'Critical thinking means questioning assumptions and evaluating alternatives — actively testing whether the first impression fits this particular patient. Following one intervention automatically is exactly the rote application that critical thinking replaces, ignoring patient-specific factors removes the individual context that reasoning depends on, and avoiding clinical judgment is the opposite of what critical thinking requires. Key point: memorisation recalls one answer; critical thinking challenges assumptions and weighs alternatives.', 'يختلف التفكير النقدي عن الحفظ لأن التفكير النقدي يتطلب من المسعف أن:', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 30, 'During a cardiac arrest, one paramedic performs chest compressions while another manages the airway. What teamwork principle is being demonstrated?', '["Task sharing","Individual performance","Conflict management","Tunnel vision"]'::jsonb, 0, 'تنفيذ مهمتين حرجتين بالتوازي على يد شخصين مختلفين هو تعريف مشاركة المهام وتوزيعها. أما الأداء الفردي فيعني انفراد شخص بالعمل وهو نقيض المشهد، وإدارة الصراع تخصّ الخلافات بين الأعضاء ولا صراع هنا، ورؤية النفق خطأ في الانتباه لا مبدأ من مبادئ العمل الجماعي. المعلومة المفتاحية: توزيع المهام المتوازية بين الأعضاء يرفع الكفاءة ويقلّل زمن التدخل.', 'Two providers performing different parallel tasks at the same time — compressions and airway management — is task sharing, the division of simultaneous work across the team. Individual performance describes one person working alone, conflict management deals with disagreement rather than workload division, and tunnel vision is a failure of attention, not a teamwork principle. Key point: task sharing means distributing parallel tasks among different members at the same time.', 'أثناء توقّف القلب، يقوم مسعف بالضغطات الصدرية بينما يدير آخر المجرى الهوائي. أي مبدأ من مبادئ العمل الجماعي يجري عرضه هنا؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 31, 'The team leader tells a nurse, "Prepare the medication." The nurse repeats the instruction and then reports, "The medication is ready." What communication method is this?', '["SBAR","Closed-loop communication","Handover communication","Passive communication"]'::jsonb, 1, 'إعادة التعليمة ثم الإبلاغ عن جاهزية الدواء يغلقان الحلقة بين مُصدِر الأمر ومنفّذه، فهذا تواصل مغلق الحلقة. أما أسلوب الموقف والخلفية والتقييم والتوصية فيُستخدم لعرض حالة كاملة بشكل منظّم، وتواصل التسليم ينقل مسؤولية المريض إلى فريق آخر، والتواصل السلبي لا يتضمن تأكيدًا ولا مبادرة. المعلومة المفتاحية: إعادة الأمر مع تأكيد إتمامه هما ركنا التواصل المغلق الحلقة.', 'The order is directed, repeated back by the receiver, and then confirmed as completed, so all three elements of closed-loop communication are present. SBAR is a structured reporting format for handovers and referrals, handover communication transfers care between providers rather than issuing an instruction, and passive communication involves no assertive direction or confirmation at all. Key point: order given, order repeated, completion reported — that is a closed loop.', 'يقول قائد الفريق لممرضة: جهّزي الدواء. فتعيد الممرضة التعليمة ثم تبلّغ قائلة: الدواء جاهز. ما أسلوب التواصل هذا؟', '{}'::jsonb, 'التواصل والتفويض', false, false, false),
  ((select id from s), 32, 'A paramedic arrives at an emergency scene and asks, "Who is leading the resuscitation?" Which stage of team formation is being established?', '["Storming","Norming","Forming","Performing"]'::jsonb, 2, 'السؤال عن هوية القائد هو خطوة تأسيسية لتحديد الأدوار والقيادة، وهذا صميم مرحلة التشكيل. أما الخلاف فيتطلب صراعًا وتنافسًا ولا أثر لهما في السؤال، والتنظيم يفترض أن الأدوار قد استقرت وبُنيت الثقة، والأداء يفترض فريقًا ناضجًا يعمل بانسجام لا فريقًا يبحث عن قائده. المعلومة المفتاحية: أي سؤال عن الأدوار والقيادة عند بداية الحدث يشير إلى مرحلة التشكيل.', 'Asking who is leading the resuscitation is an attempt to establish leadership and roles, which is the defining activity of the forming stage. Storming would involve challenging or competing for that leadership, norming reflects settled trust and agreed standards, and performing describes a team already working smoothly with roles long established. Key point: any question that establishes who leads and who does what marks the forming stage.', 'يصل مسعف إلى موقع طارئ ويسأل: من يقود الإنعاش؟ أي مرحلة من مراحل تكوين الفريق يجري تأسيسها هنا؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 33, 'During an emergency, the team leader assigns one provider to airway management and another to medication preparation. Why is this important?', '["To increase competition","To prevent duplication and missed tasks","To reduce communication","To allow the leader to work alone"]'::jsonb, 1, 'إسناد كل مهمة إلى شخص بعينه يضمن تغطية كل المهام الحرجة دون ازدواج ودون نسيان أي منها. أما زيادة التنافس فأثر ضار لا غاية مقصودة، وتقليل التواصل ليس هدفًا إذ يبقى تبادل المعلومات مطلوبًا رغم وضوح الأدوار، والسماح للقائد بالعمل بمفرده يناقض فكرة التفويض جوهريًا. المعلومة المفتاحية: التوزيع الواضح للأدوار درع مزدوج ضد التكرار وضد المهام المنسية.', 'Giving one provider the airway and another the medication ensures each task has a single identified owner, which prevents duplication and missed tasks. Increasing competition is a harm rather than a rationale, reducing communication is never a goal since clear roles still require information sharing, and allowing the leader to work alone contradicts the very act of delegating. Key point: explicit role allocation stops tasks being done twice and stops tasks being forgotten.', 'أثناء حالة طارئة، يسند قائد الفريق إدارة المجرى الهوائي إلى أحد مقدّمي الرعاية وتحضير الدواء إلى آخر. لماذا يُعدّ ذلك مهمًا؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 34, 'A paramedic sees that a patient''s oxygen saturation is falling. What should the paramedic do after identifying this problem?', '["Ignore it","Reassess and determine what needs to happen next","Wait until transport is complete","Continue the original plan without reassessment"]'::jsonb, 1, 'ملاحظة تدهور في مؤشر حيوي تستوجب إعادة تقييم فورية وتحديد الخطوة التالية، فالمعلومة الجديدة تُغيّر الخطة. أما التجاهل فإهمال صريح لتهديد وشيك، والانتظار حتى انتهاء النقل يؤخر التدخل في وقت حرج، ومتابعة الخطة الأصلية دون إعادة تقييم يعني التمسّك بصورة قديمة لم تعد مطابقة للواقع. المعلومة المفتاحية: كل معطى جديد يستدعي إعادة تقييم فورية وتعديلًا محتملًا للخطة.', 'A falling oxygen saturation is new information, and new information demands that the paramedic reassess and determine what needs to happen next rather than simply note it. Ignoring it discards a warning of deterioration, waiting until transport is complete delays action on a developing threat, and continuing the original plan without reassessment means the plan no longer matches the patient. Key point: every new finding triggers reassessment and a decision, not just documentation.', 'يلاحظ مسعف أن تشبّع الأكسجين لدى المريض في انخفاض. ماذا ينبغي أن يفعل المسعف بعد تحديد هذه المشكلة؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 35, 'A team member notices that another provider is struggling with a task and offers appropriate assistance. Which teamwork principle is demonstrated?', '["Mutual support","Authority gradient","Anchoring","Competition"]'::jsonb, 0, 'ملاحظة تعثّر زميل ومبادرته بالمساعدة المناسبة هو التعريف العملي للدعم المتبادل داخل الفريق. أما تدرّج السلطة فيصف فارق الرتبة الذي يعيق التواصل، والتثبيت على المعلومة الأولى خطأ معرفي في التشخيص لا سلوك جماعي، والتنافس نقيض المساعدة تمامًا. المعلومة المفتاحية: الدعم المتبادل يعني رصد حاجة الزميل ومدّ يد العون قبل أن يقع الخطأ.', 'Noticing that a colleague is struggling and offering appropriate help is mutual support, the team behaviour of monitoring workload and assisting before performance fails. Authority gradient is the rank difference that silences junior members, anchoring is a cognitive error of clinging to an early impression, and competition undermines rather than supports the team. Key point: mutual support means watching your colleagues'' workload and stepping in to help.', 'يلاحظ أحد أعضاء الفريق أن مقدّم رعاية آخر يواجه صعوبة في إحدى المهام فيقدّم له مساعدة مناسبة. أي مبدأ من مبادئ العمل الجماعي يجري عرضه؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 36, 'During resuscitation, two providers begin preparing the same medication while nobody is documenting. What is the most likely cause?', '["Clear role assignment","Poor role assignment","Effective leadership","Closed-loop communication"]'::jsonb, 1, 'اجتماع تكرار المهمة نفسها مع إهمال مهمة أخرى كليًا هو البصمة الكلاسيكية لسوء توزيع الأدوار. أما التوزيع الواضح فكان سيمنع الازدواج والنسيان معًا، والقيادة الفعّالة كانت ستكشف الخلل مبكرًا وتصحّحه، والتواصل المغلق الحلقة كان سيبيّن من يحضّر الدواء ومن يوثّق. المعلومة المفتاحية: الازدواج والنسيان في آن واحد يدلان دائمًا على خلل في توزيع الأدوار.', 'Two providers preparing the same drug while nobody documents is the signature of poor role assignment: the same task has two owners and another task has none. Clear role assignment would have produced the opposite result, effective leadership would have allocated tasks explicitly, and closed-loop communication concerns confirming individual orders rather than distributing the workload. Key point: simultaneous duplication plus an omitted task points directly to failed role allocation.', 'أثناء الإنعاش، يبدأ اثنان من مقدّمي الرعاية بتحضير الدواء نفسه بينما لا يقوم أحد بالتوثيق. ما السبب الأرجح؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 37, 'A paramedic receives information from a frightened bystander that the patient "is probably fine." The patient is pale, confused, and hypotensive. What should the paramedic do?', '["Accept the bystander''s interpretation","Evaluate the information against the patient''s clinical findings","Ignore all bystander information","Assume the patient is stable"]'::jsonb, 1, 'التفكير النقدي يوجب مقارنة كل معلومة واردة بالموجودات السريرية الموضوعية قبل الأخذ بها، والشحوب والتشوش وانخفاض الضغط تناقض قول المارّ. أما قبول تفسير الشخص المارّ أو افتراض استقرار المريض فتفريط خطير في مواجهة علامات صدمة واضحة، وتجاهل جميع معلومات المارّة تطرّف معاكس يهدر شهادات قد تكون مفيدة عن آلية الحدث. المعلومة المفتاحية: المعلومات من غير المختصين تُوزن بميزان الموجودات السريرية، لا تُقبل ولا تُرفض جملة.', 'A pale, confused and hypotensive patient contradicts the bystander''s reassurance, so the paramedic must evaluate the information against the patient''s clinical findings rather than take it at face value. Accepting the bystander''s interpretation ignores objective evidence of shock, ignoring all bystander information discards potentially useful history, and assuming the patient is stable is a dangerous conclusion the findings do not support. Key point: weigh third-party information against clinical findings — never accept it and never discard it wholesale.', 'يتلقى مسعف معلومة من أحد المارّة المذعورين بأن المريض على الأرجح بخير. لكن المريض شاحب ومشوّش ولديه انخفاض في ضغط الدم. ماذا ينبغي أن يفعل المسعف؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 38, 'A patient with chest pain reports nausea and sweating. The paramedic initially thinks it is anxiety. Later, the ECG shows ST-segment changes. What should the paramedic do?', '["Continue with the anxiety diagnosis","Reassess and consider a different clinical explanation","Ignore the ECG","Stop assessment"]'::jsonb, 1, 'ظهور تغيّرات في مقطع الضغط معطى موضوعي جديد يوجب مراجعة الانطباع الأول والنظر في متلازمة إكليلية حادة. أما الاستمرار على تشخيص القلق فهو التثبيت على التشخيص الأول بعينه، وتجاهل تخطيط القلب إسقاط متعمّد لأقوى دليل متاح، وإيقاف التقييم تخلٍّ عن المريض في أخطر لحظة. المعلومة المفتاحية: الدليل الجديد يعلو على الانطباع الأول، ومراجعة التشخيص علامة كفاءة لا تردّد.', 'ST-segment changes are new objective data that contradict the initial impression, so the paramedic must reassess and consider a different clinical explanation instead of holding on to anxiety. Continuing with the anxiety diagnosis is anchoring on the first impression, ignoring the ECG discards the decisive evidence, and stopping assessment abandons a patient with an evolving cardiac presentation. Key point: new evidence that conflicts with the working diagnosis obliges you to revise it — that is how anchoring is avoided.', 'مريض يعاني ألمًا صدريًا ويشكو من غثيان وتعرّق. يظن المسعف في البداية أنها حالة قلق. لاحقًا يُظهر تخطيط القلب تغيّرات في مقطع الضغط. ماذا ينبغي أن يفعل المسعف؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 39, 'During an emergency, several people speak simultaneously and the medication order is misunderstood. Which communication barrier is MOST obvious?', '["Mutual respect","Multiple people speaking simultaneously","Clear delegation","Psychological safety"]'::jsonb, 1, 'الحاجز المذكور صراحة في نص السيناريو هو تداخل الأصوات وتحدّث عدة أشخاص في وقت واحد، وهو ما أدى إلى سوء فهم الأمر. أما الاحترام المتبادل والتفويض الواضح والأمان النفسي فثلاثتها عوامل تُحسّن التواصل وتقلّل الأخطاء، فلا يصح عدّ أي منها حاجزًا. المعلومة المفتاحية: تداخل الأصوات في المواقف الطارئة من أشهر حواجز التواصل وأسرعها تسببًا في الخطأ الدوائي.', 'When several people speak at once the message is degraded and the drug order is misheard, so multiple people speaking simultaneously is the obvious communication barrier here. Mutual respect and psychological safety are enablers of good communication rather than barriers, and clear delegation is precisely what was absent instead of being the problem itself. Key point: simultaneous speech is a classic communication barrier — one voice at a time for critical orders.', 'أثناء حالة طارئة، يتحدث عدة أشخاص في وقت واحد فيُساء فهم أمر إعطاء الدواء. أي حاجز من حواجز التواصل هو الأوضح؟', '{}'::jsonb, 'التواصل والتفويض', false, false, false),
  ((select id from s), 40, 'A team leader says, "Nurse Sara, prepare the prescribed medication and tell me when it is ready." Why is this better than saying, "Someone prepare the medication"?', '["It creates ambiguity","It identifies a specific person and requires confirmation","It eliminates responsibility","It prevents communication"]'::jsonb, 1, 'تسمية المنفّذ بالاسم مع طلب الإبلاغ عند الجاهزية يحدّد المسؤولية ويغلق الحلقة، بخلاف النداء العام الذي يظن معه كل فرد أن غيره سينفّذ. أما القول إنه يخلق غموضًا فمعكوس تمامًا لأنه يزيله، وإلغاء المسؤولية أثر النداء العام لا التوجيه المحدّد، ومنع التواصل نتيجة مناقضة لصيغة تطلب ردًا صريحًا. المعلومة المفتاحية: التوجيه باسم شخص محدّد مع طلب تأكيد هو حجر الأساس في التواصل الآمن.', 'Naming Sara and asking to be told when the drug is ready identifies a specific person and requires confirmation, which prevents diffusion of responsibility and closes the communication loop. Saying it creates ambiguity is the opposite of what naming does, eliminating responsibility describes the vague alternative instruction rather than the named one, and it clearly does not prevent communication but structures it. Key point: address the order to a named individual and demand confirmation of completion.', 'يقول قائد الفريق: الممرضة سارة، جهّزي الدواء الموصوف وأبلغيني عندما يكون جاهزًا. لماذا يُعدّ هذا أفضل من قول: ليجهّز أحدكم الدواء؟', '{}'::jsonb, 'التواصل والتفويض', false, false, false),
  ((select id from s), 41, 'A patient initially improves after treatment but later develops worsening mental status and hypotension. What should the paramedic do?', '["Continue the original treatment without change","Revise the treatment plan based on the new findings","Stop reassessment","Assume the original diagnosis was correct"]'::jsonb, 1, 'تدهور الحالة العقلية مع هبوط الضغط بعد تحسّن أوّلي يعني ظهور مشكلة جديدة تستوجب مراجعة الخطة كاملة. أما متابعة العلاج الأصلي دون تغيير فتجاهل لتحوّل واضح في الحالة، وإيقاف إعادة التقييم يقطع مصدر المعلومات في أخطر وقت، وافتراض صحة التشخيص الأصلي تثبيت معرفي يمنع اكتشاف السبب الجديد. المعلومة المفتاحية: التحسّن المؤقت لا يعني انتهاء الخطر، والتدهور الجديد يفرض خطة جديدة.', 'Worsening mental status and hypotension after initial improvement are new findings that invalidate the working plan, so the paramedic must revise the treatment plan based on them. Continuing the original treatment without change ignores clear deterioration, stopping reassessment removes the only means of detecting further change, and assuming the original diagnosis was correct is anchoring in the face of contrary evidence. Key point: deterioration after improvement means the plan and the diagnosis both need revisiting.', 'يتحسّن المريض في البداية بعد العلاج لكنه يصاب لاحقًا بتدهور في الحالة العقلية وانخفاض في ضغط الدم. ماذا ينبغي أن يفعل المسعف؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 42, 'During a trauma call, the leader asks the airway provider for an updated SpO₂ and asks another provider for the latest blood pressure. Why?', '["To maintain situation awareness","To create conflict","To avoid delegation","To delay treatment"]'::jsonb, 0, 'جمع القائد لقراءات محدّثة من أعضاء الفريق يحافظ على صورة ذهنية مطابقة لحالة المريض اللحظية، وهذا هو الوعي الظرفي. أما خلق الصراع فليس غاية لأي قائد كفء، وتجنّب التفويض معكوس لأن السؤال نفسه شكل من أشكال توزيع الأدوار، وتأخير العلاج نتيجة ضارة لا هدف مقصود. المعلومة المفتاحية: طلب التحديثات الدورية من الفريق هو الوسيلة العملية لبناء الوعي الظرفي المشترك.', 'Actively requesting an updated saturation and the latest blood pressure is how the leader refreshes the team''s information and maintains situation awareness across the whole patient rather than one parameter. It does not create conflict since asking for updates is routine coordination, it does not avoid delegation because the roles are already delegated, and it does not delay treatment since the information directly guides the next decision. Key point: a leader keeps situation awareness alive by deliberately pulling updates from each role.', 'أثناء بلاغ إصابة، يسأل القائد المسؤول عن المجرى الهوائي عن قراءة محدّثة لتشبّع الأكسجين، ويسأل مقدّم رعاية آخر عن آخر قياس لضغط الدم. لماذا؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 43, 'A paramedic is under severe stress and begins focusing only on a patient''s obvious leg injury while failing to notice respiratory deterioration. What phenomenon is occurring?', '["Improved situation awareness","Tunnel vision","Effective prioritization","Norming"]'::jsonb, 1, 'الضغط الشديد ضيّق دائرة الانتباه على الإصابة الظاهرة حتى فات التدهور التنفسي، وهذه رؤية النفق بعينها. أما تحسّن الوعي الظرفي فمعكوس للواقع لأن الصورة تقلّصت لا اتسعت، وترتيب الأولويات الفعّال كان سيضع التنفس قبل إصابة الساق، والتنظيم مرحلة من مراحل تكوين الفريق لا علاقة لها بانتباه فرد. المعلومة المفتاحية: الضغط النفسي محفّز شائع لرؤية النفق، والوقاية منه بإعادة التقييم المنهجي.', 'Severe stress narrowing attention onto the obvious leg injury while respiratory deterioration goes unnoticed is tunnel vision, the classic stress-induced failure of situation awareness. Improved situation awareness would have widened the field of attention, effective prioritisation would have addressed breathing before a limb injury, and norming is a stage of team development with no bearing on individual attention. Key point: stress narrows attention, and the narrowing itself is tunnel vision.', 'مسعف تحت ضغط شديد يبدأ بالتركيز على إصابة واضحة في ساق المريض فقط بينما يفشل في ملاحظة تدهور تنفسي. ما الظاهرة التي تحدث؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 44, 'A patient arrives with severe shortness of breath, RR 36/min, SpO₂ 80%, cyanosis, and altered mental status. The team recognizes the findings and predicts rapid deterioration. What is the BEST interpretation?', '["Level 1 situation awareness only","Level 2 situation awareness only","Level 3 situation awareness","Loss of situation awareness"]'::jsonb, 2, 'الفريق تجاوز الملاحظة والتفسير إلى استشراف تدهور لم يقع بعد، وهذا يضع الموقف عند المستوى الثالث أي التوقّع. أما حصره في المستوى الأول أو الثاني فيتجاهل كلمة يتوقّع الواردة صراحة في النص، وفقدان الوعي الظرفي وصف معاكس تمامًا لفريق قرأ الحالة قراءة دقيقة واستبق مآلها. المعلومة المفتاحية: بلوغ المستوى الثالث يستلزم اجتياز المستويين السابقين، وكلمة التوقّع هي الدليل الحاسم.', 'The team has perceived the findings, understood their severity, and gone further by predicting rapid deterioration, which places them at Level 3 situation awareness — projection includes the two levels beneath it. Level 1 only would stop at noting the numbers, Level 2 only would stop at recognising severe respiratory failure, and loss of situation awareness is contradicted by the accurate forecast the team has made. Key point: once a team predicts what will happen next, it has reached Level 3, projection.', 'يصل مريض يعاني ضيق تنفس شديد، بمعدل تنفس ستة وثلاثين في الدقيقة، وتشبّع أكسجين ثمانين بالمئة، وزرقة، وتغيّر في الحالة العقلية. يتعرّف الفريق على هذه الموجودات ويتوقّع تدهورًا سريعًا. ما التفسير الأفضل؟', '{}'::jsonb, 'الوعي الظرفي', false, false, false),
  ((select id from s), 45, 'During cardiac arrest, the team leader orders epinephrine. The nurse repeats the order but does not administer the medication. The leader assumes it was completed. What failed?', '["Situation awareness only","Closed-loop communication","Team formation","Pattern recognition"]'::jsonb, 1, 'الحلقة انفتحت عند الخطوة الأخيرة إذ أُعيد الأمر ولم يُبلَّغ عن تنفيذه، فوقع القائد في افتراض خاطئ، وهذا فشل في التواصل المغلق الحلقة. أما حصر الخلل في الوعي الظرفي فقط فيغفل السبب المباشر وهو انقطاع التأكيد، وتكوين الفريق لم يكن موضع المشكلة لأن الأدوار كانت واضحة، والتعرف على النمط عملية تشخيصية لا صلة لها بتنفيذ أمر دوائي. المعلومة المفتاحية: إعادة الأمر وحدها لا تغلق الحلقة، والتأكيد على إتمام التنفيذ هو الركن الحاسم.', 'The nurse repeated the order but never reported administration, so the leader wrongly assumed the drug was given — the loop was opened but never closed, which is a failure of closed-loop communication. Situation awareness alone is too broad a label for a specific communication breakdown, team formation refers to the developmental stages and is irrelevant here, and pattern recognition concerns clinical reasoning rather than message confirmation. Key point: repeating an order back is not enough — the loop closes only with confirmation that it was actually done.', 'أثناء توقّف القلب، يأمر قائد الفريق بإعطاء الإبينفرين. تعيد الممرضة الأمر لكنها لا تعطي الدواء. يفترض القائد أن الأمر قد نُفِّذ. ما الذي فشل؟', '{}'::jsonb, 'التواصل والتفويض', false, false, false),
  ((select id from s), 46, 'A paramedic records BP 80/50 mmHg in a patient with vomiting and diarrhea. Instead of simply documenting the number, the paramedic considers dehydration, symptoms, and trends. What skill is demonstrated?', '["Data interpretation","Memorization","Storming","Passive followership"]'::jsonb, 0, 'ربط الرقم بالسياق السريري والاتجاه الزمني بدل تسجيله مجردًا هو تفسير للبيانات لا مجرد توثيق. أما الحفظ فاسترجاع آلي للمعلومة بلا تحليل، والخلاف مرحلة من مراحل تكوين الفريق لا مهارة معرفية، والتّبعية السلبية موقف سلوكي يعني الصمت وعدم المبادرة وهو نقيض ما فعله المسعف. المعلومة المفتاحية: القيمة المخبرية أو الحيوية لا تعني شيئًا خارج سياق المريض واتجاه تغيّرها.', 'Considering the dehydration, the symptoms and the trend rather than merely writing down 80/50 is data interpretation — turning a number into clinical meaning. Memorisation would be simple recall of a threshold value, storming is a team development stage unrelated to reasoning, and passive followership describes a member who does not engage at all. Key point: interpreting data means asking what a value means in this patient, not merely recording it.', 'يسجّل مسعف ضغط دم ثمانين على خمسين ملم زئبقي لدى مريض يعاني قيئًا وإسهالًا. وبدل الاكتفاء بتوثيق الرقم، يأخذ المسعف في الاعتبار الجفاف والأعراض والاتجاهات. ما المهارة التي يجري عرضها؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 47, 'A paramedic encounters a patient with wheezing, tachypnea, accessory muscle use, difficulty speaking, and low SpO₂. The paramedic recognizes a pattern of severe respiratory distress. What clinical reasoning process is being used?', '["Pattern recognition","Anchoring","Handover","Delegation"]'::jsonb, 0, 'تجميع علامات متعددة في صورة سريرية مألوفة واحدة هو التعرف على النمط، وهو استدلال سريع يعتمد على الخبرة المخزّنة. أما التثبيت على المعلومة الأولى فخطأ معرفي يقوم على التمسك بانطباع مبكر لا على تجميع علامات متكاملة، والتسليم نقل مسؤولية المريض لفريق آخر، والتفويض إسناد مهمة لعضو في الفريق. المعلومة المفتاحية: التعرف على النمط سريع ومفيد، لكنه يبقى بحاجة إلى إعادة تقييم تحميه من الخطأ.', 'Matching wheeze, tachypnoea, accessory muscle use, difficulty speaking and low saturation against a stored clinical picture of severe respiratory distress is pattern recognition. Anchoring is the error of fixing on an early impression despite new evidence, handover is the structured transfer of care, and delegation is the allocation of tasks — none of these describes recognising a clinical picture. Key point: pattern recognition matches a cluster of findings to a familiar clinical picture, and is fast but must still be rechecked.', 'يواجه مسعف مريضًا لديه أزيز وتسرّع في التنفس واستخدام للعضلات المساعدة وصعوبة في الكلام وانخفاض في تشبّع الأكسجين. يتعرّف المسعف على نمط ضائقة تنفسية شديدة. ما عملية الاستدلال السريري المستخدمة؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 48, 'A paramedic identifies severe respiratory distress but spends several minutes collecting irrelevant information before treating the patient. Which principle was violated?', '["Treat life threats promptly","Use SBAR","Followership","Norming"]'::jsonb, 0, 'الضائقة التنفسية الشديدة تهديد حياة يستوجب تدخلًا فوريًا، وتأخيره بجمع معلومات غير ذات صلة انتهاك مباشر لمبدأ معالجة تهديدات الحياة أولًا. أما أسلوب الموقف والخلفية والتقييم والتوصية فأداة تسليم منظّم لا تخصّ ترتيب أولويات العلاج، والتّبعية تصف سلوك العضو تجاه قائده، والتنظيم مرحلة من مراحل نضج الفريق. المعلومة المفتاحية: جمع المعلومات لا يسبق أبدًا معالجة تهديد حياة قائم.', 'Spending several minutes gathering irrelevant information while severe respiratory distress goes untreated violates the rule to treat life threats promptly. Using SBAR concerns structured reporting rather than treatment priority, followership describes the behaviour of team members supporting a leader, and norming is a team development stage — none of them is the principle that was broken. Key point: identified life threats are treated first; history-taking waits.', 'يحدّد مسعف وجود ضائقة تنفسية شديدة لكنه يقضي عدة دقائق في جمع معلومات غير ذات صلة قبل معالجة المريض. أي مبدأ تم انتهاكه؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 49, 'During an emergency, the team leader becomes overwhelmed and starts performing several tasks personally instead of coordinating the team. What leadership principle is being violated?', '["Effective delegation","Situation awareness","Handover","Pattern recognition"]'::jsonb, 0, 'انشغال القائد بتنفيذ المهام بنفسه بدل توزيعها هو إخفاق مباشر في التفويض الفعّال، وهو المبدأ المنتهَك هنا. صحيح أن الوعي الظرفي سيتضرر تبعًا لذلك لكنه نتيجة لا سبب، والتسليم يخص نقل المريض إلى فريق آخر، والتعرف على النمط عملية تشخيصية لا صلة لها بأسلوب القيادة. المعلومة المفتاحية: مهمة القائد الأساسية التنسيق والتفويض، وانغماسه في التنفيذ يُفقد الفريق بوصلته.', 'A leader who takes on several tasks personally instead of coordinating has abandoned effective delegation, and with it the overview that only the leader can hold. Situation awareness is a consequence that suffers rather than the principle directly violated, handover concerns transferring care to another provider, and pattern recognition is a clinical reasoning process unrelated to task allocation. Key point: the leader''s job is to delegate and coordinate, not to perform the most tasks personally.', 'أثناء حالة طارئة، يصاب قائد الفريق بالإرهاق الذهني ويبدأ بتنفيذ عدة مهام بنفسه بدل تنسيق عمل الفريق. أي مبدأ من مبادئ القيادة يجري انتهاكه؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 50, 'A junior paramedic notices that the patient''s condition is deteriorating. The team leader does not notice the change. The junior paramedic respectfully reports the finding. Which principle is MOST important here?', '["Authority gradient should prevent questioning","Team members should speak up about safety concerns","Only the leader can assess the patient","Followership means remaining silent"]'::jsonb, 1, 'ثقافة السلامة تُلزم كل عضو مهما صغرت رتبته بأن يرفع صوته عند ملاحظة خطر على المريض، وهذا ما فعله المسعف المبتدئ. أما القول إن تدرّج السلطة ينبغي أن يمنع التساؤل فهو الخطر الذي نحاربه لا مبدأ نتبناه، وحصر التقييم بالقائد يهدر عيون الفريق كلها، وتعريف التّبعية بالصمت تشويه لها لأن التّبعية الفعّالة مشاركة نشطة ومسؤولة. المعلومة المفتاحية: خفض تدرّج السلطة يجعل التنبيه للخطر واجبًا لا تجاوزًا.', 'The junior paramedic has done exactly what safe practice demands: team members should speak up about safety concerns regardless of rank, because the person who sees the deterioration is the person who must report it. Saying the authority gradient should prevent questioning describes the very hazard that safe teams work to flatten, claiming only the leader can assess the patient wastes every other pair of eyes, and defining followership as remaining silent is the dangerous misconception that costs patients their lives. Key point: a steep authority gradient must be flattened so any member can raise a safety concern.', 'يلاحظ مسعف مبتدئ أن حالة المريض تتدهور، ولا ينتبه قائد الفريق إلى هذا التغيّر. يبلّغ المسعف المبتدئ عن الملاحظة باحترام. أي مبدأ هو الأهم هنا؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 51, 'A team has clear roles but members stop sharing information with one another. The patient''s condition changes, but only one provider knows about it. Which teamwork component is missing?', '["Shared situation awareness","Technical skill","Equipment management","Team formation"]'::jsonb, 0, 'المعلومة الحرجة محصورة في رأس شخص واحد ولم تصل إلى بقية الفريق، وهذا انعدام للوعي الظرفي المشترك. أما المهارة التقنية فلا يشير النص إلى قصور فيها، وإدارة المعدات ليست موضوع المشهد أصلًا، وتكوين الفريق سليم بدليل وضوح الأدوار المذكور صراحة. المعلومة المفتاحية: وضوح الأدوار وحده لا يكفي، فالوعي المشترك يحتاج تبادلًا مستمرًا للمعلومات.', 'Roles are clear but information has stopped flowing, so only one provider knows the patient has changed — the missing element is shared situation awareness. Technical skill and equipment management concern procedures and kit rather than the team''s common mental picture, and team formation is intact because roles were successfully assigned. Key point: shared situation awareness requires active information sharing, and clear roles alone do not create it.', 'فريق لديه أدوار واضحة لكن أعضاءه توقفوا عن تبادل المعلومات فيما بينهم. تتغيّر حالة المريض، لكن مقدّم رعاية واحدًا فقط يعلم بذلك. أي مكوّن من مكوّنات العمل الجماعي مفقود؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 52, 'A patient has altered mental status, RR 8/min, poor respiratory effort, and SpO₂ 75%. A paramedic decides to obtain a complete medical history before addressing breathing. What is the PRIMARY error?', '["Failure to prioritize an immediate life threat","Excessive delegation","Effective clinical reasoning","Appropriate reassessment"]'::jsonb, 0, 'التنفس البطيء الضعيف مع تشبّع خمسة وسبعين بالمئة فشل تنفسي وشيك يوجب تدخلًا فوريًا، وتأجيله لجمع التاريخ المرضي إخفاق في ترتيب الأولويات. أما الإفراط في التفويض فلا وجود له في النص، ووصف السلوك باستدلال فعّال أو إعادة تقييم مناسبة معكوس تمامًا لأن ما جرى كان تأخيرًا خطيرًا للعلاج. المعلومة المفتاحية: التاريخ المرضي ينتظر، أما التنفس فلا ينتظر.', 'A respiratory rate of 8 with poor effort and a saturation of 75 percent is an immediate life threat, so taking a full history first is a failure to prioritise an immediate life threat. Excessive delegation is not described in the scenario, effective clinical reasoning and appropriate reassessment are both positive labels that plainly do not fit an action that leaves the patient hypoxic. Key point: breathing failure is treated before history is taken — life threats always outrank data gathering.', 'مريض لديه تغيّر في الحالة العقلية، ومعدل تنفس ثمانية في الدقيقة، وجهد تنفسي ضعيف، وتشبّع أكسجين خمسة وسبعين بالمئة. يقرّر مسعف الحصول على تاريخ مرضي كامل قبل معالجة التنفس. ما الخطأ الأساسي؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 53, 'During a resuscitation, the team leader correctly assigns roles. However, the leader becomes focused on medication administration and fails to notice that the patient''s oxygen saturation is falling. Another team member notices but remains silent because the leader is more experienced. What are the TWO major teamwork problems?', '["Poor technical skills and poor documentation","Loss of situation awareness and authority gradient","Effective leadership and followership","Appropriate delegation and communication"]'::jsonb, 1, 'المشكلة الأولى انشغال القائد بمهمة واحدة حتى فقد الصورة الشاملة، والثانية صمت العضو بسبب فارق الخبرة، أي فقدان الوعي الظرفي وتدرّج السلطة معًا. أما ضعف المهارات التقنية والتوثيق فلا يرد لهما ذكر في النص، ووصف الموقف بقيادة وتّبعية فعّالتين أو تفويض وتواصل مناسبين معكوس لأن النتيجة كانت خطرًا غير مُبلَّغ عنه. المعلومة المفتاحية: القائد المنشغل يفقد النظرة الشاملة، وتدرّج السلطة يُسكت من يرى الخطر.', 'Two failures overlap: the leader has fixed on medication and missed the falling saturation, which is loss of situation awareness, and the other member stays silent because the leader is senior, which is an authority gradient. Poor technical skills and poor documentation are not described anywhere in the scenario, and describing this as effective leadership and followership or as appropriate delegation and communication contradicts the fact that a critical finding went unreported. Key point: a distracted leader plus a silenced junior is the combination of lost situation awareness and a steep authority gradient.', 'أثناء الإنعاش، يوزّع قائد الفريق الأدوار بشكل صحيح. لكنه ينشغل بإعطاء الدواء ويفشل في ملاحظة انخفاض تشبّع الأكسجين لدى المريض. يلاحظ عضو آخر ذلك لكنه يبقى صامتًا لأن القائد أكثر خبرة. ما المشكلتان الكبيرتان في العمل الجماعي؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 54, 'A patient with chest pain has diaphoresis, nausea, pallor, tachycardia, and ST-segment changes. The paramedic initially assumes anxiety because the patient says, "I feel very nervous." Which approach would BEST prevent a cognitive error?', '["Focus only on the patient''s emotional state","Use all clinical findings together and consider alternative explanations","Ignore the ECG","Accept the first diagnosis"]'::jsonb, 1, 'الوقاية من الخطأ المعرفي تكون بقراءة الموجودات مجتمعة والانفتاح على تفسيرات بديلة بدل الانسياق وراء عبارة قالها المريض. أما التركيز على الحالة الانفعالية وحدها فيكرّس الانحياز نفسه، وتجاهل تخطيط القلب يُسقط الدليل الأقوى، وقبول التشخيص الأول هو التثبيت المعرفي الذي نحاول تفاديه. المعلومة المفتاحية: النظر في تفسير بديل واحد على الأقل هو أبسط حماية من الأخطاء التشخيصية.', 'Diaphoresis, nausea, pallor, tachycardia and ST-segment changes must be weighed together, and alternative explanations considered, so that the patient''s own word nervous does not anchor the diagnosis on anxiety. Focusing only on the emotional state ignores every objective finding, ignoring the ECG discards the decisive evidence, and accepting the first diagnosis is the anchoring error itself. Key point: guard against anchoring by interpreting all findings together and deliberately considering alternatives.', 'مريض يعاني ألمًا صدريًا مع تعرّق غزير وغثيان وشحوب وتسرّع قلب وتغيّرات في مقطع الضغط. يفترض المسعف في البداية أنها حالة قلق لأن المريض يقول: أشعر بتوتر شديد. أي نهج يمنع الخطأ المعرفي على أفضل وجه؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 55, 'During a major trauma, the team is exposed to noise, multiple casualties, limited resources, and incomplete information. The leader notices that team members are becoming confused about their tasks. What should the leader do FIRST?', '["Allow everyone to continue independently","Re-establish priorities, roles, and communication","Stop all treatment","Leave decision-making to the least experienced provider"]'::jsonb, 1, 'حين يتشوّش الفريق حول مهامه فالخطوة الأولى إعادة ضبط الأولويات والأدوار وقنوات التواصل لاستعادة التنظيم. أما السماح للجميع بالاستمرار بشكل مستقل فيعمّق الفوضى، وإيقاف كل العلاج يضرّ المصابين بلا مبرر، وترك القرار لأقل الأعضاء خبرة تنازل غير مسؤول عن دور القيادة في أشد اللحظات حاجة إليها. المعلومة المفتاحية: عند فقدان السيطرة يعود القائد إلى الأساسيات: أولويات، وأدوار، وتواصل.', 'When noise, casualties and incomplete information leave members confused about their tasks, the leader''s first move is to re-establish priorities, roles and communication so the team regains a common structure. Allowing everyone to continue independently deepens the confusion, stopping all treatment abandons the patients, and leaving decision-making to the least experienced provider removes leadership at the moment it is most needed. Key point: when a team loses coherence, the leader restores priorities, roles and communication first.', 'أثناء إصابة كبرى، يتعرّض الفريق للضجيج وتعدّد المصابين ومحدودية الموارد ونقص المعلومات. يلاحظ القائد أن أعضاء الفريق أصبحوا مشوّشين بشأن مهامهم. ماذا ينبغي أن يفعل القائد أولًا؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 56, 'A patient initially has severe respiratory distress. After treatment, SpO₂ improves from 78% to 96%, but the patient becomes hypotensive and confused. Which response BEST demonstrates the paramedic thinking cycle?', '["\"The oxygen improved, so treatment is finished.\"","Reevaluate the patient, recognize the new threat, and revise the plan","Continue the same intervention without reassessment","Disregard the mental-status change"]'::jsonb, 1, 'دورة تفكير المسعف حلقة متصلة من تقييم فتدخل فإعادة تقييم فتعديل، وهو ما يجسّده التعرف على التهديد الجديد ومراجعة الخطة. أما اعتبار العلاج منتهيًا بتحسّن الأكسجين فتجاهل لتدهور جديد، والاستمرار على التدخل نفسه دون إعادة تقييم يجمّد الخطة أمام واقع متغيّر، وتجاهل تغيّر الحالة العقلية إسقاط لعلامة إنذار خطيرة. المعلومة المفتاحية: تحسّن مؤشر واحد لا يعني تحسّن المريض، والدورة لا تُغلق قبل تسليمه.', 'The thinking cycle is assess, interpret, act, reassess, so the correct response is to reevaluate the patient, recognise the new threat of hypotension and confusion, and revise the plan. Concluding that treatment is finished because oxygen improved stops the cycle halfway, continuing the same intervention without reassessment ignores the change, and disregarding the mental-status change discards the most alarming new finding. Key point: partial improvement never ends the cycle — a new abnormal finding restarts assessment and replanning.', 'مريض لديه في البداية ضائقة تنفسية شديدة. بعد العلاج يتحسّن تشبّع الأكسجين من ثمانية وسبعين إلى ستة وتسعين بالمئة، لكن المريض يصاب بانخفاض في ضغط الدم وتشوّش. أي استجابة تُظهر دورة تفكير المسعف على أفضل وجه؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 57, 'A paramedic receives conflicting information from the patient, family, and monitor. What is the BEST approach?', '["Automatically believe the family","Automatically believe the patient","Evaluate the reliability and consistency of each source against clinical findings","Ignore all information"]'::jsonb, 2, 'عند تضارب المصادر يوزن كل مصدر بمدى موثوقيته واتساقه مع ما تُظهره الموجودات السريرية، فهذا هو النهج النقدي السليم. أما تصديق العائلة أو المريض تلقائيًا فتفضيل اعتباطي لمصدر على آخر، وتجاهل جميع المعلومات يحرم المسعف من معطيات قد تكون حاسمة كآلية الإصابة أو الأدوية المستعملة. المعلومة المفتاحية: الموجودات السريرية الموضوعية هي المرجّح عند تضارب الروايات.', 'When patient, family and monitor disagree, the paramedic evaluates the reliability and consistency of each source against the clinical findings, letting objective evidence arbitrate. Automatically believing the family or automatically believing the patient substitutes trust for verification, and ignoring all information throws away data that may be partly accurate. Key point: conflicting sources are resolved by cross-checking each against objective clinical findings.', 'يتلقى مسعف معلومات متضاربة من المريض والعائلة وجهاز المراقبة. ما النهج الأفضل؟', '{}'::jsonb, 'التفكير النقدي والاستدلال السريري', false, false, false),
  ((select id from s), 58, 'During a cardiac arrest, the team leader asks the airway provider for an update. The airway provider reports worsening ventilation. At the same time, the nurse reports that the last medication was given. The leader changes priorities based on both reports. What does this BEST demonstrate?', '["Individual performance","Shared situation awareness and adaptive decision-making","Anchoring","Storming"]'::jsonb, 1, 'تدفق المعلومات من عدة أعضاء إلى القائد ثم تعديله للأولويات بناءً عليها يجمع بين الوعي الظرفي المشترك وصنع القرار التكيّفي. أما الأداء الفردي فمعكوس لأن المشهد تعاوني بامتياز، والتثبيت على المعلومة الأولى نقيض ما جرى لأن القائد غيّر خطته، والخلاف مرحلة صراع لا أثر لها في فريق منسجم كهذا. المعلومة المفتاحية: مشاركة المعلومات ثم تعديل الأولويات بناءً عليها هي ذروة أداء الفريق الفعّال.', 'The leader pulls updates from the airway provider and the nurse, builds one common picture, and changes priorities accordingly — that is shared situation awareness combined with adaptive decision-making. Individual performance describes someone working alone rather than integrating reports, anchoring would mean refusing to change despite the new information, and storming is a conflict stage of team development that is absent here. Key point: gathering updates from every role and adjusting the plan is shared situation awareness in action.', 'أثناء توقّف القلب، يطلب قائد الفريق تحديثًا من المسؤول عن المجرى الهوائي. يبلّغ المسؤول عن المجرى الهوائي بتدهور التهوية. وفي الوقت نفسه تبلّغ الممرضة بأن آخر جرعة دواء قد أُعطيت. يغيّر القائد الأولويات بناءً على كلا التقريرين. ما الذي يوضّحه هذا على أفضل وجه؟', '{}'::jsonb, 'العمل الجماعي ومراحل تكوين الفريق', false, false, false),
  ((select id from s), 59, 'A paramedic arrives at an unsafe scene with an unstable patient. The patient''s family demands immediate treatment, while the paramedic recognizes an environmental hazard. Which principle should guide the paramedic''s decision?', '["Ignore the environment because patient treatment always comes first","Consider scene safety while prioritizing the patient''s immediate threats","Allow the family to determine the treatment","Begin treatment without assessing hazards"]'::jsonb, 1, 'السلامة وعلاج المريض ليسا خيارين متعارضين، بل يوازن المسعف بينهما فيؤمّن الموقع ويعالج تهديدات الحياة الفورية معًا. أما تجاهل البيئة فيعرّض الفريق والمريض لخطر إضافي، والسماح للعائلة بتحديد العلاج تنازل عن المسؤولية السريرية لغير المختص، وبدء العلاج دون تقييم المخاطر تكرار للخطأ نفسه بصيغة أخرى. المعلومة المفتاحية: مسعف مصاب لا ينقذ أحدًا، لذا تُدمج سلامة الموقع في ترتيب الأولويات لا تُلغى.', 'Scene safety and patient care are not opposing choices: the paramedic must consider scene safety while prioritising the patient''s immediate threats, because an injured crew helps nobody. Ignoring the environment because treatment always comes first risks becoming a casualty, allowing the family to determine the treatment hands clinical decisions to untrained people, and beginning treatment without assessing hazards is the same error stated differently. Key point: balance hazard control with patient priorities — safety and treatment are managed together, not traded off.', 'يصل مسعف إلى موقع غير آمن فيه مريض غير مستقر. تطالب عائلة المريض بعلاج فوري، بينما يلاحظ المسعف وجود خطر بيئي. أي مبدأ ينبغي أن يوجّه قرار المسعف؟', '{}'::jsonb, 'القيادة والتّبعية وأولويات التدخل', false, false, false),
  ((select id from s), 60, 'A team leader delegates airway management to an inexperienced provider who is already overloaded with another critical task. The patient''s respiratory status deteriorates. Which factor in delegation was MOST clearly ignored?', '["Competency and workload","Patient identity","Handover structure","Documentation format"]'::jsonb, 0, 'التفويض الآمن يشترط أن يكون المكلَّف مؤهلًا للمهمة وقادرًا على استيعابها ضمن عبئه الحالي، وقد انتُهك الشرطان معًا هنا. أما هوية المريض فمسألة تحقق من الشخص لا معيار لاختيار المنفّذ، وبنية التسليم تخص نقل المريض بين الفرق، وصيغة التوثيق مسألة إدارية لا صلة لها بتدهور التهوية. المعلومة المفتاحية: قبل تفويض أي مهمة حرجة اسأل عن كفاءة المكلَّف وعن حجم ما بين يديه أصلًا.', 'Handing critical airway management to an inexperienced provider who is already saturated with another task ignores the two core criteria of delegation: competency and workload. Patient identity matters for drug and procedure safety rather than task allocation, handover structure concerns transferring care between providers, and documentation format is an administrative issue with no bearing on who should have received the task. Key point: delegate according to the provider''s competence and current workload.', 'يفوّض قائد فريق إدارة المجرى الهوائي إلى مقدّم رعاية قليل الخبرة ومُثقل أصلًا بمهمة حرجة أخرى. تتدهور الحالة التنفسية للمريض. أي عامل في التفويض جرى تجاهله بشكل أوضح؟', '{}'::jsonb, 'التواصل والتفويض', false, false, false);
  insert into amusq.subjects (name, color, icon, descr, topics, exam_date, published, free, ord)
insert into amusq.questions
  (subject_id, ord, q, options, answer, expl_ar, expl_en, translation, mnemonic, topic, derived, opts_built, important)
values
  ((select id from s), 1, 'When is it safe for a paramedic to enter the Hot Zone?', '["With Level C PPE","After scene declared safe","With proper Level A or B PPE and training","Never"]'::jsonb, 2, 'المنطقة الساخنة هي منطقة التلوث المباشر، ولا يدخلها إلا شخص مدرَّب على المستوى المطلوب ويرتدي وقاية من المستوى A أو B التي توفّر حماية تنفسية بجهاز تنفس مكتفٍ ذاتياً مع حاجز كيميائي للجلد. المستوى C يعتمد على كمامة منقّية للهواء ولا يُستخدم إلا حين يكون الملوّث معروفاً وتركيزه ضمن الحدود والأكسجين كافٍ، لذلك لا يكفي للمنطقة الساخنة. وخيار «بعد إعلان أن الموقع آمن» غير صحيح لأن المنطقة الساخنة تبقى ملوّثة بحكم تعريفها. وخيار «لا يجوز أبداً» مبالغة، فالدخول مسموح للمؤهلين المدرَّبين ضمن نظام إدارة الحادث. المعلومة المفتاحية: دخول المنطقة الساخنة = تدريب مناسب + وقاية من المستوى A أو B.', 'The Hot Zone is the area of active contamination, so entry requires both appropriate training and Level A or B PPE, which provide SCBA-based respiratory protection plus a chemical barrier. Level C relies on an air-purifying respirator and is acceptable only when the contaminant and its concentration are known and oxygen is adequate, so it is inadequate for the Hot Zone. "After scene declared safe" is wrong because the Hot Zone is by definition still contaminated. "Never" is an overstatement, since properly trained and protected responders do enter. Takeaway: Hot Zone entry = correct training plus Level A or B PPE.', 'متى يكون من الآمن للمسعف أن يدخل المنطقة الساخنة (Hot Zone)؟', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 2, 'What is a common symptom of cyanide exposure?', '["Headache, confusion, shortness of breath","Skin rash","Burns","Sneezing"]'::jsonb, 0, 'السيانيد يمنع الخلايا من استخدام الأكسجين بتثبيط إنزيم سيتوكروم أوكسيديز، فيحدث اختناق خلوي تظهر أعراضه على الأعضاء الأكثر استهلاكاً للأكسجين: الدماغ والجهاز التنفسي، فيشكو المصاب من صداع وتشوّش ودوخة وضيق نفس ثم تدهور وعي وتشنجات. الطفح الجلدي والحروق أعراض تلامسية موضعية تخصّ المواد الكاوية أو الحارقة لا السيانيد الجهازي. والعطاس مجرد تهيّج بسيط في الطرق التنفسية العلوية يوحي بمهيّج خفيف لا بسمّ خلوي قاتل. المعلومة المفتاحية: السيانيد = اختناق خلوي بأعراض عصبية وتنفسية رغم وجود أكسجين كافٍ في الهواء.', 'Cyanide blocks cytochrome oxidase, so cells cannot use oxygen and the organs with the highest oxygen demand fail first, producing headache, confusion, dizziness and dyspnea before seizures and collapse. Skin rash and burns are local contact effects typical of caustics or thermal agents, not of systemic cyanide poisoning. Sneezing reflects mild upper-airway irritation and would suggest a simple irritant rather than a cellular asphyxiant. Takeaway: cyanide causes cellular asphyxia, so think neurologic and respiratory symptoms despite adequate ambient oxygen.', 'ما العَرَض الشائع للتعرّض لمادة السيانيد؟', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 3, 'Flammable liquid spill—best method to control ignition sources:', '["Douse with water","Remove spark sources and ventilate","Cover with blankets","Wait"]'::jsonb, 1, 'الأبخرة المتصاعدة من السائل القابل للاشتعال هي الخطر الحقيقي، وهي تشتعل عند أي شرارة، لذلك تكون السيطرة بإبعاد كل مصادر الإشعال (المحركات، المفاتيح الكهربائية، الهواتف، اللهب المكشوف) وتهوية المكان لخفض تركيز البخار تحت الحد الأدنى للاشتعال. غمر المكان بالماء لا يزيل الشرارة، بل قد ينشر السائل ويوسّع رقعة الخطر لأن كثيراً من هذه السوائل لا تمتزج بالماء. والتغطية بالبطانيات لا تحبس الأبخرة ولا تمنع الشرر بل قد تشتعل هي نفسها. والانتظار السلبي يترك البخار يتراكم حتى يصل إلى مصدر إشعال. المعلومة المفتاحية: السيطرة على الحريق قبل وقوعه = قطع مصادر الإشعال + تهوية لخفض تركيز الأبخرة.', 'With a flammable liquid the vapor is the hazard, and it ignites from any spark, so control means eliminating ignition sources (engines, switches, phones, open flame) and ventilating to keep vapor below the lower flammable limit. Dousing with water does not remove a spark and can spread a non-water-miscible liquid, enlarging the hazard area. Covering with blankets neither contains vapor nor removes ignition sources and the blanket itself may ignite. Simply waiting allows vapor to accumulate until it finds an ignition source. Takeaway: prevent ignition by removing spark sources and ventilating the vapor away.', 'انسكاب سائل قابل للاشتعال — ما أفضل طريقة للسيطرة على مصادر الإشعال؟', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 4, 'HAZMAT awareness-level paramedic may:', '["Recognize hazards, call for specialized help","Enter Hot Zone","Mitigate chemical release","Operate containment equipment"]'::jsonb, 0, 'مستوى الوعي هو أدنى مستويات التأهّل في المواد الخطرة، ودوره دفاعي بحت: التعرّف على وجود مادة خطرة، وقراءة اللافتات وأرقام الأمم المتحدة ودليل الاستجابة الطارئة، والعزل والإبلاغ وطلب الفريق المتخصص من مسافة آمنة. دخول المنطقة الساخنة يحتاج مستوى فنّي/متخصص مع وقاية عالية، لذلك هو خارج صلاحياته. ومعالجة التسرّب وإيقافه عمل هجومي يتطلب مستوى الفنّي المتخصص. وتشغيل معدات الاحتواء كذلك يحتاج تدريباً تشغيلياً وفنّياً متقدماً. المعلومة المفتاحية: مستوى الوعي = «تعرّف، اعزل، أبلغ» — لا تقترب ولا تتدخّل.', 'Awareness level is the lowest HAZMAT competency and is purely defensive: recognize that a hazardous material is present, use placards, UN numbers and the ERG, isolate, notify and summon a specialized team from a safe distance. Entering the Hot Zone requires technician-level training with high-level PPE and is outside this scope. Mitigating a chemical release is an offensive action reserved for HAZMAT technicians. Operating containment equipment likewise demands advanced operations or technician training. Takeaway: awareness level means recognize, isolate and call for help, never approach or intervene.', 'المسعف المؤهَّل بمستوى «الوعي/الإدراك» (Awareness) في المواد الخطرة يستطيع أن:', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 5, 'Emergency medical care priority for chemical exposure:', '["Remove from source → Decontaminate → Treat symptoms","Decontaminate → Treat → Remove from source","Treat symptoms → Remove from source → Decontaminate","Remove source only"]'::jsonb, 0, 'أول خطوة هي إخراج المصاب من بيئة التعرّض لإيقاف استمرار امتصاص المادة، ثم إزالة التلوث بخلع الملابس والغسل لأن المصاب الملوَّث يظل يتسمّم ويلوّث المسعفين والسيارة والمستشفى، وبعدها فقط يُعالَج علاجاً عرضياً وداعماً. الخيار الذي يبدأ بإزالة التلوث خطأ لأنه يترك المصاب داخل مصدر الخطر. والخيار الذي يبدأ بعلاج الأعراض أخطر، فهو يعرّض الفريق للتلوث ويؤخّر إيقاف التعرّض. و«إزالة المصدر فقط» ناقص لأنه يهمل إزالة التلوث والعلاج. المعلومة المفتاحية: أبعِد عن المصدر أولاً، ثم أزل التلوث، ثم عالج — ولا علاج نهائي قبل إزالة التلوث.', 'The first step is removing the patient from the exposure so absorption stops, then decontamination by disrobing and washing, because a contaminated patient keeps absorbing the agent and contaminates crew, ambulance and hospital; only then is symptomatic and supportive care given. Starting with decontamination is wrong because it leaves the patient inside the hazard. Starting with treatment is the most dangerous option, exposing the crew and delaying removal from the source. "Remove source only" is incomplete since it omits decontamination and care. Takeaway: remove from source, then decontaminate, then treat.', 'ترتيب أولويات الرعاية الطبية الطارئة في حالة التعرّض الكيميائي:', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 6, 'Best method to prevent inhalation during chemical exposure:', '["Hold breath","Use air-purifying respirator or SCBA","Cover mouth with shirt","Quick exit only"]'::jsonb, 1, 'الحماية التنفسية الحقيقية تكون بجهاز يفصل الجهاز التنفسي عن الجو الملوّث أو ينقّي الهواء الداخل، أي كمامة منقّية للهواء في الأجواء المعروفة وكافية الأكسجين، أو جهاز تنفس مكتفٍ ذاتياً في الأجواء المجهولة أو ناقصة الأكسجين. حبس النفس إجراء يدوم ثوانٍ ولا يمكن الاعتماد عليه ويفشل تماماً مع أي جهد أو تأخير. وتغطية الفم بالقميص لا توفّر أي ترشيح للغازات ولا إحكاماً حول الوجه. والخروج السريع مهم لكنه لا يحمي أثناء الخروج نفسه ولا يغني عن الوقاية. المعلومة المفتاحية: منع الاستنشاق = حماية تنفسية معتمدة (APR أو SCBA)، وما دونها وهم حماية.', 'Real respiratory protection means a device that either isolates the airway from the contaminated atmosphere or filters the air entering it: an air-purifying respirator where the contaminant is known and oxygen is adequate, or SCBA in unknown or oxygen-deficient atmospheres. Holding your breath lasts seconds and fails with any exertion or delay. A shirt over the mouth filters no gases and provides no face seal. A quick exit matters but offers no protection during the exit itself. Takeaway: only certified respiratory protection, APR or SCBA, actually prevents inhalation.', 'أفضل وسيلة لمنع الاستنشاق أثناء التعرّض الكيميائي:', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 7, 'Which rescue phase is MOST associated with cribbing and chocking?', '["Stabilization","Transport","Recovery","Access"]'::jsonb, 0, 'التدعيم بالأخشاب وتثبيت العجلات إجراءان هدفهما منع أي حركة للمركبة أو الحطام، وهذا هو جوهر مرحلة التثبيت التي تسبق الوصول إلى المصاب وتحميه هو والفريق من انهيار أو انزلاق مفاجئ. مرحلة النقل تأتي بعد إخراج المصاب ولا علاقة لها بتدعيم الهيكل. ومرحلة الاسترجاع تعني في العادة انتشال المتوفين أو استعادة المعدات بعد انتهاء الإنقاذ. ومرحلة الوصول هي فتح مسار للوصول للمصاب، وهي لا تبدأ أصلاً إلا بعد أن يكون المشهد مثبَّتاً. المعلومة المفتاحية: أي كلمة تعني منع الحركة (cribbing / chocking / shoring) تنتمي إلى مرحلة التثبيت.', 'Cribbing and chocking exist to eliminate any movement of the vehicle or debris, which is the definition of the stabilization phase that precedes patient access and protects both patient and crew from sudden shifting or collapse. Transport occurs after the patient is freed and has nothing to do with securing the structure. Recovery usually refers to removing deceased victims or retrieving equipment once rescue is over. Access is about creating a path to the patient, and it should not begin until the scene is already stabilized. Takeaway: anything that stops movement, cribbing, chocking or shoring, belongs to stabilization.', 'أي مرحلة من مراحل الإنقاذ ترتبط أكثر ما يكون بالتدعيم بالأخشاب (cribbing) وتثبيت العجلات (chocking)؟', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 8, 'In technical rescue incidents, atmospheric monitoring is especially important during:', '["Confined space access","Patient transport","Documentation","Recovery only"]'::jsonb, 0, 'الأماكن المحصورة كالخزانات والصهاريج وغرف الصرف الصحي معرّضة لنقص الأكسجين وتراكم الغازات السامة أو القابلة للاشتعال، ولذلك يُلزم قياس نسبة الأكسجين والغازات القابلة للاشتعال والغازات السامة قبل الدخول وباستمرار أثناءه. نقل المريض يتم في بيئة مفتوحة أو داخل سيارة الإسعاف ولا يحمل هذا الخطر الجوي. والتوثيق عمل إداري لا صلة له بجوّ الموقع. وحصر المراقبة في مرحلة الاسترجاع خطأ لأن الخطر الأكبر يقع لحظة الدخول الأول لا بعده. المعلومة المفتاحية: لا دخول لمكان محصور قبل قياس الجو — أغلب وفيات الأماكن المحصورة تقع في المنقذين غير المستعدين.', 'Confined spaces such as tanks, silos and sewers are prone to oxygen deficiency and to accumulation of toxic or flammable gases, so oxygen, flammability and toxicity must be measured before entry and monitored continuously during it. Patient transport happens in open air or in the ambulance and carries no such atmospheric hazard. Documentation is administrative and unrelated to scene atmosphere. Limiting monitoring to recovery is wrong because the greatest risk occurs at the moment of initial entry. Takeaway: never enter a confined space without atmospheric monitoring, since most confined-space deaths are unprepared rescuers.', 'في حوادث الإنقاذ الفني، تزداد أهمية مراقبة الغلاف الجوي (atmospheric monitoring) بشكل خاص أثناء:', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 9, 'What is the MAIN purpose of the disentanglement phase?', '["Provide medications","Remove obstacles trapping the patient","Contact family members","Complete triage tags"]'::jsonb, 1, 'فكّ الاحتجاز يعني إزاحة المعدن والحطام والأجزاء التي تُطبِق على المصاب أو تحيط به، أي أننا نحرّك الحطام عن المريض لا المريض عن الحطام، تمهيداً لإخراجه دون زيادة إصاباته. إعطاء الأدوية جزء من الرعاية الطبية التي قد تجري بالتوازي لكنها ليست غرض المرحلة. والتواصل مع العائلة شأن تنظيمي لاحق لا علاقة له بتحرير المصاب. وبطاقات الفرز تخص تصنيف المصابين في الحوادث الجماعية وليست هدف فكّ الاحتجاز. المعلومة المفتاحية: في فكّ الاحتجاز نزيل السيارة عن المريض، ولا ننتزع المريض من السيارة.', 'Disentanglement means cutting and displacing the metal, debris and structure that pin or surround the patient, so the vehicle is removed from the patient rather than the patient dragged from the vehicle, preparing for a controlled extrication. Giving medications is part of concurrent medical care, not the purpose of this phase. Contacting family is an administrative task unrelated to freeing the patient. Triage tagging belongs to sorting casualties in a mass-casualty incident. Takeaway: disentanglement removes the wreckage from the patient, never the patient from the wreckage.', 'ما الهدف الرئيسي من مرحلة فكّ الاحتجاز (Disentanglement)؟', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 10, 'Scene lighting is MOST important during:', '["Night operations access and extrication","Transport only","Recovery only","Dispatch communication"]'::jsonb, 0, 'الإضاءة الجيدة ضرورة سلامة أثناء العمل الليلي: فهي تكشف المخاطر كالزجاج والوقود المنسكب والكابلات، وتتيح استخدام أدوات القص والفتح بأمان، وتجعل الفريق مرئياً لحركة المرور المارّة. النقل يتم في بيئة مضاءة داخل سيارة الإسعاف، فليس هو أشد المراحل حاجة للإضاءة. وحصرها في مرحلة الاسترجاع يتجاهل أخطر مرحلة وهي العمل بالأدوات حول المركبة. والاتصال مع غرفة العمليات لا يحتاج إضاءة أصلاً. المعلومة المفتاحية: الإضاءة معدّة سلامة وليست وسيلة راحة، وذروة الحاجة إليها عند الوصول والاستخلاص ليلاً.', 'Adequate lighting is a safety requirement for night work: it reveals hazards such as glass, spilled fuel and downed wires, allows safe use of cutting and spreading tools, and makes the crew visible to passing traffic. Transport takes place in the lit ambulance compartment and is not the most lighting-dependent phase. Restricting it to recovery ignores the highest-risk activity, tool work around the vehicle. Radio communication with dispatch needs no illumination at all. Takeaway: scene lighting is safety equipment, and the peak need is night-time access and extrication.', 'إضاءة موقع الحادث تكون أكثر ما تكون أهمية أثناء:', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 11, 'During which phase should spinal precautions be maintained?', '["Extrication and transfer","Documentation only","Recovery phase only","Scene termination only"]'::jsonb, 0, 'احتياطات العمود الفقري تلزم في كل لحظة يتحرك فيها المصاب فعلياً، أي أثناء الاستخلاص من المركبة ونقله إلى اللوح والنقالة ثم إلى سيارة الإسعاف، لأن أي حركة غير مضبوطة قد تحوّل كسراً فقرياً مستقراً إلى أذى نخاعي دائم. لذلك يُثبَّت الرأس يدوياً على المحور الطولي وتُستخدم الياقة والتدحرج المنسّق أو اللوح القصير من أول لمسة حتى تسليم المريض. «التوثيق فقط» خطأ لأن الكتابة لا تحرّك المصاب أصلاً. و«مرحلة الاسترجاع فقط» تخص انتشال المتوفين والمعدات، و«إنهاء العمل في الموقع فقط» يأتي بعد أن يكون المريض قد غادر. المعلومة المفتاحية: تثبيت العمود الفقري يرافق كل حركة للمصاب — من الاستخلاص حتى التسليم.', 'Spinal precautions apply whenever the patient is actually being moved, which means during extrication from the vehicle and transfer to the board, stretcher and ambulance, because uncontrolled movement can convert a stable vertebral fracture into permanent cord injury. Manual in-line stabilization, a collar and a coordinated log roll or short board are maintained from first contact until handoff. "Documentation only" is wrong because paperwork never moves the patient. "Recovery phase only" refers to removing deceased victims and equipment, and "Scene termination only" occurs after the patient has already left. Takeaway: spinal precautions accompany every phase in which the patient is moved, above all extrication and transfer.', 'خلال أي مرحلة يجب الحفاظ على احتياطات العمود الفقري؟', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 12, 'The phase involving patient handoff to hospital staff is:', '["Stabilization","Transfer and transport","Recovery","Access"]'::jsonb, 1, 'مرحلة التسليم والنقل هي الحلقة الأخيرة في سلسلة الإنقاذ، وفيها يُنقل المريض إلى سيارة الإسعاف ثم إلى المنشأة المناسبة ويُسلَّم إلى الطاقم المستقبِل مع تقرير شفهي منظّم عن آلية الإصابة والفحص والعلاج المُعطى. التثبيت مرحلة سابقة تخص منع حركة المركبة أو الحطام قبل الاقتراب من المصاب. والاسترجاع يعني عادةً انتشال المتوفين أو استعادة المعدات بعد انتهاء الإنقاذ الحقيقي. والوصول هو فتح مسار مادي للوصول إلى المريض داخل الحطام، وهو يسبق إخراجه لا يليه. المعلومة المفتاحية: تسليم المريض لطاقم المستشفى يقع في مرحلة النقل والتسليم، آخر مراحل عملية الإنقاذ.', 'Transfer and transport is the final link in the rescue chain: the patient is moved to the ambulance, taken to the appropriate facility, and handed over to the receiving team with a structured verbal report covering mechanism, findings and treatment given. Stabilization is an earlier phase concerned with preventing movement of the vehicle or debris before anyone approaches the patient. Recovery normally means retrieving deceased victims or equipment once the rescue itself is over. Access is about creating a physical path to the patient inside the wreckage, which precedes removal rather than following it. Takeaway: handoff to hospital staff belongs to the transfer and transport phase, the last stage of a rescue operation.', 'المرحلة التي تتضمّن تسليم المريض إلى طاقم المستشفى هي:', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 13, 'After-action review and critique occur during:', '["Size-up","Debriefing/termination","Extrication","Access"]'::jsonb, 1, 'المراجعة اللاحقة للعملية تحدث في مرحلة الإحاطة الختامية وإنهاء العملية، بعد إخلاء المصابين وتأمين الموقع، وفيها يُناقش ما سار جيداً وما يحتاج تحسيناً، وتُفحص المعدات وتُعاد وتُستكمل التقارير ويُعرض الدعم النفسي على الفريق عند الحاجة. تقدير الموقف الأولي يكون لحظة الوصول ويهدف إلى تحديد المخاطر والموارد لا إلى النقد. والاستخلاص عمل ميداني نشط لا يحتمل التوقف للمناقشة. والوصول كذلك مرحلة تشغيلية وسط الحادث ينشغل فيها الفريق بفتح مسار للمصاب. المعلومة المفتاحية: النقد والتعلّم يأتيان بعد انتهاء العمل — في الإحاطة الختامية، لا أثناء العملية.', 'After-action review takes place during debriefing and termination, once patients have been evacuated and the scene secured; the team discusses what went well and what needs improvement, equipment is checked and returned, reports are completed and psychological support is offered when needed. Size-up occurs on arrival and exists to identify hazards and resources, not to critique performance. Extrication is active field work that cannot pause for discussion. Access is likewise an operational mid-incident phase in which the crew is busy opening a path to the patient. Takeaway: critique and learning happen after the work is finished, in the debriefing and termination phase.', 'المراجعة والنقد بعد انتهاء العملية (after-action review) يجريان أثناء:', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 14, 'What is the FIRST priority in any water rescue incident?', '["Enter the water immediately","Rescue the victim quickly","Ensure rescuer safety","Start CPR"]'::jsonb, 2, 'القاعدة الثابتة في كل مشهد طوارئ، والمائي منها بوجه خاص، أن سلامة المنقذ تسبق كل شيء، لأن منقذاً يغرق يتحوّل من حل إلى مصاب ثانٍ ويستهلك موارد كانت للضحية. كثير من وفيات الغرق تقع في أشخاص نزلوا الماء بدافع طيب دون تدريب ولا سترة نجاة ولا حبل تأمين. النزول الفوري إلى الماء وإنقاذ الضحية بسرعة خياران يعبّران عن اندفاع لا عن منهج، وكلاهما يخالف ترتيب الأولويات. وبدء الإنعاش القلبي الرئوي رعاية مهمة جداً لكنها تأتي بعد إخراج الضحية إلى سطح صلب آمن. المعلومة المفتاحية: سلامتك أولاً، ثم سلامة الفريق والمارّة، ثم المريض — ولا استثناء في الماء.', 'In every emergency, and especially in water, rescuer safety comes first, because a drowning rescuer stops being the solution and becomes a second patient who consumes the resources meant for the victim. Many drowning deaths occur in well-meaning bystanders who entered the water untrained, without a flotation device and without a safety line. Entering the water immediately or rescuing the victim quickly express urgency rather than method, and both invert the correct order of priorities. Starting CPR is vital care but comes after the victim has been brought onto a safe, solid surface. Takeaway: self, then team and bystanders, then patient, and water rescue is no exception.', 'ما الأولوية الأولى في أي حادث إنقاذ مائي؟', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 15, 'Which principle is commonly taught in water rescue?', '["Swim–Dive–Carry","Reach–Throw–Row–Go","Jump–Pull–Lift","Wade–Run–Dive"]'::jsonb, 1, 'المبدأ المعتمد عالمياً في الإنقاذ المائي هو تدرّج الخطر: ابدأ بمدّ شيء للضحية من اليابسة، فإن لم ينفع فارمِ لها حبلاً أو أداة طفو، فإن لم ينفع فاستخدم قارباً، ولا تنزل بنفسك إلا أخيراً وأنت مدرَّب ومجهَّز. كل خطوة في هذا الترتيب أقل خطراً على المنقذ من التي تليها، والنزول المباشر هو الخيار الأخير لأنه الأخطر. الخيارات الأخرى تبدأ كلها بالسباحة أو الغوص أو القفز، أي تضع أخطر إجراء في المقدمة وتعكس منطق السلامة. وهي أيضاً ليست مصطلحات معتمدة في مناهج الإنقاذ المائي. المعلومة المفتاحية: تسلسل الإنقاذ المائي يبدأ من أبعد نقطة آمنة وينتهي بالنزول للماء كخيار أخير.', 'The universally taught water-rescue principle is a ladder of increasing risk: first extend something to the victim from land, then throw a rope or flotation device, then use a boat, and only as a last resort enter the water yourself, trained and equipped. Each step is less dangerous to the rescuer than the one after it, and swimming to the victim is last precisely because it is the most hazardous. The other options all begin with swimming, diving or jumping, placing the most dangerous action first and inverting the logic of safety. They are also not recognized terminology in any water-rescue curriculum. Takeaway: work from the safest distance inward, and entering the water is always the final option.', 'أي مبدأ يُدرَّس عادةً في الإنقاذ المائي؟', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 16, 'The safest rescue method is usually:', '["Swimming to the victim","Diving underwater","Reaching from shore","Direct contact rescue"]'::jsonb, 2, 'الإنقاذ من الشاطئ بمدّ عصا أو مجداف أو حتى اليد مع ثبات الجسم هو أسلم أشكال الإنقاذ لأن المنقذ يبقى خارج الماء وعلى أرض ثابتة، فلا يتعرّض للتيار ولا لبرودة الماء ولا لتشبّث الضحية. السباحة نحو الضحية والإنقاذ بالتلامس المباشر يضعان المنقذ في متناول ضحية مذعورة قد تدفعه تحت السطح. والغوص تحت الماء هو الأخطر على الإطلاق ويتطلب تدريباً متخصصاً ومعدات وفريق تأمين. لهذا يوضع «مدّ اليد» في أول تسلسل الإنقاذ المائي وتوضع السباحة في آخره. المعلومة المفتاحية: الإنقاذ الأسلم هو ما يبقيك على اليابسة — كلما ابتعدت عن الماء قلّ خطرك.', 'Reaching from shore with a pole, oar or even a braced hand is the safest form of rescue because the rescuer stays out of the water on stable ground, exposed neither to current nor cold nor to the victim''s grasp. Swimming to the victim and direct contact rescue both place the rescuer within reach of a panicking person who may push them under. Diving underwater is the most hazardous of all and demands specialized training, equipment and a safety team. This is exactly why "reach" sits at the start of the water-rescue sequence and swimming sits at the end. Takeaway: the safest rescue is the one that keeps you on dry land.', 'أسلم طريقة للإنقاذ عادةً هي:', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 17, 'A drowning victim who is still conscious may:', '["Quietly wave for help","Instinctively struggle and grab rescuers","Float calmly","Always call loudly for help"]'::jsonb, 1, 'الاستجابة الغريزية للغرق تجعل الضحية الواعية تضرب الماء بذراعيها إلى الأسفل محاولةً رفع فمها فوق السطح، ولا تستطيع التلويح ولا الصياح لأن جهازها التنفسي مشغول بالمحاولة اليائسة للتنفس. وفي هذه الحالة تتشبّث بأي جسم يقترب منها، بما في ذلك المنقذ، وتحاول تسلّقه فتدفعه تحت الماء. لذلك يُمنع الاقتراب المباشر دون تدريب، ويُقدَّم للضحية جسم عائم تمسك به بدل أن تمسك بالمنقذ. الخيارات الأخرى تصف غريقاً هادئاً يلوّح أو يطفو أو ينادي، وهي صورة سينمائية لا تطابق الواقع، وكلمة «دائماً» وحدها تكفي لاستبعاد الخيار الأخير. المعلومة المفتاحية: الغرق صامت وعنيف — الضحية الواعية تتشبّث بالمنقذ ولا تلوّح له.', 'The instinctive drowning response makes a conscious victim press the arms down on the water trying to lift the mouth above the surface; the victim cannot wave or shout because the respiratory system is committed to a desperate attempt to breathe. In this state the victim grabs anything that comes close, including the rescuer, and climbs on them, forcing the rescuer under. That is why untrained direct approach is forbidden and why a flotation object is offered for the victim to hold instead of the rescuer. The other options describe a calm person waving, floating or shouting, which is a cinematic image rather than reality, and the absolute word "Always" alone rules out the last one. Takeaway: drowning is silent and violent, and a conscious victim clings to rescuers rather than signalling them.', 'الغريق الذي ما زال واعياً قد:', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 18, 'Which item is MOST useful when performing a throw rescue?', '["Stethoscope","Oxygen cylinder","Rope or flotation device","Spine board only"]'::jsonb, 2, 'الإنقاذ بالرمي يعني إيصال وسيلة إلى الضحية دون نزول المنقذ إلى الماء، ولذلك تكون الأداة المثالية حبل رمي أو طوق نجاة أو أي جسم عائم تستطيع الضحية التعلّق به ويُسحب بواسطته إلى البر. الحبل يضيف ميزة التحكّم بالمسافة والسحب، وأداة الطفو تحافظ على مجرى هواء الضحية فوق الماء حتى لو أُنهكت. السمّاعة الطبية أداة تقييم لا علاقة لها بالإنقاذ من الماء، وأسطوانة الأكسجين ثقيلة وتُستخدم بعد الإخراج لا أثناءه. واللوح الفقري وحده قد يُستعمل في تثبيت مشتبه بإصابة عمود فقري لكنه ليس أداة الرمي المخصصة ولا يكفي وحده. المعلومة المفتاحية: في مرحلة الرمي نرمي طفواً أو حبلاً — لا معدات طبية.', 'A throw rescue means delivering a means of support to the victim without the rescuer entering the water, so the ideal item is a throw rope, ring buoy or any buoyant object the victim can hold and be pulled ashore with. The rope adds distance and the ability to haul, while the flotation device keeps the victim''s airway above the surface even once exhaustion sets in. A stethoscope is an assessment tool with no role in water rescue, and an oxygen cylinder is heavy and used after removal, not during it. A spine board alone may help immobilize a suspected spinal injury but is not the dedicated throwing device and is not sufficient by itself. Takeaway: in the throw step you throw buoyancy and rope, never medical equipment.', 'أي أداة تكون الأكثر فائدة عند تنفيذ الإنقاذ بالرمي (throw rescue)؟', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 19, 'Hypothermia is MOST likely in:', '["Warm shallow water","Cold water immersion","Dry environments","Indoor swimming pools only"]'::jsonb, 1, 'الماء ينقل الحرارة من الجسم أسرع بكثير من الهواء بالحمل والتوصيل، لذلك يفقد الغاطس في ماء بارد حرارته بسرعة كبيرة وقد يدخل في انخفاض حرارة خلال دقائق حتى لو كان الماء غير متجمد. ويزيد الأمر سوءاً صدمة الماء البارد التي تسبّب شهيقاً لا إرادياً وفرط تهوية وفقد سيطرة عضلية على السباحة. الماء الضحل الدافئ لا يسحب الحرارة بالقدر نفسه، والبيئات الجافة تسبّب انخفاض حرارة أبطأ بكثير ما لم تُضَف رياح وبلل. وحصر الأمر بأحواض السباحة الداخلية خطأ لأنها بيئة مضبوطة الحرارة أصلاً. المعلومة المفتاحية: الماء البارد أسرع سارق للحرارة — كل غريق منتشل من ماء بارد يُعامل كمريض انخفاض حرارة حتى يثبت العكس.', 'Water strips heat from the body far faster than air through conduction and convection, so a person immersed in cold water loses heat rapidly and can become hypothermic within minutes even when the water is well above freezing. Cold-water shock compounds this with an involuntary gasp, hyperventilation and loss of the muscular control needed to swim. Warm shallow water does not draw heat away nearly as fast, and dry environments cause much slower cooling unless wind and wetness are added. Restricting the risk to indoor swimming pools is wrong, since those are temperature-controlled environments. Takeaway: cold water is the fastest thief of body heat, so treat every cold-water victim as hypothermic until proven otherwise.', 'انخفاض حرارة الجسم (Hypothermia) أكثر ما يُحتمل حدوثه في:', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 20, 'In water rescue, spinal injury should be suspected when:', '["The patient was fishing","Diving accidents occurred","The victim can swim","Water is shallow only"]'::jsonb, 1, 'الاشتباه بإصابة العمود الفقري في الماء يقوم على آلية الإصابة، وأوضحها الغطس أو القفز في الماء حيث يصطدم الرأس بالقاع فيتولّد تحميل محوري على الفقرات الرقبية يسبّب كسراً أو خلعاً وقد يؤذي النخاع. لذلك يُثبَّت الرأس والرقبة داخل الماء نفسه قبل رفع الضحية، باستخدام تثبيت يدوي محوري ثم لوح عائم. ممارسة صيد السمك أو إجادة السباحة لا تقولان شيئاً عن الآلية، وقد يسقط سبّاح ماهر دون أي رضّ رقبي. وحصر الاشتباه بالماء الضحل خطأ لأن العمق ليس هو المعيار بل ما حدث للرأس، وإن كان الماء الضحل يزيد احتمال ارتطام القاع. المعلومة المفتاحية: الآلية هي الدليل — كل غطس أو قفز في الماء يُعامل كإصابة رقبية حتى يثبت العكس.', 'Suspicion of spinal injury in water is driven by mechanism, and the classic one is a dive or jump in which the head strikes the bottom, producing axial loading of the cervical spine with fracture or dislocation and possible cord injury. For that reason the head and neck are stabilized in the water itself, with manual in-line stabilization and a floating board, before the victim is lifted. Fishing or being a competent swimmer say nothing about mechanism, and a strong swimmer may collapse without any neck trauma at all. Limiting suspicion to shallow water is wrong because depth is not the criterion, what happened to the head is, even though shallow water does make bottom impact more likely. Takeaway: mechanism decides, so treat every diving or jumping incident as a cervical spine injury until proven otherwise.', 'في الإنقاذ المائي، يجب الاشتباه بإصابة العمود الفقري عندما:', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 21, 'What is the PRIMARY cause of death in drowning?', '["Cardiac arrest first","Air embolism","Respiratory failure from hypoxia","Internal bleeding"]'::jsonb, 2, 'الغرق حدث تنفسي في جوهره: يدخل الماء إلى الطرق الهوائية أو يتشنّج الحنجرة فينقطع تبادل الغازات، فيهبط الأكسجين ويتراكم ثاني أكسيد الكربون حتى يصل نقص الأكسجة إلى الدماغ والقلب. توقّف القلب في الغرق نتيجة لا سبب، إذ يأتي متأخراً بعد فترة من نقص الأكسجين، ولهذا يبدأ إنعاش الغريق بالتهوية والأنفاس الإنقاذية لا بالضغطات وحدها. الانصمام الهوائي يخصّ الغوص بالأسطوانات مع صعود سريع وحبس نفس، وهو حالة خاصة نادرة لا القاعدة العامة. والنزف الداخلي يحتاج آلية رضّية مستقلة ولا يفسّر وفاة الغرق نفسها. المعلومة المفتاحية: الغرق يقتل بنقص الأكسجين أولاً، والقلب يتوقف تالياً لا أولاً.', 'Drowning is fundamentally a respiratory event: water entering the airway or laryngospasm interrupts gas exchange, oxygen falls and carbon dioxide accumulates until hypoxia reaches the brain and the heart. Cardiac arrest in drowning is the consequence rather than the cause, arriving late after a period of hypoxia, which is why drowning resuscitation begins with ventilation and rescue breaths rather than compressions alone. Air embolism belongs to scuba ascent with a closed glottis and is a rare special case, not the general rule. Internal bleeding requires a separate traumatic mechanism and does not explain death from drowning itself. Takeaway: drowning kills through hypoxia first, and the heart stops second, not first.', 'ما السبب الأساسي للوفاة في حالات الغرق؟', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 22, 'Which PPE is ESSENTIAL for swift water rescuers?', '["Surgical gown","Turnout gear","Personal flotation device (PFD)","Face shield only"]'::jsonb, 2, 'أي عمل في المياه الجارية أو قربها يبدأ بأداة طفو شخصية مناسبة ومربوطة بإحكام، لأنها تُبقي مجرى هواء المنقذ فوق السطح حتى لو فقد توازنه أو أُنهك أو سحبه التيار، ويُضاف إليها الخوذة وحزام التحرير السريع وحبل التأمين والحذاء المغلق. الثوب الجراحي حاجز بيولوجي بسيط لا يقدّم أي طفو، وواقي الوجه وحده يحمي من الرذاذ فقط ولا صلة له بخطر الغرق. أما بدلة الإطفاء فهي أسوأ الخيارات في الماء لأنها تمتلئ وتزداد ثقلاً فتسحب لابسها إلى الأسفل. المعلومة المفتاحية: في الماء لا وقاية قبل الطفو — سترة النجاة أول ما يُلبس وآخر ما يُخلع.', 'Any work in or near swift water begins with a properly fitted and fastened personal flotation device, because it keeps the rescuer''s airway above the surface even after a loss of balance, exhaustion or being swept by the current, and it is combined with a helmet, quick-release harness, safety line and closed footwear. A surgical gown is a simple biological barrier that provides no buoyancy, and a face shield alone protects against splash and has nothing to do with drowning risk. Turnout gear is the worst choice in water because it fills, becomes heavy and drags the wearer down. Takeaway: no water PPE counts before buoyancy, so the PFD is the first item on and the last item off.', 'أي معدات وقاية شخصية تُعدّ أساسية لمنقذي المياه الجارية (swift water)؟', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 23, 'A panicking drowning victim may endanger rescuers by:', '["Swimming away","Pulling the rescuer underwater","Refusing assistance","Remaining unconscious"]'::jsonb, 1, 'الضحية المذعورة تفقد التفكير المنطقي وتتصرّف بغريزة البقاء، فتتشبّث بأي جسم صلب يقترب منها وتحاول تسلّقه لرفع رأسها فوق الماء، فتدفع المنقذ إلى الأسفل وقد تُغرقه معها. لذلك تُقدَّم لها أداة طفو أو حبل تمسك به بدل أن تمسك بالمنقذ، ولا يُلجأ إلى الاقتراب بالتلامس المباشر إلا بمنقذ مدرَّب يتقن أساليب التحرّر. الابتعاد سباحةً ورفض المساعدة قد يعطّلان الإنقاذ لكنهما لا يشكّلان خطراً جسدياً على المنقذ. والضحية فاقدة الوعي هي عملياً الأقل خطورة على المنقذ لأنها لا تقاوم، وإن كانت الأسوأ حالاً من الناحية الطبية. المعلومة المفتاحية: خطر الغريق الواعي هو التشبّث والسحب إلى الأسفل — أعطِه ما يطفو ولا تعطه جسدك.', 'A panicking victim loses rational control and acts on survival instinct, grabbing any solid object that comes near and climbing it to lift the head clear of the water, which forces the rescuer under and can drown them both. That is why a flotation device or rope is offered for the victim to hold instead of the rescuer, and why direct contact approach is reserved for trained rescuers who know release techniques. Swimming away or refusing assistance may frustrate the rescue but pose no physical danger to the rescuer. An unconscious victim is in practice the least dangerous to handle because there is no struggle, even though medically the worst off. Takeaway: the danger from a conscious drowning victim is being grabbed and pulled under, so give them something that floats, never your body.', 'الغريق المذعور قد يعرّض المنقذين للخطر عن طريق:', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 24, 'During water rescue operations, rescuers should approach from:', '["Downstream in moving water","Upstream in moving water","Directly behind waves","Any direction equally"]'::jsonb, 0, 'في المياه الجارية يقترب المنقذ أو القارب من جهة أسفل المجرى صاعداً بعكس التيار، لأن هذا الوضع يمنحه تحكّماً بالسرعة وقدرة على التوقّف أو الانسحاب في أي لحظة. أما القدوم مندفعاً مع التيار من الأعلى فيعني الارتطام بالضحية بقوة الماء دون قدرة على الكبح، وقد ينحشر الاثنان معاً على صخرة أو عائق غاطس. وخيار «من خلف الأمواج مباشرة» لا يصف اتجاهاً مفهوماً بالنسبة للتيار ولا يُدرَّس كقاعدة. والقول إن كل الاتجاهات متساوية يتجاهل أن الماء المتحرك يفرض اتجاه اقتراب واحداً آمناً. المعلومة المفتاحية: في الماء الجاري اقترب من أسفل المجرى وأنت تواجه التيار، لتبقى مسيطراً لا مدفوعاً.', 'In moving water the rescuer or the boat approaches from downstream, working up against the current, because that position preserves control of speed and allows an immediate stop or withdrawal. Coming down with the current from upstream means being driven onto the victim by the force of the water with no ability to brake, and both may end up pinned against a rock or a submerged strainer. "Directly behind waves" describes no meaningful orientation relative to the current and is not taught as a rule. Saying that any direction is equally acceptable ignores the fact that moving water dictates one safe line of approach. Takeaway: in current, approach from downstream facing the flow so you stay in control instead of being pushed.', 'أثناء عمليات الإنقاذ المائي، ينبغي أن يقترب المنقذون من:', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 25, 'What is the MOST appropriate initial treatment for a drowning victim with no pulse?', '["Heimlich maneuver","Immediate defibrillation only","CPR with rescue breaths","Recovery position"]'::jsonb, 2, 'لأن سبب توقّف القلب في الغرق هو نقص الأكسجين، يبدأ الإنعاش بأنفاس إنقاذية مبكرة ثم يستمر بدورات ضغط وتهوية، خلافاً للتوقّف القلبي المفاجئ ذي المنشأ القلبي الذي يُركَّز فيه على الضغطات. تنصح الإرشادات بإعطاء أنفاس أولية فور إخراج الضحية إلى سطح صلب آمن، ثم مواصلة الإنعاش بنسبة ٣٠:٢ للمنقذ الواحد مع الأكسجين حين يتوفّر. مناورة هايمليك غير موصى بها لأن الماء لا يسدّ المجرى الهوائي كجسم صلب، وهي تؤخّر الإنعاش وتزيد خطر القيء والشفط. والصدمة الكهربائية وحدها لا تعالج قلباً توقّف بسبب نقص الأكسجين وإن استُخدم جهاز الرجفان عند وجود إيقاع قابل للصدم، ووضعية الإفاقة تخصّ مريضاً يتنفس وله نبض. المعلومة المفتاحية: غريق بلا نبض = إنعاش قلبي رئوي يبدأ بالتهوية، لا مناورة هايمليك ولا صدمة منفردة.', 'Because cardiac arrest in drowning is caused by hypoxia, resuscitation begins with early rescue breaths and then continues as cycles of compressions and ventilations, unlike primary cardiac arrest where compression-focused care is emphasized. Guidelines advise giving initial ventilations as soon as the victim is on a firm, safe surface, then continuing CPR at 30:2 for a single rescuer with oxygen once available. The Heimlich maneuver is not recommended, since water does not obstruct the airway like a solid object, and it delays resuscitation while increasing vomiting and aspiration risk. Defibrillation alone does not correct an arrest caused by hypoxia, although an AED is applied if a shockable rhythm is present, and the recovery position applies only to a patient who is breathing with a pulse. Takeaway: a pulseless drowning victim needs CPR that starts with ventilation, not a Heimlich and not a shock by itself.', 'ما العلاج الأولي الأنسب لضحية غرق بلا نبض؟', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 26, 'Which sign is commonly associated with hypothermia?', '["Hot flushed skin","Shivering and altered mental status","Severe hypertension only","Dry mucous membranes"]'::jsonb, 1, 'أول استجابة للجسم للبرد هي الارتعاش، وهو انقباض عضلي لا إرادي يولّد حرارة، ويرافقه تضيّق الأوعية الطرفية فيصبح الجلد شاحباً بارداً. ومع استمرار هبوط الحرارة المركزية يتباطأ الدماغ فتظهر بلادة وتشوّش وكلام غير مترابط وترنّح، ثم يتوقّف الارتعاش في الانخفاض الشديد وهي علامة تدهور لا تحسّن. الجلد الساخن المحمرّ يشير إلى الإجهاد الحراري أو ضربة الشمس، أي الحالة المعاكسة تماماً. وارتفاع الضغط ليس علامة مميّزة، وجفاف الأغشية المخاطية يدلّ على الجفاف لا على التعرّض للبرد. المعلومة المفتاحية: ارتعاش + تغيّر في الوعي = انخفاض حرارة، وغياب الارتعاش في مريض بارد إنذار خطر.', 'The body''s first response to cold is shivering, an involuntary muscular effort to generate heat, accompanied by peripheral vasoconstriction that leaves the skin pale and cold. As core temperature keeps falling the brain slows, producing lethargy, confusion, slurred speech and poor coordination, and in severe hypothermia shivering ceases altogether, which signals deterioration rather than improvement. Hot flushed skin points to heat exhaustion or heat stroke, the opposite condition. Severe hypertension is not a distinguishing sign, and dry mucous membranes indicate dehydration rather than cold exposure. Takeaway: shivering plus altered mental status means hypothermia, and a cold patient who has stopped shivering is a red flag.', 'أي علامة ترتبط عادةً بانخفاض حرارة الجسم (Hypothermia)؟', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 27, 'What does “reach rescue” involve?', '["Swimming to the victim","Using an object to extend reach from safety","Helicopter rescue","Diving underwater"]'::jsonb, 1, 'الإنقاذ بالمدّ هو أول خطوة في تسلسل Reach–Throw–Row–Go، ومعناه أن يبقى المنقذ على اليابسة أو على حافة ثابتة ويمدّ للضحية عصا أو مجدافاً أو غصناً أو منشفة أو حتى يده، مع خفض مركز ثقله وتثبيت جسده حتى لا تسحبه الضحية. الفكرة أن نطيل ذراع المنقذ بأداة بدل أن نطيل خطره بالنزول إلى الماء. السباحة نحو الضحية والغوص تحت الماء يقعان في آخر التسلسل وأخطره ويحتاجان تدريباً ومعدات وفريق تأمين. والإنقاذ بالمروحية أسلوب جوي متخصص لا صلة له بمعنى كلمة «المدّ». المعلومة المفتاحية: المدّ = أداة تطول نحو الضحية ومنقذ لا يغادر موضعه الآمن.', 'Reach rescue is the first step of the Reach–Throw–Row–Go sequence: the rescuer stays on land or on a solid edge and extends a pole, oar, branch, towel or even a braced hand toward the victim, lowering the center of gravity and anchoring the body so the victim cannot pull them in. The idea is to lengthen the rescuer''s arm with an object instead of lengthening the rescuer''s exposure by entering the water. Swimming to the victim and diving underwater sit at the dangerous end of the sequence and demand training, equipment and a safety team. Helicopter rescue is a specialized aviation technique with nothing to do with the meaning of reach. Takeaway: reach means the tool travels toward the victim while the rescuer never leaves safe ground.', 'ماذا يعني «الإنقاذ بالمدّ» (reach rescue)؟', '{}'::jsonb, 'الإنقاذ المائي والغرق', false, false, false),
  ((select id from s), 28, 'What is the FIRST priority when arriving at a suspected crime scene?', '["Start patient treatment immediately","Secure the scene and ensure safety","Move all evidence away from the patient","Question bystanders"]'::jsonb, 1, 'مسرح الجريمة موقع قد يكون الجاني ما زال فيه أو قد يعود إليه، لذلك لا يدخله الطاقم إلا بعد أن تؤمّنه الشرطة، والأولوية الأولى دائماً سلامة الفريق ثم المريض. وبعد التأمين تُقدَّم الرعاية الطبية مع التحرّك في مسار واحد للدخول والخروج ولمس أقل قدر ممكن من الأشياء وتوثيق كل ما اضطررنا لتحريكه. البدء بالعلاج قبل التأمين يعرّض الطاقم لنفس التهديد الذي أصاب المريض. وإبعاد الأدلة عن المريض خطأ صريح لأنه إتلاف لمسرح الجريمة، واستجواب الشهود دور جهات التحقيق لا دور المسعف. المعلومة المفتاحية: في مسرح الجريمة أمّن أولاً ثم عالج، وحافظ على الأدلة دون أن تتحوّل إلى محقّق.', 'A crime scene may still hold the perpetrator, or one who returns, so the crew does not enter until law enforcement has secured it, and the first priority is always crew safety before patient care. Once the scene is secure, medical care proceeds using a single path in and out, touching as little as possible and documenting anything that had to be moved. Starting treatment before the scene is secured exposes the crew to the very threat that injured the patient. Moving all evidence away from the patient is plainly wrong because it destroys the scene, and questioning bystanders is the investigators'' role rather than the paramedic''s. Takeaway: at a crime scene secure first, then treat, and preserve evidence without becoming an investigator.', 'ما الأولوية الأولى عند الوصول إلى موقع يُشتبه بأنه مسرح جريمة؟', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 29, 'A scene is considered unsafe if:', '["The patient is unconscious","There are visible weapons or ongoing threats","There are multiple victims","Police are already present"]'::jsonb, 1, 'عدم أمان الموقع يُحدَّد بوجود تهديد نشط قادر على إيذاء الطاقم: سلاح ظاهر، أو شخص عدواني، أو عنف مستمر، أو حريق ومواد خطرة أو حركة مرور غير مضبوطة. وعند وجود مثل هذا التهديد يتراجع الطاقم إلى موقع آمن وينتظر الشرطة، لأن الدخول يضاعف عدد الضحايا ولا يُنقذ أحداً. فقدان المريض للوعي حالة طبية حرجة لكنه لا يشكّل بحدّ ذاته خطراً على المنقذ. وتعدّد المصابين مسألة موارد وفرز لا مسألة أمان، ووجود الشرطة يزيد الأمان ولا ينقصه. المعلومة المفتاحية: خطورة الموقع تُقاس بالتهديد على الطاقم لا بخطورة حالة المريض.', 'A scene is unsafe when an active threat capable of harming the crew is present: a visible weapon, an aggressive person, ongoing violence, fire, hazardous materials or uncontrolled traffic. Facing such a threat the crew withdraws to a safe position and waits for law enforcement, because entering simply adds casualties instead of saving anyone. An unconscious patient is medically critical but by itself poses no danger to the rescuer. Multiple victims is a question of resources and triage rather than safety, and the presence of police increases safety rather than reducing it. Takeaway: scene safety is judged by the threat to the crew, not by how sick the patient is.', 'يُعتبر الموقع غير آمن إذا:', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 30, 'At the end of a highway rescue operation, responders should:', '["Leave equipment behind","Conduct debriefing and equipment checks","Ignore documentation","Reopen traffic immediately without inspection"]'::jsonb, 1, 'مرحلة إنهاء العملية جزء أصيل من الإنقاذ وليست وقتاً ضائعاً: يجتمع الفريق لمراجعة ما جرى وما يمكن تحسينه، ثم تُجمع المعدات وتُنظَّف وتُفحص وتُعاد إلى جاهزيتها، ويُستكمل التوثيق ويُعرض الدعم النفسي عند الحاجة. ترك المعدات في الموقع يعني فقدها وخروج المركبة من الجاهزية، وقد تتحوّل هي نفسها إلى خطر على المرور. وتجاهل التوثيق يضيّع السجل الطبي والقانوني للحادث ويعرّض الفريق للمساءلة. وإعادة فتح الطريق فوراً دون فحص خطر مباشر، لأن الزيوت والزجاج والحطام والوقود قد تبقى على الأسفلت فتسبّب حادثاً ثانياً. المعلومة المفتاحية: العملية لا تنتهي بمغادرة المريض بل بإحاطة ختامية وفحص معدات وطريق نظيف وموثَّق.', 'Termination is a genuine part of the operation rather than wasted time: the team debriefs on what happened and what could be improved, then equipment is collected, cleaned, inspected and returned to a ready state while documentation is completed and psychological support offered if needed. Leaving equipment behind means losing it, taking the unit out of service and possibly creating a hazard for traffic. Ignoring documentation destroys the medical and legal record of the incident and exposes the crew to liability. Reopening traffic immediately without inspection is directly dangerous, because oil, glass, debris and fuel may still be on the roadway and cause a second collision. Takeaway: the call ends not when the patient leaves but after debriefing, equipment checks and a cleared, documented roadway.', 'في نهاية عملية إنقاذ على طريق سريع، ينبغي على أفراد الاستجابة:', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 31, 'Chlorine gas exposure requires which PPE before entering scene?', '["Surgical mask","N95 mask","SCBA","Gloves only"]'::jsonb, 2, 'الكلور غاز أثقل من الهواء يتجمّع في المنخفضات، ويتفاعل مع رطوبة الأغشية المخاطية فيكوّن حمضاً يحرق العين والطرق الهوائية وقد يسبّب وذمة رئوية متأخرة. الدخول إلى جوّ فيه كلور بتركيز مجهول يستوجب جهاز تنفس مكتفٍ ذاتياً يوفّر هواءً مستقلاً تماماً عن جو الموقع، مع وقاية للجلد والعين. الكمامة الجراحية حاجز للقطيرات لا يرشّح الغازات إطلاقاً، وكمامة N95 مصمّمة للجسيمات الدقيقة لا للغازات ولا تنفع في جوّ ناقص الأكسجين. والقفازات وحدها تحمي اليدين بينما الخطر القاتل هنا في الاستنشاق. المعلومة المفتاحية: غاز سام بتركيز مجهول = جهاز تنفس مكتفٍ ذاتياً قبل أي خطوة نحو الموقع.', 'Chlorine is heavier than air, pools in low areas, and reacts with the moisture of mucous membranes to form acid that burns the eyes and airway and can cause delayed pulmonary edema. Entering an atmosphere containing chlorine at an unknown concentration requires SCBA, which supplies air completely independent of the scene atmosphere, together with skin and eye protection. A surgical mask is a droplet barrier that filters no gases at all, and an N95 is built for fine particulates rather than gases and is useless in an oxygen-deficient atmosphere. Gloves alone protect the hands while the lethal route here is inhalation. Takeaway: a toxic gas at an unknown concentration means SCBA before any step toward the scene.', 'التعرّض لغاز الكلور يستلزم أي معدات وقاية قبل دخول الموقع؟', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 32, 'PPE Level C includes:', '["Full chemical suit with SCBA","Air-purifying respirator, gloves, protective clothing","Standard uniform","No protection"]'::jsonb, 1, 'المستوى C يعني حماية تنفسية بكمامة منقّية للهواء تُلبس مع بدلة واقية وقفازات وحذاء واقٍ وواقي عين، أي أن الجلد مغطّى والتنفس يمرّ عبر فلتر لا عبر أسطوانة. ولا يجوز استخدامه إلا إذا كان الملوّث معروفاً وتركيزه ضمن حدود الخرطوشة ونسبة الأكسجين في الجو كافية. البدلة الكيميائية الكاملة مع جهاز تنفس مكتفٍ ذاتياً تصف المستوى A أو B لا المستوى C. والزي الرسمي المعتاد ليس معدات وقاية أصلاً، و«لا وقاية» تمثّل أدنى صور المستوى D. المعلومة المفتاحية: الفرق بين B وC هو مصدر الهواء — أسطوانة مستقلة في B، وفلتر ينقّي هواء الموقع في C.', 'Level C means respiratory protection through an air-purifying respirator worn with a protective suit, gloves, boots and eye protection, so the skin is covered and breathing passes through a filter rather than a cylinder. It is permitted only when the contaminant is identified, its concentration is within the cartridge rating, and ambient oxygen is adequate. A full chemical suit with SCBA describes Level A or B, not Level C. A standard uniform is not PPE at all, and "no protection" corresponds to the barest form of Level D. Takeaway: the dividing line between Level B and Level C is the air source, an independent cylinder in B versus a filter cleaning scene air in C.', 'معدات الوقاية الشخصية من المستوى C تشمل:', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 33, 'Tanker truck overturned with flammable liquid, first safety measure:', '["Rescue patients immediately","Establish isolation distances (ERG)","Wait for evaporation","Use water to wash spill"]'::jsonb, 1, 'أول ما يُفعل في حادث مادة خطرة هو تحديد المادة من اللافتة أو رقم الأمم المتحدة، ثم فرض مسافات العزل والإخلاء الواردة في دليل الاستجابة الطارئة، لأن هذه المسافات هي التي تحدّد أين يقف الجميع وأين تُرسم مناطق العمل. الاندفاع لإنقاذ المصابين قبل العزل يضع الطاقم داخل سحابة أبخرة قابلة للاشتعال وقد يحوّله إلى مصابين جدد. وانتظار تبخّر السائل ليس إجراء سلامة بل ترك للخطر يتمدّد مع اتجاه الريح. واستخدام الماء لغسل الانسكاب ينشر السائل ويلوّث المجاري ويوسّع رقعة الحريق المحتمل. المعلومة المفتاحية: في المواد الخطرة العزل يسبق الإنقاذ — حدّد المادة، ارسم المسافة، ثم تحرّك.', 'The first action at a hazardous materials incident is identifying the product from the placard or UN number and then imposing the isolation and evacuation distances given in the Emergency Response Guidebook, because those distances decide where everyone stands and where the control zones are drawn. Rushing in to rescue patients before isolation places the crew inside a flammable vapor cloud and can turn them into additional casualties. Waiting for the liquid to evaporate is not a safety measure but an invitation for the hazard to spread downwind. Washing the spill with water moves the product, contaminates drains and enlarges the potential fire area. Takeaway: at a HAZMAT scene isolation precedes rescue, so identify the product, set the distance, then act.', 'انقلاب شاحنة صهريج تحمل سائلاً قابلاً للاشتعال — ما أول إجراء سلامة؟', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 34, 'Ammonia gas exposure treatment:', '["IV fluids","Move to fresh air","Antibiotic ointment","Wrap in blanket"]'::jsonb, 1, 'الأمونيا غاز شديد الذوبان في الماء، فيهاجم العين والأنف والحلق والطرق الهوائية العليا فور ملامسته للأغشية الرطبة. لذلك تكون الخطوة العلاجية الأولى إخراج المصاب من الجو الملوّث إلى هواء نقي لإيقاف التعرّض، ثم غسل العين والجلد بكثرة الماء وإعطاء الأكسجين ومراقبة المجرى الهوائي من التورّم. السوائل الوريدية قد تلزم لاحقاً في الحالات الشديدة لكنها ليست علاج التعرّض نفسه. والمرهم المضاد الحيوي لا دور له في إصابة كيميائية حادّة وقد يحبس المادة على الجلد، ولفّ المصاب ببطانية إجراء حراري لا صلة له بقطع التعرّض. المعلومة المفتاحية: علاج أي غاز مهيّج يبدأ بقطع التعرّض — هواء نقي أولاً، ثم غسل وأكسجين ومراقبة للمجرى الهوائي.', 'Ammonia is highly water-soluble and attacks the eyes, nose, throat and upper airway the moment it meets moist membranes. The first therapeutic step is therefore removing the patient from the contaminated atmosphere into fresh air to stop the exposure, followed by copious irrigation of eyes and skin, oxygen, and close airway monitoring for swelling. Intravenous fluids may be needed later in severe cases but are not the treatment of the exposure itself. Antibiotic ointment has no role in an acute chemical injury and may trap the agent against the skin, while wrapping the patient in a blanket is a thermal measure unrelated to interrupting exposure. Takeaway: treatment of any irritant gas starts by stopping the exposure, fresh air first, then irrigation, oxygen and airway watch.', 'علاج التعرّض لغاز الأمونيا:', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 35, 'Flammable liquid spill—best method to control ignition sources:', '["Douse with water","Remove spark sources and ventilate","Cover with blankets","Wait"]'::jsonb, 1, 'الخيارات الثلاثة الخاطئة تكشف الفكرة نفسها من زاويتها المقابلة: الماء لا يطفئ شرارة لم تقع بعد، والبطانية لا تحبس بخاراً ينتشر في كل اتجاه، والانتظار يمنح البخار وقتاً ليصل إلى أقرب محرّك أو مفتاح كهربائي. الخطر هنا ليس بركة السائل بل الغيمة غير المرئية فوقها، وهي تشتعل متى وجدت طاقة إشعال وتركيزاً واقعاً بين الحدّ الأدنى والحدّ الأعلى للاشتعال. لذلك يعمل الفريق على ضلعين من مثلث النار في وقت واحد: إلغاء كل مصدر طاقة قادر على الإشعال، وتهوية تخفض تركيز البخار تحت حدّ الاشتعال. ويشمل ذلك إطفاء المحركات ومنع الهواتف والإنارة غير المؤمّنة وإبعاد المتفرجين إلى جهة أعلى الريح. المعلومة المفتاحية: عالِج الغيمة لا البركة — أطفئ كل مصدر إشعال وهوِّ المكان قبل أن يكتمل مثلث النار.', 'The three wrong options expose the same principle from the opposite side: water cannot extinguish a spark that has not happened yet, a blanket cannot contain vapor spreading in every direction, and waiting merely gives the vapor time to reach the nearest engine or electrical switch. The hazard is not the pool of liquid but the invisible cloud above it, which ignites whenever it finds an energy source and a concentration between the lower and upper flammable limits. So the crew attacks two sides of the fire triangle at once: eliminating every energy source capable of ignition, and ventilating to hold vapor below the lower flammable limit. In practice that means shutting down engines, banning phones and non-intrinsically-safe lighting, and moving bystanders upwind. Takeaway: treat the cloud rather than the puddle, killing ignition sources and ventilating before the fire triangle can close.', 'انسكاب سائل قابل للاشتعال — ما أفضل طريقة للسيطرة على مصادر الإشعال؟', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 36, 'HAZMAT awareness-level paramedic may:', '["Recognize hazards, call for specialized help","Enter Hot Zone","Mitigate chemical release","Operate containment equipment"]'::jsonb, 0, 'انظر إلى الخيارات الخاطئة تجدها كلها أفعالاً هجومية: دخول المنطقة الساخنة، وإيقاف التسرّب، وتشغيل معدات الاحتواء، وثلاثتها تتطلب مستوى الفنّي المتخصص مع وقاية عالية وخطة عمل وفريق إنقاذ احتياطي. مستوى الوعي في المعايير المعتمدة ليس مستوى تدخّل بل مستوى إدراك: صاحبه يقف من مسافة آمنة في جهة أعلى الريح وأعلى المنحدر، ويقرأ اللافتة ورقم الأمم المتحدة بالمنظار، ويفتح دليل الاستجابة الطارئة ليحدّد مسافة العزل. ثم يبلّغ غرفة العمليات ويطلب الفريق المختص ويمنع الناس من الاقتراب ويهيّئ نقطة تجمّع للوحدات القادمة. وأي خطوة أبعد من ذلك تُخرجه من صلاحياته وتحوّله إلى مصاب محتمل. المعلومة المفتاحية: قِس المستوى بالفعل المطلوب — كل فعل يلمس المادة نفسها خارج نطاق مستوى الوعي.', 'Look at the wrong options and they are all offensive actions: entering the Hot Zone, stopping the release, and operating containment equipment, each requiring technician-level certification with high-level PPE, a work plan and a backup rescue team. Under the recognized standards awareness level is not an intervention level but a recognition level: the responder stays at a safe distance uphill and upwind, reads the placard and UN number through binoculars, and opens the ERG to establish an isolation distance. They then notify dispatch, request the specialized team, keep people back, and set up a staging point for incoming units. Anything beyond that exceeds their scope and turns them into a potential casualty. Takeaway: judge the level by the action required, because any action that touches the material itself lies outside awareness level.', 'المسعف المؤهَّل بمستوى «الوعي/الإدراك» (Awareness) في المواد الخطرة يستطيع أن:', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 37, 'Emergency medical care priority for chemical exposure:', '["Remove from source → Decontaminate → Treat symptoms","Decontaminate → Treat → Remove from source","Treat symptoms → Remove from source → Decontaminate","Remove source only"]'::jsonb, 0, 'جرّب الترتيبات الثلاثة الأخرى ترَ لماذا تسقط جميعها: البدء بإزالة التلوث يعني غسل مصاب ما زال واقفاً داخل مصدر التعرّض، والبدء بعلاج الأعراض يعني اقتراب الفريق من مادة لم تُزَل بعد فيصير المعالِج مصاباً، و«إزالة المصدر فقط» تتوقّف عند نصف الطريق وتترك المادة على جلد المريض. الترتيب الصحيح يتبع منطق قطع سلسلة الأذى: أوقف التعرّض بإبعاد المصاب، ثم أزل ما بقي على جسده بخلع الملابس والغسل الغزير، ثم انتقل إلى العلاج العرضي والداعم. وخلع الملابس وحده يزيل نسبة كبيرة من الملوّث، وهو أسرع تدخّل مؤثّر متاح في الميدان. المعلومة المفتاحية: كل خطوة في الترتيب تحمي التي تليها — من لم يُبعَد لا يُغسَل، ومن لم يُغسَل لا يُعالَج.', 'Test the other three sequences and each one collapses: starting with decontamination means washing a patient still standing inside the source, starting with treatment brings the crew up against an agent that has not been removed so the treater becomes a patient, and "remove source only" stops halfway and leaves the chemical on the patient''s skin. The correct order follows the logic of breaking the chain of harm: stop the exposure by moving the patient out, remove what remains on the body by disrobing and copious irrigation, then move on to symptomatic and supportive care. Disrobing alone removes a large share of the contaminant and is the fastest high-yield intervention available in the field. Takeaway: each step protects the step after it, so no washing before removal and no treatment before washing.', 'ترتيب أولويات الرعاية الطبية الطارئة في حالة التعرّض الكيميائي:', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 38, 'Best method to prevent inhalation during chemical exposure:', '["Hold breath","Use air-purifying respirator or SCBA","Cover mouth with shirt","Quick exit only"]'::jsonb, 1, 'الخيارات الثلاثة الخاطئة تشترك في أنها تعتمد على الجسد لا على الجهاز: حبس النفس يعتمد على إرادة تنهار خلال ثوانٍ وتنتهي بشهيق عميق في أسوأ لحظة، وتغطية الفم بالقميص تعتمد على نسيج لا يملك وسطاً ماصّاً للغازات ولا إحكاماً حول الأنف، والخروج السريع يعتمد على سرعة لا تلغي أنفاس الطريق ولا تنفع إن فقد المسعف وعيه في الداخل. الحماية الحقيقية جهاز يفصل بينك وبين الجو: كمامة منقّية للهواء بخرطوشة مطابقة للملوّث حين يكون معروفاً والأكسجين كافياً، أو جهاز تنفس مكتفٍ ذاتياً حين يكون الجو مجهولاً أو ناقص الأكسجين أو مرتفع التركيز. ولكل جهاز شروط استخدام لا تُهمَل: فحص إحكام على الوجه، وخرطوشة صالحة مناسبة، وضغط أسطوانة كافٍ لزمن العمل. المعلومة المفتاحية: كل ما يعتمد على قدرة جسدك وهمُ حماية، والوقاية التنفسية تُقاس بجهاز مطابق مفحوص لا بحيلة.', 'The three wrong options share one flaw: they rely on the body instead of on equipment. Holding your breath depends on willpower that fails within seconds and ends in a deep gasp at the worst possible moment; a shirt over the mouth is fabric with no gas-adsorbing medium and no seal around the nose; and a quick exit does not cancel the breaths taken on the way out and is useless if the responder collapses inside. Real protection is a device that separates you from the atmosphere: an air-purifying respirator with a cartridge matched to a known contaminant in an oxygen-adequate atmosphere, or SCBA when the atmosphere is unknown, oxygen-deficient or highly concentrated. Each device carries conditions that are never skipped, including a face fit check, a valid matching cartridge and enough cylinder pressure for the work period. Takeaway: anything that depends on your body is an illusion of protection, and respiratory safety is measured by a matched, checked device.', 'أفضل وسيلة لمنع الاستنشاق أثناء التعرّض الكيميائي:', '{}'::jsonb, 'المواد الخطرة والتعرّض الكيميائي', false, false, false),
  ((select id from s), 39, 'Which rescue phase occurs AFTER extrication?', '["Scene survey","Hazard control","Transfer and transport","Dispatch"]'::jsonb, 2, 'مراحل الإنقاذ تسير بترتيب منطقي: تقدير الموقف ومسح الموقع، ثم السيطرة على المخاطر وتثبيت المركبة، ثم الوصول، ثم فكّ الاحتجاز والاستخلاص. وبعد خروج المصاب من الحطام تأتي مرحلة التسليم والنقل، حيث يُنقل إلى النقالة وسيارة الإسعاف ثم إلى المنشأة المناسبة مع تقرير تسليم منظّم. ومسح الموقع تقييم أولي يقع لحظة الوصول قبل كل شيء، والسيطرة على المخاطر تسبق الاقتراب من المركبة لأنها هي التي تجعل العمل ممكناً. أما الإرسال فهو استدعاء الوحدة من غرفة العمليات، أي أنه سابق للعملية الميدانية كلها. المعلومة المفتاحية: بعد الاستخلاص لا يبقى إلا نقل المريض وتسليمه، وكل الخيارات الأخرى تقع قبله لا بعده.', 'Rescue phases follow a logical order: size-up and scene survey, then hazard control and vehicle stabilization, then access, then disentanglement and extrication. Once the patient is out of the wreckage comes transfer and transport, moving them to the stretcher and ambulance and on to the appropriate facility with a structured handover report. Scene survey is the initial assessment made on arrival before anything else, and hazard control precedes any approach to the vehicle because it is what makes the work possible. Dispatch is the alerting of the unit from the communications center and therefore precedes the entire field operation. Takeaway: after extrication only transport and handover remain, since every other option belongs before extrication rather than after it.', 'أي مرحلة من مراحل الإنقاذ تأتي بعد الاستخلاص؟', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 40, 'Which rescue phase focuses on preventing further injury to rescuers and victims?', '["Stabilization","Documentation","Transport","Recovery"]'::jsonb, 0, 'التثبيت هو المرحلة التي تُبطل حركة المركبة أو الحطام قبل أن يقترب أحد، بالإسفين تحت العجلات والتدعيم بالأخشاب وتفريغ هواء الإطارات وفصل البطارية، وهدفها المعلن منع أي أذى إضافي للمنقذين والمصابين معاً أثناء العمل. فالمركبة غير المثبّتة قد تنزلق أو تتدحرج أو تهبط فجأة على من يعمل تحتها، وكل حركة منها تنتقل إلى عمود فقري مصاب في الداخل. والتوثيق عمل ورقي لا يمنع أذى ميدانياً، والنقل مرحلة لاحقة تفترض أن المصاب صار خارج الحطام أصلاً. أما الاسترجاع فيعني انتشال المتوفين أو استعادة المعدات بعد انتهاء الإنقاذ. المعلومة المفتاحية: الوقاية من الأذى الإضافي اسمها التثبيت — لا حركة للمركبة يعني لا إصابة جديدة.', 'Stabilization is the phase that eliminates movement of the vehicle or debris before anyone approaches, using chocks, cribbing, tire deflation and battery disconnection, and its stated purpose is preventing further harm to rescuers and patients alike during the work. An unstabilized vehicle can slide, roll or drop suddenly onto whoever is working beneath it, and every shift is transmitted to an injured spine inside. Documentation is paperwork and prevents no field injury, while transport is a later phase that assumes the patient is already out of the wreckage. Recovery refers to retrieving deceased victims or equipment once the rescue itself is over. Takeaway: the phase dedicated to preventing further injury is stabilization, because no vehicle movement means no new injury.', 'أي مرحلة من مراحل الإنقاذ تركّز على منع وقوع مزيد من الإصابات للمنقذين والضحايا؟', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 41, 'The recovery phase of rescue operations usually refers to:', '["Saving viable victims","Removal of deceased victims or equipment retrieval","Ambulance transport","Airway management"]'::jsonb, 1, 'مصطلح الاسترجاع في أدبيات الإنقاذ يصف ما يجري بعد أن تنتهي فرص الإنقاذ الحقيقي: انتشال جثامين المتوفين واستعادة المعدات والمركبات من الموقع. والفارق الجوهري بينه وبين الإنقاذ أن العملية تتحوّل من سباق مع الزمن إلى عمل مخطَّط بلا مخاطرة، لأنه ما من حياة تُنتظر فلا مبرّر لتعريض المنقذين للخطر. ولذلك فإن «إنقاذ الضحايا القابلين للنجاة» وصف لمرحلة الإنقاذ نفسها لا للاسترجاع. والنقل بسيارة الإسعاف ينتمي إلى مرحلة التسليم والنقل، وإدارة المجرى الهوائي إجراء طبي يجري ضمن الرعاية لا مرحلة عملياتية. المعلومة المفتاحية: حين تتحوّل العملية من إنقاذ إلى استرجاع تسقط المخاطرة — لا حياة تُنتظر، فلا خطر يُقبل.', 'In rescue terminology recovery describes what happens once realistic rescue is over: retrieving the bodies of the deceased and recovering equipment and vehicles from the scene. The essential difference from rescue is that the operation shifts from a race against time to a deliberate, low-risk task, because no life remains to be saved and therefore no reason to expose rescuers to danger. "Saving viable victims" accordingly describes the rescue phase itself rather than recovery. Ambulance transport belongs to transfer and transport, and airway management is a clinical intervention delivered within patient care rather than an operational phase. Takeaway: when an operation changes from rescue to recovery the risk-taking stops, since no life is waiting, no hazard is accepted.', 'مرحلة الاسترجاع (Recovery) في عمليات الإنقاذ تشير عادةً إلى:', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 42, 'Which phase includes disentangling a trapped patient from wreckage?', '["Access","Extrication","Triage","Rehabilitation"]'::jsonb, 1, 'الاستخلاص هو المرحلة التي تشمل فكّ الاحتجاز، أي قصّ المعدن وإزاحة لوحة القيادة والمقاعد والأجزاء المطبِقة على المصاب حتى يصير إخراجه ممكناً دون زيادة إصاباته. أما الوصول فيسبقه، وهدفه فتح ثغرة تسمح بملامسة المصاب وتقييمه وبدء الرعاية، وقد يكون بفتح باب أو كسر زجاج قبل أي عمل تحريري. والفرز تصنيف للمصابين حسب أولوية العلاج في حوادث الإصابات الجماعية ولا صلة له بتحرير مريض من مركبة. وإعادة التأهيل مصطلح يشير إلى إراحة أفراد الاستجابة وترطيبهم ومراقبة علاماتهم الحيوية أثناء العمليات الطويلة. المعلومة المفتاحية: الوصول يفتح طريقك إلى المصاب، والاستخلاص يفتح للمصاب طريق الخروج — وفكّ الاحتجاز جزء من الثاني.', 'Extrication is the phase that contains disentanglement: cutting metal and displacing dashboards, seats and the structure pinning the patient so that removal becomes possible without adding injury. Access comes before it and aims only to create an opening that lets the crew reach the patient, assess and begin care, sometimes simply by opening a door or breaking a window. Triage is the sorting of casualties by treatment priority in a mass-casualty incident and has nothing to do with freeing a patient from a vehicle. Rehabilitation refers to resting, rehydrating and monitoring responders during prolonged operations. Takeaway: access opens a path to the patient while extrication opens a path out for the patient, and disentanglement belongs to the latter.', 'أي مرحلة تتضمّن فكّ احتجاز مريض محاصر داخل الحطام؟', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 43, 'The termination phase includes:', '["Hazard identification","Returning equipment and documentation","Initial patient assessment","Vehicle stabilization"]'::jsonb, 1, 'إنهاء العملية هو الجزء الأخير من دورة الاستجابة، ويشمل جمع المعدات وتنظيفها وفحصها وإعادتها إلى أماكنها، وإعادة الوحدة إلى الجاهزية، واستكمال تقرير الحالة والتوثيق، ثم الإحاطة الختامية ومراجعة الأداء. وهذه المرحلة ليست إجراء شكلياً، فهي التي تضمن أن الفريق التالي سيجد معدات صالحة وسجلاً مكتملاً. أما تحديد المخاطر فيقع ضمن تقدير الموقف لحظة الوصول، أي في بداية العملية لا في نهايتها. والتقييم الأولي للمريض جزء من الرعاية أثناء المهمة، وتثبيت المركبة إجراء ميداني يسبق الوصول إلى المصاب. المعلومة المفتاحية: العملية تنتهي بمعدات جاهزة وتوثيق مكتمل وإحاطة ختامية، لا بمجرّد مغادرة الموقع.', 'Termination is the closing part of the response cycle and covers collecting, cleaning, checking and restocking equipment, returning the unit to service, completing the patient care report and documentation, and holding the debriefing and performance review. This phase is not a formality: it is what guarantees that the next crew finds serviceable equipment and a complete record. Hazard identification belongs to size-up on arrival, at the beginning of the operation rather than its end. Initial patient assessment is part of the care delivered during the call, and vehicle stabilization is a field action performed before the patient is reached. Takeaway: a call ends with ready equipment, finished documentation and a debriefing, not with driving away from the scene.', 'مرحلة إنهاء العملية (Termination) تشمل:', '{}'::jsonb, 'مراحل عمليات الإنقاذ الفنية', false, false, false),
  ((select id from s), 44, 'In tactical EMS principles, retreat decisions are based primarily on:', '["Patient age","Scene threat level and risk assessment","Family requests","Transport time only"]'::jsonb, 1, 'الإسعاف التكتيكي يقوم على مبدأ أن الرعاية تتشكّل حسب التهديد لا حسب الرغبة: ففي المنطقة الساخنة تقتصر الأولوية على إبعاد المصاب ووقف النزيف الشديد، وفي المنطقة الدافئة تُقدَّم رعاية محدودة موجزة، وفي المنطقة الباردة تُستكمل الرعاية الكاملة. ولذلك يكون قرار الانسحاب أو البقاء ثمرة تقدير مستمر لمستوى التهديد وموازنة بين الخطر والفائدة، ويُعاد تقييمه كلما تغيّر الموقف. وعمر المريض معيار طبي مهم في العلاج لكنه لا يغيّر خطورة إطلاق نار أو انهيار مبنى. وطلبات العائلة عامل عاطفي لا يُبنى عليه قرار أمني، وزمن النقل وحده معلومة لوجستية لا تصف التهديد أصلاً. المعلومة المفتاحية: في البيئة التكتيكية التهديد هو من يقود القرار — والمسعف المصاب لا يعالج أحداً.', 'Tactical EMS rests on the idea that care is shaped by the threat rather than by preference: in the hot zone the priority is limited to moving the patient and controlling massive hemorrhage, in the warm zone brief limited care is given, and full care is completed in the cold zone. A decision to withdraw or stay is therefore the product of continuous threat assessment and a risk-versus-benefit judgement that is revisited whenever the situation changes. Patient age is an important clinical variable but it does not change the danger of gunfire or a collapsing structure. Family requests are an emotional factor that cannot drive a security decision, and transport time alone is logistical information that says nothing about the threat. Takeaway: in a tactical environment the threat drives the decision, because an injured medic treats no one.', 'في مبادئ الإسعاف التكتيكي، تُبنى قرارات الانسحاب أساساً على:', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 45, 'What is the correct first action upon arrival at an MVA scene?', '["Enter the vehicle immediately","Perform a rapid patient assessment","Conduct a 360° scene survey","Start IV access"]'::jsonb, 2, 'المسح الشامل حول الموقع بزاوية كاملة هو أول ما يفعله الطاقم، لأنه يكشف ما لا يظهر من الواجهة الأمامية: عدد المركبات، وعدد المصابين، وآلية الإصابة، والوقود المنسكب، والكابلات الساقطة، وحركة المرور القادمة، ومصابين مقذوفين خارج المركبة. وهذا المسح هو الذي يحدّد ما إذا كنا نحتاج وحدات إضافية أو فرق إنقاذ أو إطفاء قبل أن ينشغل أحد بالمريض. ودخول المركبة فوراً يضع المسعف داخل هيكل غير مثبّت وربما وسط خطر لم يُقيَّم بعد. والتقييم السريع للمريض وفتح الخط الوريدي رعاية طبية لا تبدأ قبل تأمين المشهد، لأن سلامة الطاقم تسبق سلامة المريض. المعلومة المفتاحية: عيناك تدوران حول الموقع كاملاً قبل أن تلمس يداك أي مريض.', 'A full 360-degree walk-around is the first action on arrival because it reveals what the front view hides: the number of vehicles, the number of patients, the mechanism of injury, spilled fuel, downed wires, oncoming traffic and patients ejected clear of the wreck. That survey is what determines whether extra units, rescue or fire suppression are required before anyone becomes occupied with a patient. Entering the vehicle immediately puts the medic inside an unstabilized structure and possibly in the middle of an unassessed hazard. Rapid patient assessment and IV access are patient care, which does not begin before the scene is secured, because crew safety precedes patient care. Takeaway: your eyes circle the entire scene before your hands touch any patient.', 'ما الإجراء الأول الصحيح عند الوصول إلى موقع حادث مروري؟', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 46, 'A major hazard at an MVA scene includes:', '["Clean environment","Air conditioning systems","Fuel leakage and fire risk","Patient clothing"]'::jsonb, 2, 'تسرّب الوقود من الخزان أو الأنابيب يخلق بركة وأبخرة قابلة للاشتعال، وقد تكفي شرارة من دائرة كهربائية مقطوعة أو معدن ساخن أو أداة قصّ لإشعالها، فيتحوّل الحادث إلى حريق يحاصر المصاب والفريق معاً. لذلك يُفصل قطب البطارية، وتُبعد مصادر الإشعال، وتُجهَّز طفاية أو خرطوم قبل بدء القصّ، مع مراقبة أي انسكاب أو رائحة وقود. والبيئة النظيفة ليست خطراً بل صفة إيجابية تسهّل العمل. وأنظمة التكييف في المركبة لا تشكّل تهديداً على المنقذين، وملابس المريض قد تُقص أثناء الفحص لكنها ليست خطراً في الموقع. المعلومة المفتاحية: الوقود والحريق هما الخطر الأكبر في حوادث المركبات، ويُقابَلان بفصل البطارية وإبعاد مصادر الإشعال وتجهيز وسيلة إطفاء.', 'Fuel escaping from a tank or line creates a pool and flammable vapors, and a spark from a severed electrical circuit, hot metal or a cutting tool can be enough to ignite them, turning the collision into a fire that traps patient and crew together. For that reason the battery is disconnected, ignition sources are removed, and an extinguisher or charged line is ready before cutting begins, with continuous watch for spills or fuel odor. A clean environment is not a hazard but a favorable finding that makes the work easier. A vehicle''s air conditioning system poses no threat to rescuers, and the patient''s clothing may be cut away during assessment but is not a scene hazard. Takeaway: fuel and fire are the dominant hazard at a crash, answered by battery isolation, ignition control and a ready means of extinguishing.', 'من الأخطار الكبرى في موقع الحادث المروري:', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 47, 'Before approaching a crashed vehicle, paramedics should check:', '["Vehicle color","Engine size","Traffic flow and oncoming vehicles","Patient identity"]'::jsonb, 2, 'المرور المارّ هو القاتل الصامت في حوادث الطرق، فالسائق القادم قد لا يرى الفريق ليلاً أو في المطر أو خلف منعطف، وأغلب إصابات أفراد الاستجابة على الطريق تقع بالدهس أثناء انشغالهم بالمريض. لذلك يُتحقّق من اتجاه الحركة وسرعتها قبل النزول، وتُوضع سيارة الإسعاف كحاجز يحمي منطقة العمل، وتُستخدم الأقماع والسترات عالية الوضوح والإنارة، ويبقى التحرّك في مواجهة حركة المرور لا بالظهر إليها. ولون المركبة وحجم المحرك تفصيلان لا يغيّران شيئاً في سلامة الاقتراب. وهوية المريض معلومة إدارية تُجمع لاحقاً ضمن التوثيق ولا علاقة لها بالخطر المحيط. المعلومة المفتاحية: قبل أن تقترب من الحطام انظر إلى الطريق لا إلى السيارة — الخطر يأتي من خلفك بسرعة الطريق.', 'Passing traffic is the silent killer at roadway incidents, since an approaching driver may not see the crew at night, in rain or beyond a bend, and most responder injuries on the road come from being struck while attention is on the patient. Traffic direction and speed are therefore checked before stepping out, the ambulance is positioned to shield the work area, cones, high-visibility clothing and lighting are used, and crews move facing traffic rather than with their backs to it. Vehicle color and engine size are details that change nothing about the safety of the approach. Patient identity is administrative information gathered later as part of documentation and has no bearing on the surrounding hazard. Takeaway: before approaching the wreck look at the road rather than at the car, because the danger arrives from behind at highway speed.', 'قبل الاقتراب من مركبة تعرّضت لحادث، ينبغي على المسعفين التحقّق من:', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 48, 'What is the safest approach to a vehicle involved in an accident?', '["From the front of the vehicle","From the side facing traffic","From a safe angle avoiding traffic exposure","From inside another vehicle"]'::jsonb, 2, 'الاقتراب الآمن يعني اختيار مسار يبقيك خارج مسار المركبات المارّة وداخل المنطقة المحمية خلف سيارة الإسعاف أو مركبة الإطفاء، مع مراعاة أن يبقى المصاب قادراً على رؤيتك حتى لا يلتفت برأسه وعموده الفقري نحوك. والاقتراب من الجهة المكشوفة على حركة المرور يضع المسعف في المسار المفتوح تماماً، وهو أكثر أوضاع الدهس شيوعاً. والاقتراب من المقدّمة قد يفيد في إبقائك ضمن مجال رؤية المصاب، لكنه ليس بحدّ ذاته معياراً للسلامة من المرور وقد يمرّ بمنطقة تسرّب الوقود أو أمام وسائد هوائية لم تنفجر. أما البقاء داخل مركبة أخرى فليس اقتراباً أصلاً ولا يسمح بأي تقييم أو رعاية. المعلومة المفتاحية: اقترب من الجهة المحمية بعيداً عن مسار المرور، وابقَ حيث يستطيع المصاب أن يراك.', 'A safe approach means choosing a path that keeps you out of the lane used by passing vehicles and inside the area shielded by the ambulance or fire apparatus, while ideally staying within the patient''s line of sight so they do not turn their head and spine toward you. Approaching from the side facing traffic places the responder fully in the open lane, which is the commonest way responders are struck. Approaching from the front may help keep you in the patient''s field of vision but is not in itself a traffic-safety rule and can lead you through spilled fuel or in front of undeployed airbags. Staying inside another vehicle is not an approach at all and permits no assessment or care. Takeaway: approach from the protected angle away from the traffic lane, and stay where the patient can see you.', 'ما الطريقة الأكثر أماناً للاقتراب من مركبة تعرّضت لحادث؟', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 49, 'Which PPE is MOST essential at an MVA scene?', '["Stethoscope only","Gloves, high-visibility jacket, and helmet if needed","Oxygen mask only","Surgical gown only"]'::jsonb, 1, 'موقع الحادث المروري يجمع ثلاثة أخطار في وقت واحد: دم وسوائل جسدية، ومرور سريع لا يرى الفريق، وزجاج ومعدن حادّ وحطام قد ينهار. لذلك تكون الوقاية الأساسية قفازات تحمي من الملامسة، وسترة عالية الوضوح تجعل المسعف مرئياً للسائقين، وخوذة مع واقي عين حين يجري العمل بأدوات القصّ أو تحت خطر السقوط. والسماعة الطبية أداة تقييم لا وسيلة وقاية، وقناع الأكسجين علاج يُعطى للمريض لا حماية للمسعف. والعباءة الجراحية حاجز للسوائل في بيئة نظيفة لكنها لا تحمي من المرور ولا من الزجاج والمعدن. المعلومة المفتاحية: وقاية الحادث المروري تُبنى على ثلاثة: حاجز للسوائل، ووضوح لعين السائق، وحماية للرأس والوجه.', 'A motor vehicle collision presents three hazards at once: blood and body fluids, fast traffic that cannot see the crew, and glass, sharp metal and debris that may shift. The essential protection is therefore gloves as a contact barrier, a high-visibility jacket that makes the responder visible to drivers, and a helmet with eye protection whenever cutting tools are used or falling hazards exist. A stethoscope is an assessment instrument rather than protective equipment, and an oxygen mask is a treatment given to the patient rather than protection for the medic. A surgical gown is a fluid barrier suited to a clean environment but offers nothing against traffic, glass or metal. Takeaway: MVA protection rests on three things, a fluid barrier, visibility to drivers, and protection for the head and face.', 'ما معدات الوقاية الشخصية الأكثر ضرورة في موقع حادث مروري؟', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false),
  ((select id from s), 50, 'If a vehicle is unstable after a crash, paramedics should:', '["Enter immediately","Wait for fire/rescue support for stabilization","Pull patient quickly without precautions","Ignore vehicle condition"]'::jsonb, 1, 'المركبة غير المستقرة — المائلة على جانبها، أو المستندة إلى حاجز، أو الواقفة على منحدر أو فوق مركبة أخرى — قد تنزلق أو تتدحرج بمجرّد دخول شخص إليها أو تغيّر توزيع الوزن فيها. لذلك تُستدعى فرق الإنقاذ لتثبيتها بالإسفين والتدعيم بالأخشاب والدعامات والحبال وتفريغ هواء الإطارات قبل أي دخول، ويُكتفى في الأثناء بالتواصل مع المصاب من موضع آمن وطمأنته. والدخول فوراً يعرّض المسعف للسحق ويحوّل الحادث الواحد إلى حادثين. وسحب المريض بسرعة دون احتياطات لا يُبرَّر إلا أمام خطر داهم كحريق مشتعل، بينما تجاهل حالة المركبة نفيٌ صريح لأول خطوة في سلامة الموقع. المعلومة المفتاحية: لا قدم داخل مركبة غير مثبّتة — التثبيت أولاً، ثم الوصول، ثم الاستخلاص.', 'An unstable vehicle, one resting on its side, leaning against a barrier, perched on a slope or on top of another car, can slide or roll the moment someone climbs in or the weight distribution changes. Rescue crews are therefore called to stabilize it with chocks, cribbing, struts, lines and tire deflation before any entry, while contact with the patient is maintained verbally from a safe position. Entering immediately risks crushing the medic and turns one incident into two. Dragging the patient out without precautions is justified only by an immediate danger such as active fire, while ignoring the vehicle''s condition plainly denies the first step of scene safety. Takeaway: no foot enters an unstabilized vehicle, so stabilize first, then access, then extricate.', 'إذا كانت المركبة غير مستقرة بعد الحادث، فعلى المسعفين:', '{}'::jsonb, 'سلامة الموقع والحوادث المرورية', false, false, false);
  insert into amusq.subjects (name, color, icon, descr, topics, exam_date, published, free, ord)
insert into amusq.questions
  (subject_id, ord, q, options, answer, expl_ar, expl_en, translation, mnemonic, topic, derived, opts_built, important)
values
  ((select id from s), 1, 'يُعد الابتكار التسويقي من الأساليـب التسويقية في علم التسويق حيث يعمل على:', '["عدم تنمية الأفكار الجديدة","خلق أفكار مبتكرة وعدم المفاضلة بينها","يساعد ببناء رسالة قوية وغير مميزة عن الدور الذي تقوم به الشركة وأهدافها","تنمية الأفكار الجديدة وخلق أفكار مبتكرة والمفاضلة بينها ويساعد ببناء رسالة قوية ومميزة عن الدور الذي تقوم به الشركة وأهدافها"]'::jsonb, 3, 'الخيار الرابع هو الوحيد الذي يجمع وظائف الابتكار التسويقي كاملة: تنمية الأفكار الجديدة وخلقها والمفاضلة بينها وبناء رسالة قوية ومميزة. أما الخيارات الثلاثة الأخرى فهي النص نفسه بعد قلبه بالنفي: عدم تنمية الأفكار، وعدم المفاضلة بينها، ورسالة غير مميزة. المعلومة المفتاحية: الابتكار التسويقي أربع وظائف إيجابية متتالية، وأي خيار يُدخل عليها نفياً يكون خاطئاً بالضرورة.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 2, 'إن الابتكار التسويقي على ارتباط وثيق:', '["بالقدرات العقلية والتفكير المبتكر للأفراد التي تمكنه من إنتاج أفكار خلاقة","يرفع الأسعار للسلع والخدمات","التسليم في أوقات متأخرة عن المتفق عليه","الابتكار التسويقي دوره محدود في إنتاج أفكار خلاقة"]'::jsonb, 0, 'الارتباط الوثيق للابتكار التسويقي هو بالقدرات العقلية والتفكير المبتكر للأفراد التي تمكّنه من إنتاج أفكار خلاقة. ورفع الأسعار والتسليم المتأخر نتائج سلبية لا علاقة لها بجوهر الابتكار، والخيار الأخير يقلب المعنى بالنفي حين يجعل دور الابتكار محدوداً. المعلومة المفتاحية: مصدر الابتكار التسويقي هو العقل البشري والتفكير المبتكر للأفراد.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 3, 'يعتمد نجاح المشاريع الصغيرة والمتوسطة على:', '["على نجاح النشاط التسويقي لها الذي يساهم في اكتشاف رغبات العملاء","المنظمات تتنافس لتقديم المنتجات","حل المشاكل بالاعتماد على الخبرات","الاستمرار بالأساليب التقليدية"]'::jsonb, 0, 'نجاح المشاريع الصغيرة والمتوسطة مرهون بنجاح نشاطها التسويقي لأنه هو الذي يكتشف رغبات العملاء. أما التنافس بين المنظمات فهو وصف للسوق لا سبب للنجاح، والاعتماد على الخبرات وحدها والاستمرار بالأساليب التقليدية نقيض الابتكار المطلوب. المعلومة المفتاحية: مفتاح النجاح هو النشاط التسويقي الكاشف لرغبات العملاء، لا التقليد ولا الأساليب التقليدية.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 4, 'إن أبعاد الابتكار التسويقي تعتمد اعتماداً مباشراً على المزيج التسويقي ومنها:', '["الابتكار في المنتج والتسعير والترويج والتوزيع","الابتكار في التسعير والمنتج","الابتكار في الترويج والتسعير","الابتكار في الترويج والمنتج"]'::jsonb, 0, 'أبعاد الابتكار التسويقي أربعة مستمدة من المزيج التسويقي: المنتج والتسعير والترويج والتوزيع، فالخيار الأول هو الأشمل. أما الخيارات الثلاثة الباقية فكل منها يذكر بُعدين فقط ويُسقط الباقي، وأشهرها إسقاط التوزيع. المعلومة المفتاحية: احفظها بمفتاح مُتّت (منتج، تسعير، ترويج، توزيع) واختر دائماً الخيار الجامع للأربعة.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 5, 'يُعد الترويج من الأبعاد التي تشكل أهمية بالغة إذا:', '["إن التسعير يتمتع بحساسية عالية","أن الأفراد والجماعات في إطار إداري واجتماعي","تم استغلالها كما يجب","إذا لم يكن الاتصال فعالاً"]'::jsonb, 2, 'شرط الأهمية البالغة للترويج هو أن يتم استغلاله كما يجب، فالجواب هو الخيار الثالث لا الأول. حساسية التسعير خاصية بُعد آخر أُقحمت هنا للتشويش، والأفراد والجماعات في إطار إداري واجتماعي عبارة من فصل القيادة، والخيار الأخير مبني على النفي إذ يجعل عدم فعالية الاتصال شرطاً للأهمية وهو عكس المقصود. المعلومة المفتاحية: انتبه أن الإجابة الصحيحة هنا ليست الخيار الأول، والشرط هو حسن الاستغلال.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 6, 'إن التسعير يتمتع بحساسية عالية لأنه:', '["يخضع للتقييم من قبل العميل","من قبل الابتكار في المنتج","من قبل الابتكار في الترويج","في التوزيع"]'::jsonb, 0, 'سبب الحساسية العالية للتسعير هو خضوعه المباشر للتقييم من قبل العميل، فهو البُعد الذي يلمسه المشتري ويقارن به. أما الخيارات الثلاثة الأخرى فتحيل إلى أبعاد أخرى من المزيج التسويقي (المنتج والترويج والتوزيع) ولا تعلل حساسية السعر. المعلومة المفتاحية: التسعير حساس لأن العميل هو من يقيّمه.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 7, 'إن للتسويق مزيج من مجموعة من العناصر من أهمها:', '["حاجات ورغبات","مبادئ المدونة التربوية","المبادئ الإدارية","مبادئ المدونة الأخلاقية"]'::jsonb, 0, 'أهم عناصر المزيج التسويقي هي الحاجات والرغبات لأنها منطلق أي نشاط تسويقي. أما المدونة التربوية والمبادئ الإدارية والمدونة الأخلاقية فهي مفاهيم من حقول أخرى أُقحمت كمشتتات ولا تُعد عناصر للمزيج التسويقي. المعلومة المفتاحية: التسويق يبدأ من حاجات العميل ورغباته، لا من المدونات والمبادئ.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 8, 'عملية التبادل بين عناصر المزيج التسويقي هي مبنية على:', '["رسالة تربوية","أن يكون هناك طرفين (بائع ومشتري)","نشاطات اجتماعية","نشاطات ثقافية"]'::jsonb, 1, 'عملية التبادل تفترض وجود طرفين هما البائع والمشتري، فهذا شرطها الأساسي والجواب هو الخيار الثاني. أما الرسالة التربوية والنشاطات الاجتماعية والثقافية فهي سياقات خارج العملية التبادلية التسويقية. المعلومة المفتاحية: لا تبادل بلا طرفين، والإجابة الصحيحة هنا ليست الخيار الأول.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 9, 'إن إدخال منتجات وخدمات جديدة ومبتكرة بين الحين والآخر:', '["يطور من قدرة الشركة على تحقيق الميزة التنافسية في السوق","القائد الاستراتيجي","مسؤول الجودة","القائد الإداري"]'::jsonb, 0, 'إدخال منتجات وخدمات جديدة ومبتكرة بشكل دوري يطوّر قدرة الشركة على تحقيق الميزة التنافسية في السوق، وهو ثمرة الابتكار في المنتج. أما القائد الاستراتيجي ومسؤول الجودة والقائد الإداري فهي مسميات وظيفية من فصل القيادة لا تصلح إجابة عن أثر إدخال المنتجات. المعلومة المفتاحية: ثمرة الابتكار في المنتج هي الميزة التنافسية، واستبعد فوراً أي خيار من فصل آخر.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 10, 'من متطلبات الابتكار التسويقي:', '["متطلبات غير متعلقة بإدارة العاملين في التسويق","متطلبات خاصة بجدوى وتقييم الابتكار التسويقي","متطلبات خاصة بمستوى المعلومات غير المرتدة","متطلبات تنظيمية وإدارية وتسويقية لا تعزز من قيمة المنتج"]'::jsonb, 1, 'من متطلبات الابتكار التسويقي المتطلبات الخاصة بجدوى الابتكار وتقييمه، فالجواب هو الخيار الثاني. والخيارات الأخرى كلها صيغ منفية للمتطلبات الصحيحة: متطلبات غير متعلقة بإدارة العاملين، ومعلومات غير مرتدة بدل المعلومات المرتدة، ومتطلبات لا تعزز قيمة المنتج بدل أن تعززها. المعلومة المفتاحية: امسح الخيارات المنفية أولاً فيتبقى الخيار الصحيح، والإجابة هنا ليست الأولى.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 11, 'إن عملية الابتكار التسويقي عملية صعبة بحاجة أن تكون الإدارة:', '["واعية للمتطلبات الواجب أخذها بعين الاعتبار","واعية للتطورات الحاصلة في السوق على المدى البعيد","معرفة الأسلوب الابتكاري الذي لا يدعم مركزها التنافسي","الابتكار في المنتج والتسعير وعدم التوزيع"]'::jsonb, 0, 'صعوبة الابتكار التسويقي تستلزم إدارة واعية للمتطلبات الواجب أخذها بعين الاعتبار. والخيار الثاني يقيّد الوعي بالمدى البعيد فقط وهو تخصيص غير صحيح، والثالث مقلوب بالنفي إذ يطلب معرفة الأسلوب الذي لا يدعم المركز التنافسي، والرابع يحذف التوزيع من أبعاد المزيج بصيغة عدم التوزيع. المعلومة المفتاحية: الوعي المطلوب هو وعي بمتطلبات الابتكار كلها، وحذار من صيغتي لا يدعم وعدم.', '', '', '{}'::jsonb, 'الابتكار التسويقي (الفصل السادس)', false, false, false),
  ((select id from s), 12, 'الابتكار الحكومي أضحى اليوم مؤشراً:', '["عدم التغلب على الحواجز الجمركية","للمقارنة بين بلد وآخر","الخوارزميات التنبؤية للتعلم الآلي","الشبكات الاجتماعية"]'::jsonb, 1, 'الابتكار الحكومي صار مؤشراً تُقارَن به الدول فيما بينها، فالجواب هو الخيار الثاني. أما عدم التغلب على الحواجز الجمركية فصياغة منفية مقلوبة، والخوارزميات التنبؤية والشبكات الاجتماعية أدوات تقنية لا مؤشرات مقارنة بين الدول. المعلومة المفتاحية: الابتكار الحكومي مؤشر للمقارنة بين بلد وآخر، والإجابة الصحيحة هنا ليست الخيار الأول.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 13, 'يُعرف الابتكار الحكومي بأنه:', '["التعليم والبحث العلمي","التعليم والثقافة","خدمة جديدة أو محسنة بشكل كبير في القطاع العام","مجمل العمليات"]'::jsonb, 2, 'تعريف الابتكار الحكومي هو خدمة جديدة أو محسنة بشكل كبير في القطاع العام، فالجواب هو الخيار الثالث. والتعليم والبحث العلمي والتعليم والثقافة مجالات قطاعية لا تعريفات، وعبارة مجمل العمليات فضفاضة لا تحدد الجدة ولا التحسين ولا القطاع العام. المعلومة المفتاحية: التعريف يقوم على ثلاثة قيود معاً: خدمة، جديدة أو محسّنة بشكل كبير، في القطاع العام.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 14, 'من الأنشطة التي يشملها الابتكار الحكومي:', '["الخدمات","الإدارة والخدمات والعمليات","المواطن الخبير","توسيع نطاق العمل"]'::jsonb, 1, 'أنشطة الابتكار الحكومي ثلاثة معاً: الإدارة والخدمات والعمليات، فالخيار الثاني هو الأشمل. أما الخدمات وحدها فجزء ناقص من الإجابة، والمواطن الخبير وتوسيع نطاق العمل مفهومان آخران لا يمثلان قائمة الأنشطة. المعلومة المفتاحية: احفظها بمفتاح إخع (إدارة، خدمات، عمليات) واحذر من الخيار الجزئي الصحيح ظاهرياً.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 15, 'الجيل الجديد من الخدمات ينعكس مثلاً عبر الحكومة الرقمية التي تجعل من:', '["التقنيات الرقمية جزءاً متكاملاً من استراتيجيات تحديثها","الحكومة التجريبية","الحكومة غير الرقمية","تبني استراتيجيات"]'::jsonb, 0, 'الحكومة الرقمية تجعل التقنيات الرقمية جزءاً متكاملاً من استراتيجيات تحديثها، وهذا جوهر الجيل الجديد من الخدمات. أما الحكومة التجريبية فمفهوم مغاير، والحكومة غير الرقمية قلب للمعنى بالنفي وهو تناقض صريح مع نص السؤال، وعبارة تبني استراتيجيات ناقصة لا تحدد ماذا يُتبنى. المعلومة المفتاحية: دمج التقنيات الرقمية في صلب استراتيجية التحديث هو ما يعرّف الحكومة الرقمية.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 16, 'تبني استراتيجية للابتكار الحكومي في أي دولة يسعى ذلك في العموم إلى تحقيق أهداف من أهمها:', '["لا تجدد الثقة بالحكومة","يجعل الحكومة تتسم بالانسيابية","تخفض التكاليف ولكن ليس في الوقت","لا تساهم في تعزيز القدرة التنافسية"]'::jsonb, 1, 'من أهم أهداف استراتيجية الابتكار الحكومي أن تجعل الحكومة تتسم بالانسيابية، فالجواب هو الخيار الثاني. والخيارات الثلاثة الأخرى نموذج صريح لفخ النفي: لا تجدد الثقة، وتخفض التكاليف لكن ليس الوقت، ولا تساهم في تعزيز القدرة التنافسية، وكلها عكس الأهداف الحقيقية. المعلومة المفتاحية: أهداف الابتكار الحكومي كلها إيجابية (انسيابية، تجديد ثقة، خفض تكلفة ووقت، تعزيز تنافسية) فامسح كل خيار منفي.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 17, 'تجدد الثقة بالحكومة يكون من خلال:', '["تبسيط الإجراءات الإدارية","تنفيذ التغييرات","تجديد وتعزيز العلاقات بين الإدارات والعاملين","إلغاء القوانين"]'::jsonb, 0, 'تجديد الثقة بالحكومة يتحقق عبر تبسيط الإجراءات الإدارية لأنه ما يلمسه المواطن مباشرة. وتنفيذ التغييرات عبارة عامة لا تحدد الوسيلة، وتجديد العلاقات بين الإدارات والعاملين شأن داخلي لا يمس ثقة الجمهور، وإلغاء القوانين مبالغة مرفوضة إذ المطلوب تبسيط الإجراءات لا إلغاء التشريعات. المعلومة المفتاحية: تبسيط الإجراءات لا إلغاء القوانين هو طريق تجديد الثقة.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 18, 'إن من أبرز مبررات التوجه نحو الابتكار الحكومي من طرف الحكومات هي:', '["تحسين الأداء ورفع الكفاءة والفعالية","تعزيز القدرة غير التنافسية","تخفيض التكاليف ورفع الأعباء التي كانت تتحملها الدولة","تسريع وصول الخدمات للعاملين"]'::jsonb, 0, 'أبرز مبررات التوجه نحو الابتكار الحكومي هو تحسين الأداء ورفع الكفاءة والفعالية. والخيار الثاني مقلوب بالنفي إذ يقول القدرة غير التنافسية بدل التنافسية، والثالث يقول رفع الأعباء والصواب تخفيفها، والرابع يوجّه الخدمات للعاملين بدل المواطنين. المعلومة المفتاحية: المبررات تدور على تحسين الأداء والكفاءة والفعالية، وتذكر أن تبديل كلمة واحدة (غير، رفع، العاملين) يقلب الخيار إلى خطأ.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 19, 'إن من الخصائص التنظيمية المصاحبة للريادة الاستراتيجية في القطاع العام التي تميز المنظمات الريادية في القطاع العام مثل:', '["التركيز على العميل والعمليات الفعالة","القيود على الموظفين","القيود على المكافآت","الأفراد"]'::jsonb, 0, 'الخصائص التنظيمية المميزة للمنظمات الريادية في القطاع العام هي التركيز على العميل والعمليات الفعالة. أما القيود على الموظفين والقيود على المكافآت فهما من المعوقات لا الخصائص الريادية، وكلمة الأفراد وحدها عامة لا تصف خاصية تنظيمية. المعلومة المفتاحية: الريادة تعني انفتاحاً على العميل وفعالية في العمليات، وكل خيار يبدأ بكلمة قيود ينتمي إلى المعوقات.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 20, 'من المعوقات للريادة الاستراتيجية:', '["المنظمات","السياسات والإجراءات المعقدة","وجود قائد على قمة الهرم","الأفراد والمجتمعات"]'::jsonb, 1, 'أبرز معوقات الريادة الاستراتيجية هو تعقّد السياسات والإجراءات، فالجواب هو الخيار الثاني. وكلمتا المنظمات والأفراد والمجتمعات ألفاظ عامة لا تصف معوقاً بعينه، ووجود قائد على قمة الهرم عامل تنظيمي طبيعي لا يُعد معوقاً في ذاته. المعلومة المفتاحية: التعقيد الإجرائي هو العائق، والحل المقابل له هو تبسيط الإجراءات، والإجابة هنا ليست الخيار الأول.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 21, 'لا بد للحكومة الرقمية أن تأخذ في الاعتبار العديد من العوامل منها:', '["اختيار تكنولوجيا غير حديثة","فهم احتياجات الناس","خدمات بسيطة وبديهية لا تؤدي إلى فعالية ونجاح","خدمات عالية المستوى على المدى القريب"]'::jsonb, 1, 'من أهم عوامل نجاح الحكومة الرقمية فهم احتياجات الناس، فالجواب هو الخيار الثاني. والخياران الأول والثالث مقلوبان بالنفي: تكنولوجيا غير حديثة بدل الحديثة، وخدمات لا تؤدي إلى فعالية بدل أن تؤدي إليها، والرابع يحصر الخدمات بالمدى القريب والصواب المدى البعيد. المعلومة المفتاحية: الحكومة الرقمية تبدأ من المستفيد وتقوم على تكنولوجيا حديثة وأفق بعيد.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 22, 'حددت عوامل أساسية متداخلة يمكنها أن تفتح باب الابتكار منها:', '["التغلب على الحواجز الاقتصادية والاستفادة من الأفكار","تمكين ثقافة لا تدعم الابتكار","الاستفادة من أفكار المواطنين والأشخاص الذين يطرحونها في غير مجال الابتكار","وضع وتبني الأفكار البسيطة التي لا تستدعي تحمل التكاليف المرتفعة"]'::jsonb, 0, 'العوامل التي تفتح باب الابتكار تشمل التغلب على الحواجز الاقتصادية والاستفادة من الأفكار. والخيارات الأخرى مصاغة بالنفي أو بالتقييد الخاطئ: ثقافة لا تدعم الابتكار، وأفكار مطروحة في غير مجال الابتكار، وحصر التبني بالأفكار البسيطة قليلة التكلفة. المعلومة المفتاحية: فتح باب الابتكار يقوم على إزالة الحواجز والاستفادة من كل الأفكار لا على تصفيتها أو تقييدها.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 23, 'إن الحكومات حول العالم تسعى جاهدة إلى استخدام:', '["التقنيات الرقمية الجديدة والناشئة بطرق مبتكرة لتعزيز أساليب تقديم خدماتها","التغلب على الحواجز الاقتصادية","تحليل البيانات","وضع البرامج التقليدية"]'::jsonb, 0, 'الحكومات تسعى إلى استخدام التقنيات الرقمية الجديدة والناشئة بطرق مبتكرة لتعزيز أساليب تقديم خدماتها، وهذا هو الخيار الجامع. أما التغلب على الحواجز الاقتصادية فعامل من عوامل فتح باب الابتكار لا ما تسعى الحكومات لاستخدامه، وتحليل البيانات أداة جزئية، ووضع البرامج التقليدية نقيض الابتكار. المعلومة المفتاحية: الكلمات الدالة هي الجديدة والناشئة وبطرق مبتكرة، وأي خيار فيه تقليدي مرفوض.', '', '', '{}'::jsonb, 'الابتكار الحكومي والريادة في القطاع العام (الفصل السابع)', false, false, false),
  ((select id from s), 24, 'البحث عن صفات أو سمات القادة يعود إلى:', '["إلى قرون مضت","إلى عام 2000","إلى عام 1999","إلى عام 1975"]'::jsonb, 0, 'البحث في صفات القادة وسماتهم قديم يعود إلى قرون مضت لا إلى تاريخ حديث محدد. لذلك فالسنوات المذكورة في الخيارات الأخرى (2000 و1999 و1975) كلها تواريخ حديثة لا تناسب قِدم هذا الاهتمام. المعلومة المفتاحية: متى وجدت الأسئلة خياراً واحداً عاماً وقديماً مقابل ثلاث سنوات حديثة متقاربة فالغالب أن الصحيح هو العام القديم.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 25, 'القيادة الابتكارية هي أحد الأساليب:', '["القيادية الحديثة المعاصرة","للمقارنة بين بلد وآخر","التقليدية","الشبكات الاجتماعية"]'::jsonb, 0, 'القيادة الابتكارية أسلوب من الأساليب القيادية الحديثة المعاصرة. أما المقارنة بين بلد وآخر فهي صفة الابتكار الحكومي في الفصل السابع أُقحمت هنا، والتقليدية نقيض الابتكار تماماً، والشبكات الاجتماعية مفهوم تقني لا صلة له بتصنيف الأساليب القيادية. المعلومة المفتاحية: الابتكار مقترن دائماً بالحداثة والمعاصرة، فلا يجتمع مع وصف تقليدي.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 26, 'القيادة الابتكارية تتميز:', '["بقدرتها على زيادة القدرات التنافسية للمنظمة وتطوير أدائها","نتيجة التغيرات والتطورات","عاجزة عن جعل المنظمة قادرة على المنافسة","بأنها تقليدية"]'::jsonb, 0, 'ما يميز القيادة الابتكارية قدرتها على زيادة القدرات التنافسية للمنظمة وتطوير أدائها. والخيار الثاني يذكر سبب النشأة لا وجه التميز، والثالث مقلوب بالنفي إذ يصفها بالعجز عن المنافسة، والرابع يصفها بالتقليدية وهو ضد تعريفها. المعلومة المفتاحية: القيادة الابتكارية تُقاس بأثرها التنافسي والتطويري، وكل خيار سلبي أو تقليدي مستبعد.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 27, 'الابتكار في مؤداه:', '["عملية خلق أفكار جديدة ووضعها موضع التنفيذ","في حالة من الانتظار لتنفيذها","موضع التنفيذ بدون تخطيط","إقصائها من عملية التنفيذ"]'::jsonb, 0, 'الابتكار في مؤداه عملية خلق أفكار جديدة ووضعها موضع التنفيذ، فهو شقان: الخلق ثم التنفيذ. والخيارات الأخرى تعطل أحد الشقين: الانتظار يؤجل التنفيذ، والتنفيذ بدون تخطيط يفقده الانضباط، والإقصاء من التنفيذ نفي صريح للشق الثاني. المعلومة المفتاحية: فكرة بلا تنفيذ ليست ابتكاراً، والابتكار خلق وتنفيذ معاً.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 28, 'تكمن أهمية القيادة من أنها:', '["حلقة الوصل بين العاملين وبين خطط المنظمة وتصوراتها","بيئة الأعمال المتفاعلة","الاستراتيجية التنظيمية فقط","وسيلة للضغط على الموظفين"]'::jsonb, 0, 'أهمية القيادة أنها حلقة الوصل بين العاملين وبين خطط المنظمة وتصوراتها. وبيئة الأعمال المتفاعلة سياق لا وظيفة، وحصرها بالاستراتيجية التنظيمية فقط تضييق خاطئ بدلالة كلمة فقط، ووصفها بأنها وسيلة للضغط على الموظفين قلب سلبي لمعناها. المعلومة المفتاحية: أهمية القيادة = حلقة الوصل، وميّزها عن مصادر قوتها وعن خصائصها وأركانها.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 29, 'إن موضوع القيادة يعد من أبرز الموضوعات وأهمها في مجال:', '["التكنولوجيا","الاتصال","الإدارة كعملية","موضع التنفيذ المتقطع"]'::jsonb, 2, 'موضوع القيادة من أبرز موضوعات الإدارة كعملية، فالجواب هو الخيار الثالث. والتكنولوجيا والاتصال مجالان آخران قد ترتبط بهما القيادة لكنها لا تُصنَّف ضمنهما، وعبارة موضع التنفيذ المتقطع مأخوذة من سياق الابتكار ولا معنى لها هنا. المعلومة المفتاحية: القيادة إحدى وظائف الإدارة كعملية، والإجابة الصحيحة هنا ليست الخيار الأول.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 30, 'القيادة تعتمد على أربعة أركان منها:', '["الأتباع والأقران","الاختيار","البيئة المحيطة بهذه المتغيرات والقائد والهدف والأتباع","الخصائص"]'::jsonb, 2, 'أركان القيادة أربعة: القائد والهدف والأتباع والبيئة المحيطة بهذه المتغيرات، والخيار الثالث وحده يجمعها. أما الأتباع والأقران فناقص ويُدخل الأقران وهم ليسوا ركناً، والاختيار والخصائص كلمتان مفردتان لا تمثلان الأركان الأربعة. المعلومة المفتاحية: احفظها بمفتاح قهأب (قائد، هدف، أتباع، بيئة) واختر الخيار الجامع، فالإجابة هنا ليست الأولى.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 31, 'من خصائص القيادة:', '["القيادة نشاط وعدم حركة","القيادة تؤثر في الأفراد والجماعات","القيادة ليست تعاون","القيادة دافع نحو تبني الأهداف السهلة غير المرنة"]'::jsonb, 1, 'من خصائص القيادة أنها تؤثر في الأفراد والجماعات، فالجواب هو الخيار الثاني. والخيارات الباقية نموذج مكثف لفخ النفي: نشاط وعدم حركة والصواب نشاط وحركة، وليست تعاون والصواب أنها تعاون، والأهداف السهلة غير المرنة والصواب الأهداف المرنة. المعلومة المفتاحية: خصائص القيادة كلها إيجابية (تأثير، حركة، تعاون، مرونة)، فامسح كل خيار يحمل نفياً.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 32, 'أهمية القيادة تكمن في:', '["أن القيادة حلقة الوصل بين العاملين وبين خطط المؤسسة وتصوراتها المستقبلية","القيادة لا تنصهر في داخلها طاقة المفاهيم والسياسات والإجراءات","أنها قيادة المؤسسة من أجل تحقيق الأهداف غير المرسومة","تعميم القوى الإيجابية والتسليم بالجوانب السلبية"]'::jsonb, 0, 'أهمية القيادة أنها حلقة الوصل بين العاملين وبين خطط المؤسسة وتصوراتها المستقبلية، وهي الصيغة نفسها المتكررة في المنهج. والخيارات الأخرى مقلوبة بالنفي أو بالسلب: لا تنصهر بدل تنصهر، والأهداف غير المرسومة بدل المرسومة، والتسليم بالجوانب السلبية بدل معالجتها. المعلومة المفتاحية: أهمية القيادة سؤال متكرر وجوابه الثابت حلقة الوصل، فلا تخلطه بمصادر القوة أو الخصائص.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false),
  ((select id from s), 33, 'إن مصادر قوة القيادة تكمن في:', '["السلطة الرسمية وقوة التغلب","قوة التأثير والسلطة الرسمية البسيطة","القائد والسلطة الرسمية","السلطة الرسمية وقوة التأثير"]'::jsonb, 3, 'مصادر قوة القيادة اثنان: السلطة الرسمية وقوة التأثير، فالجواب هو الخيار الرابع. والخيار الأول يستبدل قوة التأثير بقوة التغلب، والثاني يضعّف السلطة بوصفها البسيطة، والثالث يجعل القائد نفسه مصدراً وهو صاحب القوة لا مصدرها. المعلومة المفتاحية: انتبه جيداً فالإجابة هنا هي الخيار الأخير، والفرق بين الخيارات كلمة واحدة فقط، وميّز مصادر القوة عن أركان القيادة وعن أهميتها.', '', '', '{}'::jsonb, 'القيادة الابتكارية (الفصل الثامن)', false, false, false);
