-- ═══ الإسعاف الطبي المتخصص لحالات التسمم · 45 سؤالًا ═══
delete from amusq.subjects where name = 'الإسعاف الطبي المتخصص لحالات التسمم';
with s as (
  values ('الإسعاف الطبي المتخصص لحالات التسمم', 'subject-4', '☠️', 'تغطي هذه المادة التعامل قبل المستشفوي مع حالات التسمّم الدوائي والنباتي، وتربط بين آلية عمل المادة السامّة والصورة السريرية التي يراها المسعف أمامه: النبض، الضغط، الحدقة، الوعي، ودرجة الحرارة. تدور المحاور الكبرى حول أربعة أعمدة: الأعشاب والمستحضرات الطبيعية وما تحمله من سُمّية حقيقية وتداخلات دوائية، وأدوية القلب والأوعية بأصنافها، والمهلوسات والمواد النفسية، والمسكنات ومضادات الالتهاب غير الستيرويدية مع السالسيلات. أكثر النقاط تكرارًا في الأسئلة: القفازيّة والدفلى بوصفهما مصدرًا للغليكوزيدات القلبية وتطابق صورتهما مع تسمّم الديجوكسين ورؤية الأصفر والأخضر؛ والتفريق بين حاصرات بيتا وحاصرات قنو', '["الأعشاب والمستحضرات الطبيعية","أدوية القلب والأوعية","المهلوسات والمواد النفسية","المسكنات ومضادات الالتهاب","المبادئ العامة للتعامل مع التسمم"]'::jsonb, '2026-08-27T09:00:00+03:00'::timestamptz, true, true, 0)
  returning id
)

-- ═══ الإسعاف الطبي المتخصص للحالات التنفسية الطارئة · 64 سؤالًا ═══
delete from amusq.subjects where name = 'الإسعاف الطبي المتخصص للحالات التنفسية الطارئة';
with s as (
  values ('الإسعاف الطبي المتخصص للحالات التنفسية الطارئة', 'subject-2', '🫁', 'تغطي هذه المادة الطوارئ التنفسية الأكثر شيوعًا في العمل الإسعافي، بدءًا من أمراض المجرى الهوائي السفلي الانسدادية وانتهاءً بإصابات الجنبة والاختناقات عند الأطفال. تبدأ المادة بالربو بوصفه اضطرابًا التهابيًا مزمنًا ذا انسداد عكوس، مع تفريق دقيق بين الاستجابة المبكرة التي تستجيب لموسعات القصبات والاستجابة المتأخرة التي تحتاج ستيرويدات قشرية. ثم ينتقل المحور إلى الانسداد الرئوي المزمن بشقيه: النفاخ وفقدان المرونة وتدمير الأسناخ، مقابل التهاب القصبات المزمن وفرط إفراز المخاط، وما يترتب عليهما من قلب رئوي واحتقان وريدي. أما الالتهابات فتشمل ذات الرئة بأنواعها المكتسبة من المجتمع والمستشفى والاستنشا', '["الربو","الانسداد الرئوي المزمن","الالتهابات الرئوية والقصيبات","استرواح الصدر وإصابات الجنبة","المجرى الهوائي عند الأطفال والانسداد","الوذمة الرئوية والانصمام الرئوي"]'::jsonb, '2026-08-29T09:00:00+03:00'::timestamptz, true, false, 1)
  returning id
)

-- ═══ اتخاذ القرارات السريرية الذكية للإسعاف الطبي المتخصص · 60 سؤالًا ═══
delete from amusq.subjects where name = 'اتخاذ القرارات السريرية الذكية للإسعاف الطبي المتخصص';
with s as (
  values ('اتخاذ القرارات السريرية الذكية للإسعاف الطبي المتخصص', 'subject-3', '🧠', 'تتناول هذه المادة المهارات غير التقنية التي تحدّد جودة الأداء في المواقف الإسعافية الحرجة، وهي مهارات لا تقل أهمية عن المهارات اليدوية مثل تأمين المجرى الهوائي أو الإنعاش القلبي الرئوي. المحور الأول هو الوعي الظرفي بمستوياته الثلاثة: الإدراك ثم الفهم ثم التوقّع، مع التركيز على ما يُضعفه كالإرهاق والضغط النفسي، وعلى أبرز مؤشرات فقدانه وهو رؤية النفق . المحور الثاني هو العمل الجماعي : مراحل تكوين الفريق الأربع (التشكيل، الخلاف، التنظيم، الأداء)، وتوزيع الأدوار بوضوح لمنع التكرار والمهام المنسية، والدعم المتبادل بين الأعضاء، والوعي الظرفي المشترك. المحور الثالث هو التواصل والتفويض : التواصل المغل', '["الوعي الظرفي","العمل الجماعي ومراحل تكوين الفريق","التواصل والتفويض","التفكير النقدي والاستدلال السريري","القيادة والتّبعية وأولويات التدخل"]'::jsonb, '2026-08-30T09:00:00+03:00'::timestamptz, true, false, 2)
