)

-- ═══ السلامة الصحية · 50 سؤالًا ═══
delete from amusq.subjects where name = 'السلامة الصحية';
with s as (
  values ('السلامة الصحية', 'subject-5', '🛡️', 'تتناول هذه المادة سلامة المسعف نفسه قبل سلامة المريض: كيف يقرأ الموقع، ومتى يدخل ومتى ينتظر، وما الوقاية الشخصية التي تناسب كل خطر. القاعدة الحاكمة لكل أسئلتها واحدة: سلامة المنقذ أولًا ، فالمسعف المصاب يتحوّل من حلٍّ إلى ضحية إضافية. المحور الأول المواد الخطرة : مناطق الموقع الثلاث ومتى يجوز دخول المنطقة الساخنة، ومستويات الوقاية الشخصية من A إلى D، ودور المسعف عند مستوى التوعية وهو التعرّف والاستدعاء لا المعالجة الميدانية للتسرّب، وتسلسل الرعاية الثابت: الإبعاد عن المصدر ثم إزالة التلوّث ثم علاج الأعراض. المحور الثاني مراحل الإنقاذ الفني بترتيبها: الاستطلاع، ضبط المخاطر، تثبيت المركبة، الوصو', '["المواد الخطرة والتعرّض الكيميائي","مراحل عمليات الإنقاذ الفنية","الإنقاذ المائي والغرق","سلامة الموقع والحوادث المرورية"]'::jsonb, '2026-08-30T09:00:00+03:00'::timestamptz, true, false, 3)
  returning id
)

